def _canonical_newton_broad_phase(value: Any) -> str:
    """Return a process-stable Newton broad-phase identifier."""

    if isinstance(value, str):
        return value.strip().lower()
    type_name = type(value).__name__.lower()
    return next(
        (name for name in ("explicit", "sap", "nxn") if name in type_name),
        type_name,
    )


