def _sample_hs005_reset_offsets(
    random_state: np.random.RandomState,
    *,
    randomize: bool,
) -> np.ndarray:
    """Sample seeded XY/yaw offsets for both manipulated HS005 objects."""

    for _attempt in range(32):
        if randomize:
            bottle_xy_offset = random_state.uniform(
                -_HS005_BOTTLE_RESET_XY_JITTER,
                _HS005_BOTTLE_RESET_XY_JITTER,
            )
            bottle_yaw = float(random_state.uniform(-8.0, 8.0))
            brush_xy_offset = random_state.uniform(
                -_HS005_BRUSH_RESET_XY_JITTER,
                _HS005_BRUSH_RESET_XY_JITTER,
            )
            brush_yaw = float(random_state.uniform(-10.0, 10.0))
        else:
            bottle_xy_offset = np.zeros(2, dtype=np.float64)
            bottle_yaw = 0.0
            brush_xy_offset = np.zeros(2, dtype=np.float64)
            brush_yaw = 0.0
        bottle_xy = _HS005_BOTTLE_RESET_XY + bottle_xy_offset
        brush_xy = _HS005_BRUSH_STABLE_RESET_POSE_XYZW[:2] + brush_xy_offset
        if (
            np.all(
                np.abs(bottle_xy - _HS005_BOTTLE_RESET_XY)
                <= _HS005_BOTTLE_RESET_XY_JITTER + 1.0e-12
            )
            and np.all(
                np.abs(brush_xy - _HS005_BRUSH_STABLE_RESET_POSE_XYZW[:2])
                <= _HS005_BRUSH_RESET_XY_JITTER + 1.0e-12
            )
            and float(np.linalg.norm(bottle_xy - brush_xy)) >= 0.20
            and float(np.linalg.norm(bottle_xy)) <= 0.65
            and float(np.linalg.norm(brush_xy)) <= 0.65
        ):
            return np.asarray(
                [
                    *bottle_xy_offset,
                    bottle_yaw,
                    *brush_xy_offset,
                    brush_yaw,
                ],
                dtype=np.float64,
            )
    raise RuntimeError("HS005 could not sample a supported reachable reset in 32 attempts")
