_B03_NEWTON_TASK_COLLIDER_COUNT = 9
_B03_NEWTON_HAND_COLLIDER_COUNT = 52
# The detailed Wuji MJCF gives all 26 colliders on each hand a rubber-like
# contact profile.  The analytic primitive replacement used by Isaac/Newton
# keeps the geometry but otherwise falls back to friction=(1, .005, .0001),
# condim=3 and priority=0.  Restore the source profile explicitly for B03 so
# the light peg and socket can be held without any kinematic grasp assist.
_B03_NEWTON_HAND_SLIDING_FRICTION = 3.0
_B03_NEWTON_HAND_TORSIONAL_FRICTION = 0.5
_B03_NEWTON_HAND_ROLLING_FRICTION = 0.02
_B03_NEWTON_HAND_CONTACT_DIMENSION = 4
_B03_NEWTON_HAND_CONTACT_PRIORITY = 1
