def _physx_solver_iteration_caps(task_name: str) -> tuple[int, int]:
    """Return the stable single-environment solver caps."""

    if task_name == "eval_flex03_pack_pillow":
        # Match the pillow's 64-iteration FEM solve. The 255-iteration solve
        # retained contact jitter that never passed the formal origin gate.
        return (64, 4)

    # D02 previously doubled both caps to compensate for overlapping reset
    # poses.  Those overlaps are now removed geometrically.  Keeping 128/8
    # makes GPU PhysX repeatedly grow its temporary collision workspace while
    # finalizing the microwave articulation, so the first reset can appear to
    # hang before teleoperation is ready.  The shared 64/4 caps resolve the
    # authored contacts without that allocator churn.
    # D03's 20 g target can be constrained by several driven fingertips at
    # once.  Give the velocity solve enough iterations to share those impulses
    # instead of concentrating the correction in one contact point.
    if task_name in {"t35_rotate_propeller", "t28_place_tableware"}:
        # Match YCB03's articulated landing-gear contacts and YCB06's thin
        # utensils at 64/16. The default velocity ceiling silently clips
        # the actor request and leaves small supported contacts chattering.
        return (64, 16)
    if task_name == ycb09.TASK_NAME:
        # Preserve the thin glass foot's actor iterations in the scene solve.
        return (_YCB09_SOLVER_POSITION_ITERATIONS, _YCB09_SOLVER_VELOCITY_ITERATIONS)
    if task_name == "bench320_hs014_bottle_stabilized_cap_opening":
        return (64, 8)
    if task_name in _d20_stages.TASK_NAMES:
        # The tall selected bottle needs an eight-iteration velocity solve
        # across its base contacts. The actor requests 64/8 locally; keep the
        # scene ceiling high enough that PhysX does not silently clip it.
        return (64, 8)
    velocity_iteration_8_tasks = {"t21_pass_block", xy1.TASK_NAME}
    return (64, 8) if task_name in velocity_iteration_8_tasks else (64, 4)


