    def _configure_ycb01_physics(self, sim_utils) -> int:
        """Keep the freely rolling ball responsive and the YCB posts stable.

        The YCB MJCF uses a MuJoCo three-term friction tuple.  Isaac's
        PhysX importer does not preserve that tuple as a rolling-resistance
        model, so the resulting default pair can bleed almost all of a
        finger flick in a few frames.  Author the measured mass/geometry from
        the MJCF, then bind a low-dissipation PhysX material only to this
        task's analytic sphere.
        """
        if self._stage is None or self.task_name != YCB01_TASK_NAME:
            return 0
        tuned = self._configure_named_reset_stability(
            sim_utils,
            (YCB01_BALL_NAME,),
            linear_damping=_YCB01_BALL_LINEAR_DAMPING,
            angular_damping=_YCB01_BALL_ANGULAR_DAMPING,
            sleep_threshold=_YCB01_BALL_SLEEP_THRESHOLD,
            warning_label="YCB01 ball",
        )
        tuned += self._configure_named_reset_stability(
            sim_utils,
            YCB01_GATE_BODY_NAMES,
            linear_damping=0.12,
            angular_damping=0.80,
            sleep_threshold=0.005,
            warning_label="YCB01 gate",
        )
        if self._physics_backend != "physx":
            return tuned

        from pxr import PhysxSchema, UsdPhysics, UsdShade

        ball_prim = self._find_rigid_body_prim(YCB01_BALL_NAME)
        if ball_prim is None:
            self._add_task_state_warning(
                "Could not tune YCB01 ball: rigid body is unavailable"
            )
            return tuned

        ball_path = str(ball_prim.GetPath())
        # The converter can leave the free-body root as an instance.  Expand
        # only the rigid-body root before binding the task-local material.
        # Applying PhysX collision schemas to instance-proxy descendants is
        # unsafe on the GPU backend (it can invalidate the narrowphase); the
        # root binding is inherited by the analytic child collider and keeps
        # the stage instancing-safe.
        sim_utils.make_uninstanceable(ball_path, stage=self._stage)
        sim_utils.update_stage()
        ball_prim = self._stage.GetPrimAtPath(ball_path)
        material_cfg = sim_utils.RigidBodyMaterialCfg(
            static_friction=_YCB01_BALL_STATIC_FRICTION,
            dynamic_friction=_YCB01_BALL_DYNAMIC_FRICTION,
            restitution=_YCB01_BALL_RESTITUTION,
            # The table's generic material is intentionally high friction;
            # use the lower ball value for this pair, while leaving the
            # table's behavior unchanged for all other tasks.
            friction_combine_mode="min",
            restitution_combine_mode="max",
        )
        material_cfg.func(_YCB01_BALL_MATERIAL_PATH, material_cfg)
        sim_utils.bind_physics_material(
            ball_path,
            _YCB01_BALL_MATERIAL_PATH,
            stage=self._stage,
            stronger_than_descendants=True,
        )

        rigid_api = PhysxSchema.PhysxRigidBodyAPI(ball_prim)
        if not rigid_api:
            rigid_api = PhysxSchema.PhysxRigidBodyAPI.Apply(ball_prim)
        for getter_name, creator_name, value in (
            ("GetEnableCCDAttr", "CreateEnableCCDAttr", True),
            ("GetSolverPositionIterationCountAttr", "CreateSolverPositionIterationCountAttr", 16),
            ("GetSolverVelocityIterationCountAttr", "CreateSolverVelocityIterationCountAttr", 4),
            ("GetMaxDepenetrationVelocityAttr", "CreateMaxDepenetrationVelocityAttr", 2.0),
        ):
            attribute = getattr(rigid_api, getter_name)()
            if not attribute or not attribute.IsValid():
                attribute = getattr(rigid_api, creator_name)()
            attribute.Set(value)

        mass_api = UsdPhysics.MassAPI(ball_prim)
        if not mass_api:
            mass_api = UsdPhysics.MassAPI.Apply(ball_prim)
        mass_attr = mass_api.GetMassAttr()
        if not mass_attr or not mass_attr.IsValid():
            mass_attr = mass_api.CreateMassAttr()
        mass_attr.Set(0.058)
        return tuned + 1

