    def _configure_b01_pitcher_base_physics(self, sim_utils) -> tuple[int, bool]:
        """Keep B01's free pitcher base physical but stable for one-hand seating."""
        if self._stage is None or self.task_name not in {
            "t04_cover_pitcher",
            xy5.TASK_NAME,
            "c07_pitcher_pour_cup",
        }:
            return 0, False

        base_prim = self._find_rigid_body_prim("019_pitcher_base")
        if base_prim is None:
            self._add_task_state_warning(
                "Could not tune 019_pitcher_base stability: rigid body is unavailable"
            )
            return 0, False
        base_path = str(base_prim.GetPath())
        sim_utils.make_uninstanceable(base_path, stage=self._stage)
        sim_utils.update_stage()
        base_prim = self._stage.GetPrimAtPath(base_path)

        physics_cfg = _B01_PITCHER_BASE_PHYSICS
        material_path = "/World/PhysicsMaterials/HandsOnPitcherBaseStability"
        material_cfg = sim_utils.RigidBodyMaterialCfg(
            static_friction=physics_cfg.static_friction,
            dynamic_friction=physics_cfg.dynamic_friction,
            restitution=0.0,
            friction_combine_mode="average",
            restitution_combine_mode="min",
        )
        material_cfg.func(material_path, material_cfg)
        sim_utils.bind_physics_material(
            base_path,
            material_path,
            stage=self._stage,
            stronger_than_descendants=True,
        )

        from pxr import PhysxSchema, Usd, UsdPhysics, UsdShade

        bound_colliders = 0
        for prim in Usd.PrimRange(base_prim):
            if not prim.HasAPI(UsdPhysics.CollisionAPI):
                continue
            if physics_cfg.contact_offset is not None:
                physx_collision_api = PhysxSchema.PhysxCollisionAPI(prim)
                if not physx_collision_api:
                    physx_collision_api = PhysxSchema.PhysxCollisionAPI.Apply(prim)
                contact_attr = physx_collision_api.GetContactOffsetAttr()
                if not contact_attr or not contact_attr.IsValid():
                    contact_attr = physx_collision_api.CreateContactOffsetAttr()
                contact_attr.Set(float(physics_cfg.contact_offset))
                if physics_cfg.rest_offset is not None:
                    rest_attr = physx_collision_api.GetRestOffsetAttr()
                    if not rest_attr or not rest_attr.IsValid():
                        rest_attr = physx_collision_api.CreateRestOffsetAttr()
                    rest_attr.Set(float(physics_cfg.rest_offset))
            targets = (
                UsdShade.MaterialBindingAPI(prim)
                .GetDirectBindingRel("physics")
                .GetTargets()
            )
            if any(str(target) == material_path for target in targets):
                bound_colliders += 1

        mass_api = UsdPhysics.MassAPI(base_prim)
        if not mass_api:
            mass_api = UsdPhysics.MassAPI.Apply(base_prim)
        mass_attr = mass_api.GetMassAttr()
        if not mass_attr or not mass_attr.IsValid():
            mass_attr = mass_api.CreateMassAttr()
        mass_attr.Set(float(physics_cfg.mass))

        rigid_body_api = PhysxSchema.PhysxRigidBodyAPI(base_prim)
        if not rigid_body_api:
            rigid_body_api = PhysxSchema.PhysxRigidBodyAPI.Apply(base_prim)
        linear_damping_attr = rigid_body_api.GetLinearDampingAttr()
        if not linear_damping_attr or not linear_damping_attr.IsValid():
            linear_damping_attr = rigid_body_api.CreateLinearDampingAttr()
        linear_damping_attr.Set(float(physics_cfg.linear_damping))
        angular_damping_attr = rigid_body_api.GetAngularDampingAttr()
        if not angular_damping_attr or not angular_damping_attr.IsValid():
            angular_damping_attr = rigid_body_api.CreateAngularDampingAttr()
        angular_damping_attr.Set(float(physics_cfg.angular_damping))

        if bound_colliders == 0:
            self._add_task_state_warning(
                "Could not tune 019_pitcher_base friction: no collider accepted the material"
            )
        return bound_colliders, True

    def _configure_a01_reset_stability(self, sim_utils) -> int:
        """Restore A01 source dynamics and settle its reset contacts."""
        if self._stage is None or self.task_name not in {"t26_place_fruit_in_bucket", xy3.TASK_NAME}:
            return 0

        from pxr import Gf, PhysxSchema, Usd, UsdPhysics

        from .task_preview import _A01_ANALYTIC_FRUIT_INERTIALS

        tuned = 0
        for name in _A01_RESET_STABILITY_BODIES:
            prim = self._find_rigid_body_prim(name)
            if prim is None or (
                hasattr(prim, "IsValid") and not prim.IsValid()
            ):
                message = (
                    "Could not tune A01 reset stability: "
                    f"{name} rigid body is unavailable"
                )
                self._add_task_state_warning(message)
                raise RuntimeError(message)
            path = str(prim.GetPath())
            sim_utils.make_uninstanceable(path, stage=self._stage)
            sim_utils.update_stage()
            prim = self._stage.GetPrimAtPath(path)
            if prim is None or (
                hasattr(prim, "IsValid") and not prim.IsValid()
            ):
                message = (
                    "Could not tune A01 reset stability: "
                    f"{name} rigid body disappeared after uninstancing"
                )
                self._add_task_state_warning(message)
                raise RuntimeError(message)

            source_inertial = _A01_ANALYTIC_FRUIT_INERTIALS.get(name)
            if source_inertial is not None:
                # Conversion can leave these fields at 0/-inf sentinels even
                # when the prepared MJCF is explicit.  Author all four mass
                # properties on the uninstanced runtime prim so PhysX never
                # falls back to collider density or a cache-dependent value.
                mass_api = UsdPhysics.MassAPI(prim)
                if not mass_api:
                    mass_api = UsdPhysics.MassAPI.Apply(prim)
                center_of_mass = tuple(
                    float(value) for value in source_inertial["pos"].split()
                )
                diagonal_inertia = tuple(
                    float(value)
                    for value in source_inertial["diaginertia"].split()
                )
                principal_axes = tuple(
                    float(value) for value in source_inertial["quat"].split()
                )
                mass_api.CreateMassAttr().Set(
                    float(source_inertial["mass"])
                )
                mass_api.CreateCenterOfMassAttr().Set(
                    Gf.Vec3f(*center_of_mass)
                )
                mass_api.CreateDiagonalInertiaAttr().Set(
                    Gf.Vec3f(*diagonal_inertia)
                )
                mass_api.CreatePrincipalAxesAttr().Set(
                    Gf.Quatf(
                        principal_axes[0],
                        Gf.Vec3f(*principal_axes[1:]),
                    )
                )
            collider_count = 0
            for collision_prim in Usd.PrimRange(prim):
                if not collision_prim.HasAPI(UsdPhysics.CollisionAPI):
                    continue
                collider_count += 1
                collision_api = PhysxSchema.PhysxCollisionAPI(collision_prim)
                if not collision_api:
                    collision_api = PhysxSchema.PhysxCollisionAPI.Apply(
                        collision_prim
                    )
                collision_api.CreateContactOffsetAttr().Set(
                    float(_A01_CONTACT_OFFSET)
                )
                collision_api.CreateRestOffsetAttr().Set(
                    float(_A01_REST_OFFSET)
                )
            if collider_count == 0:
                message = (
                    "Could not tune A01 reset stability: "
                    f"{name} rigid body has no colliders"
                )
                self._add_task_state_warning(message)
                raise RuntimeError(message)
            rigid_api = PhysxSchema.PhysxRigidBodyAPI(prim)
            if not rigid_api:
                rigid_api = PhysxSchema.PhysxRigidBodyAPI.Apply(prim)
            linear_damping = (
                2.0 if self.task_name == xy3.TASK_NAME else _A01_RESET_LINEAR_DAMPING
            )
            angular_damping = (
                8.0 if self.task_name == xy3.TASK_NAME else _A01_RESET_ANGULAR_DAMPING
            )
            for getter_name, creator_name, value in (
                ("GetLinearDampingAttr", "CreateLinearDampingAttr", linear_damping),
                ("GetAngularDampingAttr", "CreateAngularDampingAttr", angular_damping),
                ("GetSleepThresholdAttr", "CreateSleepThresholdAttr", _A01_RESET_SLEEP_THRESHOLD),
            ):
                attribute = getattr(rigid_api, getter_name)()
                if not attribute or not attribute.IsValid():
                    attribute = getattr(rigid_api, creator_name)()
                attribute.Set(value)
            tuned += 1
        return tuned

    def _configure_a01_newton_contacts(self) -> tuple[int, int]:
        """Restore Newton's contact envelope on the complete A01 hand scene.

        Isaac's MJCF converter explicitly writes a zero Newton contact gap,
        which takes precedence over both Isaac Lab's Newton default and the
        PhysX contact offset authored by :meth:`_configure_a01_reset_stability`.
        Author the Newton-native value before ``ModelBuilder.add_usd`` so
        contacts are generated before a moving finger crosses a surface.
        """
        if (
            self._stage is None
            or self.task_name != "t26_place_fruit_in_bucket"
            or self._physics_backend != "newton"
        ):
            return 0, 0

        from pxr import Sdf, Usd, UsdPhysics

        required_task_groups = {
            "apple",
            "banana",
            "orange",
            "pear",
            "bucket",
            "table",
        }
        hand_sides = (
            ("right",)
            if self._direct_hand_control
            else ("right", "left")
        )
        # The detached Wuji asset intentionally omits the five proximal
        # link1 collision capsules; its palm collider covers that region.
        # Keep the full-arm requirement strict while matching the actual
        # collision topology used by direct physical replay.
        hand_links = range(2, 5) if self._direct_hand_control else range(1, 5)
        required_hand_names = {
            f"{side}_palm_link_col2"
            for side in hand_sides
        }
        required_hand_names.update(
            f"{side}_finger{finger}_link{link}_col2"
            for side in hand_sides
            for finger in range(1, 6)
            for link in hand_links
        )
        required_hand_names.update(
            f"{side}_finger{finger}_tip_link_col2"
            for side in hand_sides
            for finger in range(1, 6)
        )

        found_task_groups: set[str] = set()
        found_hand_names: set[str] = set()
        task_colliders = 0
        hand_colliders = 0

        roots = [
            ("task", _TASK_ROOT),
            *[
                (
                    "hand",
                    f"/World/HandsOnRobots/{side.capitalize()}Robot",
                )
                for side in hand_sides
            ],
        ]
        for kind, root_path in roots:
            root = self._stage.GetPrimAtPath(root_path)
            if root is None or (
                hasattr(root, "IsValid") and not root.IsValid()
            ):
                continue
            for prim in Usd.PrimRange(root):
                collision_api = UsdPhysics.CollisionAPI(prim)
                if not collision_api:
                    continue
                enabled_attr = collision_api.GetCollisionEnabledAttr()
                if (
                    enabled_attr
                    and enabled_attr.IsValid()
                    and enabled_attr.Get() is False
                ):
                    continue

                prim_name = str(prim.GetName())
                if kind == "task":
                    lower_path = str(prim.GetPath()).lower()
                    group = next(
                        (
                            candidate
                            for candidate in required_task_groups
                            if candidate in lower_path
                        ),
                        None,
                    )
                    if group is None:
                        continue
                    found_task_groups.add(group)
                    task_colliders += 1
                else:
                    if prim_name not in required_hand_names:
                        continue
                    found_hand_names.add(prim_name)
                    hand_colliders += 1

                contact_gap = prim.GetAttribute("newton:contactGap")
                if not contact_gap or not contact_gap.IsValid():
                    prim.ApplyAPI("NewtonCollisionAPI")
                    contact_gap = prim.GetAttribute("newton:contactGap")
                if not contact_gap or not contact_gap.IsValid():
                    contact_gap = prim.CreateAttribute(
                        "newton:contactGap",
                        Sdf.ValueTypeNames.Float,
                    )
                contact_gap.Set(float(_A01_NEWTON_CONTACT_GAP))

        missing_task_groups = sorted(required_task_groups - found_task_groups)
        missing_hand_names = sorted(required_hand_names - found_hand_names)
        if missing_task_groups or missing_hand_names:
            details = []
            if missing_task_groups:
                details.append(
                    "task=" + ",".join(missing_task_groups)
                )
            if missing_hand_names:
                details.append(
                    "hand=" + ",".join(missing_hand_names)
                )
            message = (
                "A01 Newton collision setup is incomplete ("
                + "; ".join(details)
                + ")"
            )
            self._add_task_state_warning(message)
            raise RuntimeError(message)

        return task_colliders, hand_colliders

    def _configure_b03_newton_hand_grasp_physics(self, sim_utils) -> int:
        """Restore the source Wuji contact profile on B03 primitive hands.

        Isaac's robot preparation replaces the detailed Wuji collision meshes
        with calibrated capsules and spheres.  Those primitive geoms do not
        carry the source MJCF's friction/condim/priority fields, so the
        converted Newton hand silently falls back to a much slicker material.
        Bind a B03-only material and author the source MuJoCo contact fields on
        every expected hand collider before Newton builds its model.
        """
        if (
            self._stage is None
            or self.task_name != "t09_insert_peg"
            or self._physics_backend != "newton"
        ):
            return 0

        from pxr import Sdf, Usd, UsdPhysics, UsdShade

        material_cfg = sim_utils.RigidBodyMaterialCfg(
            static_friction=_B03_NEWTON_HAND_SLIDING_FRICTION,
            dynamic_friction=_B03_NEWTON_HAND_SLIDING_FRICTION,
            restitution=0.0,
            friction_combine_mode="max",
            restitution_combine_mode="min",
        )
        material_cfg.func(
            _B03_NEWTON_HAND_MATERIAL_PATH,
            material_cfg,
        )
        material_prim = self._stage.GetPrimAtPath(
            _B03_NEWTON_HAND_MATERIAL_PATH
        )
        if material_prim is None or (
            hasattr(material_prim, "IsValid")
            and not material_prim.IsValid()
        ):
            raise RuntimeError("B03 Newton hand material was not created")

        newton_material_fields = (
            (
                "newton:torsionalFriction",
                _B03_NEWTON_HAND_TORSIONAL_FRICTION,
            ),
            (
                "newton:rollingFriction",
                _B03_NEWTON_HAND_ROLLING_FRICTION,
            ),
        )
        for attribute_name, value in newton_material_fields:
            attribute = material_prim.GetAttribute(attribute_name)
            if not attribute or not attribute.IsValid():
                try:
                    material_prim.ApplyAPI("NewtonMaterialAPI")
                except Exception:
                    # A headless USD stage may be authored before Kit loads
                    # the Newton schema plugin.  The namespaced attribute is
                    # still consumed when Newton later builds the model.
                    pass
                attribute = material_prim.GetAttribute(attribute_name)
            if not attribute or not attribute.IsValid():
                attribute = material_prim.CreateAttribute(
                    attribute_name,
                    Sdf.ValueTypeNames.Float,
                )
            attribute.Set(float(value))

        for attribute_name, expected in (
            (
                "physics:staticFriction",
                _B03_NEWTON_HAND_SLIDING_FRICTION,
            ),
            (
                "physics:dynamicFriction",
                _B03_NEWTON_HAND_SLIDING_FRICTION,
            ),
            *newton_material_fields,
        ):
            attribute = material_prim.GetAttribute(attribute_name)
            actual = (
                None
                if not attribute or not attribute.IsValid()
                else attribute.Get()
            )
            if actual is None or not np.isclose(float(actual), float(expected)):
                raise RuntimeError(
                    "B03 Newton hand material is incomplete: "
                    f"{attribute_name}={actual!r}, expected {expected!r}"
                )

        hand_sides = (
            ("right",)
            if self._direct_hand_control
            else ("right", "left")
        )
        hand_links = range(2, 5) if self._direct_hand_control else range(1, 5)
        required_hand_names = {
            f"{side}_palm_link_col2"
            for side in hand_sides
        }
        required_hand_names.update(
            f"{side}_finger{finger}_link{link}_col2"
            for side in hand_sides
            for finger in range(1, 6)
            for link in hand_links
        )
        required_hand_names.update(
            f"{side}_finger{finger}_tip_link_col2"
            for side in hand_sides
            for finger in range(1, 6)
        )

        source_contact_fields = (
            (
                "mjc:condim",
                Sdf.ValueTypeNames.Int,
                _B03_NEWTON_HAND_CONTACT_DIMENSION,
            ),
            (
                "mjc:priority",
                Sdf.ValueTypeNames.Int,
                _B03_NEWTON_HAND_CONTACT_PRIORITY,
            ),
            (
                "mjc:solref",
                Sdf.ValueTypeNames.DoubleArray,
                list(_B03_NEWTON_HAND_SOLREF),
            ),
            (
                "mjc:solimp",
                Sdf.ValueTypeNames.DoubleArray,
                list(_B03_NEWTON_HAND_SOLIMP),
            ),
        )
        bound_names: set[str] = set()
        for side in hand_sides:
            root_path = f"/World/HandsOnRobots/{side.capitalize()}Robot"
            root = self._stage.GetPrimAtPath(root_path)
            if root is None or (
                hasattr(root, "IsValid") and not root.IsValid()
            ):
                continue
            for prim in Usd.PrimRange(root):
                prim_name = str(prim.GetName())
                if prim_name not in required_hand_names:
                    continue
                collision_api = UsdPhysics.CollisionAPI(prim)
                if not collision_api:
                    continue
                enabled_attr = collision_api.GetCollisionEnabledAttr()
                if (
                    enabled_attr
                    and enabled_attr.IsValid()
                    and enabled_attr.Get() is False
                ):
                    continue

                prim_path = str(prim.GetPath())
                binding_result = sim_utils.bind_physics_material(
                    prim_path,
                    _B03_NEWTON_HAND_MATERIAL_PATH,
                    stage=self._stage,
                    stronger_than_descendants=True,
                )
                if binding_result is False:
                    continue
                targets = (
                    UsdShade.MaterialBindingAPI(prim)
                    .GetDirectBindingRel("physics")
                    .GetTargets()
                )
                if not any(
                    str(target) == _B03_NEWTON_HAND_MATERIAL_PATH
                    for target in targets
                ):
                    continue

                for attribute_name, value_type, value in source_contact_fields:
                    attribute = prim.GetAttribute(attribute_name)
                    if not attribute or not attribute.IsValid():
                        try:
                            prim.ApplyAPI("MjcCollisionAPI")
                        except Exception:
                            # The MJC schema can be registered after the USD
                            # scene is authored in headless Newton startup.
                            pass
                        attribute = prim.GetAttribute(attribute_name)
                    if not attribute or not attribute.IsValid():
                        attribute = prim.CreateAttribute(
                            attribute_name,
                            value_type,
                        )
                    attribute.Set(value)
                bound_names.add(prim_name)

        missing_hand_names = sorted(required_hand_names - bound_names)
        expected_hand_colliders = (
            21 if self._direct_hand_control else _B03_NEWTON_HAND_COLLIDER_COUNT
        )
        if missing_hand_names or len(bound_names) != expected_hand_colliders:
            message = (
                "B03 Newton hand material setup is incomplete: "
                f"bound={len(bound_names)}/{expected_hand_colliders}"
            )
            if missing_hand_names:
                message += "; missing=" + ",".join(missing_hand_names)
            self._add_task_state_warning(message)
            raise RuntimeError(message)

        return len(bound_names)

    def _configure_b03_newton_contacts(self) -> tuple[int, int]:
        """Author tight-fit Newton contact envelopes for B03.

        The MJCF converter writes a zero Newton gap on every collider.  That
        permits a fast Wuji finger to cross the narrow peg before Newton emits
        a contact candidate.  B03 cannot reuse A01's 10 mm per-shape envelope:
        the round peg has only about 2.4 mm of radial clearance in the socket.
        Keep the mating bodies at 0.5 mm each and give the source-driven hand
        a 4 mm candidate envelope.  ``contactGap`` only broadens speculative
        contact generation; it does not enlarge the physical hand solids.
        """
        if (
            self._stage is None
            or self.task_name != "t09_insert_peg"
            or self._physics_backend != "newton"
        ):
            return 0, 0

        from pxr import Sdf, Usd, UsdPhysics

        required_task_groups = {"peg", "socket", "table"}
        hand_sides = (
            ("right",)
            if self._direct_hand_control
            else ("right", "left")
        )
        # The canonical detached Wuji primitive intentionally leaves each
        # five-finger link1 capsule non-colliding; the palm box covers that
        # proximal region.  Full arm assets add those external colliders and
        # retain the stricter legacy requirement.
        hand_links = range(2, 5) if self._direct_hand_control else range(1, 5)
        required_hand_names = {
            f"{side}_palm_link_col2"
            for side in hand_sides
        }
        required_hand_names.update(
            f"{side}_finger{finger}_link{link}_col2"
            for side in hand_sides
            for finger in range(1, 6)
            for link in hand_links
        )
        required_hand_names.update(
            f"{side}_finger{finger}_tip_link_col2"
            for side in hand_sides
            for finger in range(1, 6)
        )

        found_task_groups: set[str] = set()
        found_hand_names: set[str] = set()
        task_colliders = 0
        hand_colliders = 0

        roots = [
            ("task", _TASK_ROOT),
            *[
                (
                    "hand",
                    f"/World/HandsOnRobots/{side.capitalize()}Robot",
                )
                for side in hand_sides
            ],
        ]
        for kind, root_path in roots:
            root = self._stage.GetPrimAtPath(root_path)
            if root is None or (
                hasattr(root, "IsValid") and not root.IsValid()
            ):
                continue
            for prim in Usd.PrimRange(root):
                collision_api = UsdPhysics.CollisionAPI(prim)
                if not collision_api:
                    continue
                enabled_attr = collision_api.GetCollisionEnabledAttr()
                if (
                    enabled_attr
                    and enabled_attr.IsValid()
                    and enabled_attr.Get() is False
                ):
                    continue

                prim_name = str(prim.GetName())
                if kind == "task":
                    lower_path = str(prim.GetPath()).lower()
                    if "industreal_tray_insert_round_peg_8mm" in lower_path:
                        group = "socket"
                        gap = _B03_NEWTON_SOCKET_CONTACT_GAP
                    elif "industreal_round_peg_8mm" in lower_path:
                        group = "peg"
                        gap = _B03_NEWTON_PEG_CONTACT_GAP
                    elif "table" in lower_path:
                        group = "table"
                        gap = _B03_NEWTON_TABLE_CONTACT_GAP
                    else:
                        continue
                    found_task_groups.add(group)
                    task_colliders += 1
                else:
                    if prim_name not in required_hand_names:
                        continue
                    found_hand_names.add(prim_name)
                    hand_colliders += 1
                    gap = _B03_NEWTON_HAND_CONTACT_GAP

                contact_gap = prim.GetAttribute("newton:contactGap")
                if not contact_gap or not contact_gap.IsValid():
                    prim.ApplyAPI("NewtonCollisionAPI")
                    contact_gap = prim.GetAttribute("newton:contactGap")
                if not contact_gap or not contact_gap.IsValid():
                    contact_gap = prim.CreateAttribute(
                        "newton:contactGap",
                        Sdf.ValueTypeNames.Float,
                    )
                contact_gap.Set(float(gap))

        missing_task_groups = sorted(required_task_groups - found_task_groups)
        missing_hand_names = sorted(required_hand_names - found_hand_names)
        if missing_task_groups or missing_hand_names:
            details = []
            if missing_task_groups:
                details.append("task=" + ",".join(missing_task_groups))
            if missing_hand_names:
                details.append("hand=" + ",".join(missing_hand_names))
            message = (
                "B03 Newton collision setup is incomplete ("
                + "; ".join(details)
                + ")"
            )
            self._add_task_state_warning(message)
            raise RuntimeError(message)

        expected_hand_colliders = (
            21 if self._direct_hand_control else _B03_NEWTON_HAND_COLLIDER_COUNT
        )
        if (
            task_colliders != _B03_NEWTON_TASK_COLLIDER_COUNT
            or hand_colliders != expected_hand_colliders
        ):
            message = (
                "B03 Newton collision topology changed: "
                f"task={task_colliders}/"
                f"{_B03_NEWTON_TASK_COLLIDER_COUNT}, "
                f"hand={hand_colliders}/"
                f"{expected_hand_colliders}"
            )
            self._add_task_state_warning(message)
            raise RuntimeError(message)

        return task_colliders, hand_colliders

    def _configure_a03_reset_stability(self, sim_utils) -> int:
        """Restore analytic-ball inertials and model physical rolling resistance."""
        if self._stage is None or self.task_name != "t24_place_ball_in_bowl":
            return 0

        from pxr import Gf, PhysxSchema, UsdPhysics

        tuned = 0
        for name in _A03_RESET_STABILITY_BODIES:
            prim = self._find_rigid_body_prim(name)
            if prim is None or (
                hasattr(prim, "IsValid") and not prim.IsValid()
            ):
                message = (
                    "Could not tune A03 reset stability: "
                    f"{name} rigid body is unavailable"
                )
                self._add_task_state_warning(message)
                raise RuntimeError(message)
            path = str(prim.GetPath())
            sim_utils.make_uninstanceable(path, stage=self._stage)
            # ``make_uninstanceable`` may recompose the subtree.  Resolve the
            # body again rather than authoring through a pre-recomposition
            # Prim handle; the live inertial A/B probe used this exact fresh
            # root and demonstrated zero integrated motion for all three balls.
            prim = self._stage.GetPrimAtPath(path)
            if prim is None or (
                hasattr(prim, "IsValid") and not prim.IsValid()
            ):
                message = (
                    "Could not tune A03 reset stability: "
                    f"{name} rigid body disappeared after uninstancing"
                )
                self._add_task_state_warning(message)
                raise RuntimeError(message)

            mass, radius = _A03_ANALYTIC_BALL_MASS_RADIUS[name]
            diagonal_inertia = 0.4 * float(mass) * float(radius) ** 2
            mass_api = UsdPhysics.MassAPI(prim)
            if not mass_api:
                mass_api = UsdPhysics.MassAPI.Apply(prim)
            mass_api.CreateMassAttr().Set(float(mass))
            mass_api.CreateCenterOfMassAttr().Set(Gf.Vec3f(0.0, 0.0, 0.0))
            mass_api.CreateDiagonalInertiaAttr().Set(
                Gf.Vec3f(
                    diagonal_inertia,
                    diagonal_inertia,
                    diagonal_inertia,
                )
            )
            mass_api.CreatePrincipalAxesAttr().Set(
                Gf.Quatf(1.0, Gf.Vec3f(0.0, 0.0, 0.0))
            )

            rigid_api = PhysxSchema.PhysxRigidBodyAPI(prim)
            if not rigid_api:
                rigid_api = PhysxSchema.PhysxRigidBodyAPI.Apply(prim)
            for getter_name, creator_name, value in (
                (
                    "GetLinearDampingAttr",
                    "CreateLinearDampingAttr",
                    _A03_RESET_LINEAR_DAMPING,
                ),
                (
                    "GetAngularDampingAttr",
                    "CreateAngularDampingAttr",
                    _A03_RESET_ANGULAR_DAMPING,
                ),
                (
                    "GetSleepThresholdAttr",
                    "CreateSleepThresholdAttr",
                    _A03_RESET_SLEEP_THRESHOLD,
                ),
            ):
                attribute = getattr(rigid_api, getter_name)()
                if not attribute or not attribute.IsValid():
                    attribute = getattr(rigid_api, creator_name)()
                attribute.Set(value)
            tuned += 1
        return tuned

    def _configure_ycb02_reset_stability(self, sim_utils) -> int:
        """Apply modest rolling damping without changing YCB mass or size."""
        if self._stage is None or self.task_name != ycb02.TASK_NAME:
            return 0
        return self._configure_named_reset_stability(
            sim_utils,
            (*ycb02.CUP_NAMES, *ycb02.BALL_NAMES),
            linear_damping=_YCB02_RESET_LINEAR_DAMPING,
            angular_damping=_YCB02_RESET_ANGULAR_DAMPING,
            sleep_threshold=_YCB02_RESET_SLEEP_THRESHOLD,
            warning_label="YCB02",
        )

    def _configure_ycb09_reset_stability(self, sim_utils) -> int:
        """Restore source inertials and let both YCB bodies sleep physically."""
        if self._stage is None or self.task_name != ycb09.TASK_NAME:
            return 0
        tuned = self._configure_named_reset_stability(
            sim_utils,
            _YCB09_RESET_STABILITY_BODIES,
            linear_damping=_YCB09_RESET_LINEAR_DAMPING,
            angular_damping=_YCB09_RESET_ANGULAR_DAMPING,
            sleep_threshold=_YCB09_RESET_SLEEP_THRESHOLD,
            warning_label="YCB09",
            # Each asset is a loose MJCF freejoint body, not a mechanism.  The
            # imported one-link articulation wrapper can keep its contact
            # island awake indefinitely and override rigid-body sleep.
            strip_redundant_articulation_root=True,
        )
        if tuned != len(_YCB09_SOURCE_INERTIALS):
            message = (
                "Could not restore all YCB09 source inertials: "
                f"found {tuned}/{len(_YCB09_SOURCE_INERTIALS)} bodies"
            )
            self._add_task_state_warning(message)
            raise RuntimeError(message)

        from pxr import Gf, UsdPhysics

        for name, source in _YCB09_SOURCE_INERTIALS.items():
            prim = self._find_rigid_body_prim(name)
            if prim is None or not prim.IsValid():
                message = f"Could not restore YCB09 source inertial for {name}"
                self._add_task_state_warning(message)
                raise RuntimeError(message)
            mass_api = UsdPhysics.MassAPI(prim)
            if not mass_api:
                mass_api = UsdPhysics.MassAPI.Apply(prim)
            mass_api.CreateMassAttr().Set(float(source["mass"]))
            mass_api.CreateCenterOfMassAttr().Set(
                Gf.Vec3f(*source["center_of_mass"])
            )
            mass_api.CreateDiagonalInertiaAttr().Set(
                Gf.Vec3f(*source["diagonal_inertia"])
            )
            principal_w, principal_x, principal_y, principal_z = source[
                "principal_axes_wxyz"
            ]
            mass_api.CreatePrincipalAxesAttr().Set(
                Gf.Quatf(
                    principal_w,
                    Gf.Vec3f(principal_x, principal_y, principal_z),
                )
            )
        return tuned

    def _configure_b05_clear_box_contacts(self, sim_utils) -> int:
        """Give every B05 box component the same narrow table contact shell."""
        if self._stage is None or self.task_name not in {"t03_cover_box", xy5.TASK_NAME}:
            return 0

        clear_box_prim = self._find_rigid_body_prim("Clear_Box")
        if clear_box_prim is None or (
            hasattr(clear_box_prim, "IsValid")
            and not clear_box_prim.IsValid()
        ):
            message = (
                "Could not tune B05 Clear_Box contacts: rigid body is unavailable"
            )
            self._add_task_state_warning(message)
            raise RuntimeError(message)

        path = str(clear_box_prim.GetPath())
        sim_utils.make_uninstanceable(path, stage=self._stage)
        sim_utils.update_stage()
        clear_box_prim = self._stage.GetPrimAtPath(path)
        if clear_box_prim is None or (
            hasattr(clear_box_prim, "IsValid")
            and not clear_box_prim.IsValid()
        ):
            message = (
                "Could not tune B05 Clear_Box contacts: rigid body "
                "disappeared after uninstancing"
            )
            self._add_task_state_warning(message)
            raise RuntimeError(message)

        from pxr import Gf, PhysxSchema, Usd, UsdPhysics

        # Newton-imported visual meshes retain CollisionAPI with collisions
        # disabled; they are not extra physical components of the box.
        collision_prims = [
            prim
            for prim in Usd.PrimRange(clear_box_prim)
            if prim.HasAPI(UsdPhysics.CollisionAPI)
            and (
                UsdPhysics.CollisionAPI(prim).GetCollisionEnabledAttr().Get()
                is not False
            )
        ]
        if len(collision_prims) != _B05_CLEAR_BOX_COLLIDER_COUNT:
            message = (
                "Could not tune B05 Clear_Box contacts: expected exactly "
                f"{_B05_CLEAR_BOX_COLLIDER_COUNT} colliders, found "
                f"{len(collision_prims)}"
            )
            self._add_task_state_warning(message)
            raise RuntimeError(message)

        # Restore the exact inertial compiled by MuJoCo.  Importing the
        # component meshes independently otherwise lets PhysX infer a
        # different body mass frame from its collider representation.
        mass_api = UsdPhysics.MassAPI(clear_box_prim)
        if not mass_api:
            mass_api = UsdPhysics.MassAPI.Apply(clear_box_prim)
        mass_api.CreateMassAttr().Set(float(_B05_CLEAR_BOX_MASS))
        mass_api.CreateCenterOfMassAttr().Set(
            Gf.Vec3f(*_B05_CLEAR_BOX_CENTER_OF_MASS)
        )
        mass_api.CreatePrincipalAxesAttr().Set(
            Gf.Quatf(
                _B05_CLEAR_BOX_PRINCIPAL_AXES_WXYZ[0],
                Gf.Vec3f(*_B05_CLEAR_BOX_PRINCIPAL_AXES_WXYZ[1:]),
            )
        )
        mass_api.CreateDiagonalInertiaAttr().Set(
            Gf.Vec3f(*_B05_CLEAR_BOX_DIAGONAL_INERTIA)
        )

        tuned = 0
        for collision_prim in collision_prims:
            collision_api = PhysxSchema.PhysxCollisionAPI(collision_prim)
            if not collision_api:
                collision_api = PhysxSchema.PhysxCollisionAPI.Apply(
                    collision_prim
                )
            collision_api.CreateContactOffsetAttr().Set(
                float(_B05_CONTACT_OFFSET)
            )
            collision_api.CreateRestOffsetAttr().Set(float(_B05_REST_OFFSET))
            tuned += 1
        return tuned

    def _configure_a06_reset_stability(self, sim_utils) -> int:
        """Restore A06's source rigid body and deterministic contact shell."""
        if self._stage is None or self.task_name != "t19_orient_cup_upright":
            return 0

        from pxr import Gf, PhysxSchema, Usd, UsdPhysics

        tuned = 0
        for name in _A06_RESET_STABILITY_BODIES:
            prim = self._find_rigid_body_prim(name)
            if prim is None:
                self._add_task_state_warning(
                    f"Could not tune A06 reset stability: {name} rigid body is unavailable"
                )
                continue
            path = str(prim.GetPath())
            sim_utils.make_uninstanceable(path, stage=self._stage)
            sim_utils.update_stage()
            prim = self._stage.GetPrimAtPath(path)

            # The MJCF importer drops the per-geom masses on this 27-piece
            # compound mesh.  Restore the compiled MuJoCo body inertial so
            # every reset seed has the same center of mass and angular
            # response as the source task.
            mass_api = UsdPhysics.MassAPI(prim)
            if not mass_api:
                mass_api = UsdPhysics.MassAPI.Apply(prim)
            mass_api.CreateMassAttr().Set(float(_A06_SOURCE_MASS))
            mass_api.CreateCenterOfMassAttr().Set(
                Gf.Vec3f(*_A06_SOURCE_CENTER_OF_MASS)
            )
            mass_api.CreateDiagonalInertiaAttr().Set(
                Gf.Vec3f(*_A06_SOURCE_DIAGONAL_INERTIA)
            )
            principal_w, principal_x, principal_y, principal_z = (
                _A06_SOURCE_PRINCIPAL_AXES_WXYZ
            )
            mass_api.CreatePrincipalAxesAttr().Set(
                Gf.Quatf(
                    principal_w,
                    Gf.Vec3f(principal_x, principal_y, principal_z),
                )
            )

            # PhysX otherwise derives a different default contact offset for
            # each convex piece from its individual bounds.  One shared shell
            # prevents the three-point table support from switching between
            # collider-specific separation distances.
            for collision_prim in Usd.PrimRange(prim):
                if not collision_prim.HasAPI(UsdPhysics.CollisionAPI):
                    continue
                collision_api = PhysxSchema.PhysxCollisionAPI(collision_prim)
                if not collision_api:
                    collision_api = PhysxSchema.PhysxCollisionAPI.Apply(
                        collision_prim
                    )
                collision_api.CreateContactOffsetAttr().Set(
                    float(_A06_CONTACT_OFFSET)
                )
                collision_api.CreateRestOffsetAttr().Set(float(_A06_REST_OFFSET))

            rigid_api = PhysxSchema.PhysxRigidBodyAPI(prim)
            if not rigid_api:
                rigid_api = PhysxSchema.PhysxRigidBodyAPI.Apply(prim)
            for getter_name, creator_name, value in (
                (
                    "GetLinearDampingAttr",
                    "CreateLinearDampingAttr",
                    _A06_RESET_LINEAR_DAMPING,
                ),
                (
                    "GetAngularDampingAttr",
                    "CreateAngularDampingAttr",
                    _A06_RESET_ANGULAR_DAMPING,
                ),
                (
                    "GetSleepThresholdAttr",
                    "CreateSleepThresholdAttr",
                    _A06_RESET_SLEEP_THRESHOLD,
                ),
            ):
                attribute = getattr(rigid_api, getter_name)()
                if not attribute or not attribute.IsValid():
                    attribute = getattr(rigid_api, creator_name)()
                attribute.Set(value)
            tuned += 1
        return tuned

    def _configure_ycb04_denest_materials(self, sim_utils) -> str:
        """Use low cup/cup friction and a separate real hand grip material."""
        from pxr import Usd, UsdPhysics

        material_paths = {
            "cup": "/World/PhysicsMaterials/HandsOnYCB04Cup",
            "hand": "/World/PhysicsMaterials/HandsOnYCB04Hand",
        }
        for kind, static, dynamic in (
            ("cup", _YCB04_CUP_STATIC_FRICTION, _YCB04_CUP_DYNAMIC_FRICTION),
            ("hand", _YCB04_HAND_STATIC_FRICTION, _YCB04_HAND_DYNAMIC_FRICTION),
        ):
            cfg = sim_utils.RigidBodyMaterialCfg(
                static_friction=static, dynamic_friction=dynamic,
                restitution=0.0, friction_combine_mode="max",
                restitution_combine_mode="min",
            )
            cfg.func(material_paths[kind], cfg)

        # Do not change table/arm/other-task materials or add contact assists.
        hand_colliders = 0
        for side in ("Right", "Left"):
            root_path = f"/World/HandsOnRobots/{side}Robot"
            root = self._stage.GetPrimAtPath(root_path)
            if not root.IsValid():
                continue
            sim_utils.make_uninstanceable(root_path, stage=self._stage)
            sim_utils.update_stage()
            root = self._stage.GetPrimAtPath(root_path)
            for prim in Usd.PrimRange(root):
                path = str(prim.GetPath())
                if not any(part in path.lower() for part in ("palm", "finger")):
                    continue
                if prim.HasAPI(UsdPhysics.RigidBodyAPI) or prim.HasAPI(UsdPhysics.CollisionAPI):
                    sim_utils.bind_physics_material(
                        path, material_paths["hand"], stage=self._stage,
                        stronger_than_descendants=True,
                    )
                    hand_colliders += int(prim.HasAPI(UsdPhysics.CollisionAPI))
        if not hand_colliders:
            raise RuntimeError("YCB04 denest material could not bind any hand colliders")
        return material_paths["cup"]

    def _configure_ycb04_reset_stability(self, sim_utils) -> int:
        """Restore source cup inertias and a narrow nested-contact shell."""
        if self._stage is None or self.task_name != "t41_sort_nested_cups":
            return 0

        from pxr import Gf, PhysxSchema, Usd, UsdPhysics

        tuned = self._configure_named_reset_stability(
            sim_utils,
            tuple(_YCB04_SOURCE_INERTIALS),
            linear_damping=_YCB04_RESET_LINEAR_DAMPING,
            angular_damping=_YCB04_RESET_ANGULAR_DAMPING,
            sleep_threshold=_YCB04_RESET_SLEEP_THRESHOLD,
            warning_label="YCB04",
        )
        if tuned <= 0:
            return 0

        cup_material_path = self._configure_ycb04_denest_materials(sim_utils)
        for name, source in _YCB04_SOURCE_INERTIALS.items():
            prim = self._find_rigid_body_prim(name)
            if prim is None:
                continue
            # Strong root binding overrides any importer/source material;
            # explicit collider bindings below also cover detached shapes.
            sim_utils.bind_physics_material(
                str(prim.GetPath()), cup_material_path, stage=self._stage,
                stronger_than_descendants=True,
            )
            mass_api = UsdPhysics.MassAPI(prim)
            if not mass_api:
                mass_api = UsdPhysics.MassAPI.Apply(prim)
            mass_api.CreateMassAttr().Set(float(source["mass"]))
            mass_api.CreateCenterOfMassAttr().Set(
                Gf.Vec3f(*source["center_of_mass"])
            )
            principal_w, principal_x, principal_y, principal_z = source[
                "principal_axes"
            ]
            mass_api.CreatePrincipalAxesAttr().Set(
                Gf.Quatf(
                    principal_w,
                    Gf.Vec3f(principal_x, principal_y, principal_z),
                )
            )
            mass_api.CreateDiagonalInertiaAttr().Set(
                Gf.Vec3f(*source["diagonal_inertia"])
            )

            for collision_prim in Usd.PrimRange(prim):
                if not collision_prim.HasAPI(UsdPhysics.CollisionAPI):
                    continue
                sim_utils.bind_physics_material(
                    str(collision_prim.GetPath()), cup_material_path,
                    stage=self._stage, stronger_than_descendants=True,
                )
                collision_api = PhysxSchema.PhysxCollisionAPI(collision_prim)
                if not collision_api:
                    collision_api = PhysxSchema.PhysxCollisionAPI.Apply(
                        collision_prim
                    )
                collision_api.CreateContactOffsetAttr().Set(
                    float(_YCB04_CONTACT_OFFSET)
                )
                collision_api.CreateRestOffsetAttr().Set(
                    float(_YCB04_REST_OFFSET)
                )
        return tuned

    def _configure_b04_stack_physics(self, sim_utils) -> tuple[int, int]:
        """Match stack friction/damping so a released tower settles.

        GEN5 deliberately reuses B04's stack predicates, but its package
        bodies are different rigid prims. Keep the shared tuning in one place
        and apply it to both families before the first PhysX reset.
        """
        stack_task = self.task_name in {"t44_stack_blocks", gen5.TASK_NAME}
        if self._stage is None or not stack_task:
            return 0, 0

        block_paths: dict[str, str] = {}
        stack_names = (
            gen5.BODY_NAMES if self.task_name == gen5.TASK_NAME
            else ("036_wood_block", "BuildingBlock017", "BuildingBlock018", "BuildingBlock019")
        )
        for name in stack_names:
            prim = self._find_rigid_body_prim(name)
            if prim is None:
                self._add_task_state_warning(
                    f"Could not tune stack physics: {name} rigid body is unavailable"
                )
                continue
            path = str(prim.GetPath())
            block_paths[name] = path
            sim_utils.make_uninstanceable(path, stage=self._stage)
        if not block_paths:
            return 0, 0
        sim_utils.update_stage()

        material_cfgs = {
            "base": sim_utils.RigidBodyMaterialCfg(
                static_friction=_STACK_BASE_STATIC_FRICTION,
                dynamic_friction=_STACK_BASE_DYNAMIC_FRICTION,
                restitution=0.0,
                friction_combine_mode="max",
                restitution_combine_mode="min",
            ),
            "small": sim_utils.RigidBodyMaterialCfg(
                static_friction=_STACK_SMALL_STATIC_FRICTION,
                dynamic_friction=_STACK_SMALL_DYNAMIC_FRICTION,
                restitution=0.0,
                friction_combine_mode="max",
                restitution_combine_mode="min",
            ),
        }
        material_paths = {
            "base": "/World/PhysicsMaterials/HandsOnStackBaseStability",
            "small": "/World/PhysicsMaterials/HandsOnStackSmallBlockStability",
        }
        for key, cfg in material_cfgs.items():
            cfg.func(material_paths[key], cfg)

        from pxr import PhysxSchema, Usd, UsdPhysics

        tuned_colliders = 0
        tuned_bodies = 0
        for name, path in block_paths.items():
            prim = self._stage.GetPrimAtPath(path)
            material_key = "base" if name in _STACK_BOTTOM_BLOCK_NAMES else "small"
            sim_utils.bind_physics_material(
                path,
                material_paths[material_key],
                stage=self._stage,
                stronger_than_descendants=True,
            )
            for descendant in Usd.PrimRange(prim):
                if not descendant.HasAPI(UsdPhysics.CollisionAPI):
                    continue
                collision_api = PhysxSchema.PhysxCollisionAPI(descendant)
                if not collision_api:
                    collision_api = PhysxSchema.PhysxCollisionAPI.Apply(descendant)
                contact_attr = collision_api.GetContactOffsetAttr()
                if not contact_attr or not contact_attr.IsValid():
                    contact_attr = collision_api.CreateContactOffsetAttr()
                contact_attr.Set(_STACK_CONTACT_OFFSET)
                rest_attr = collision_api.GetRestOffsetAttr()
                if not rest_attr or not rest_attr.IsValid():
                    rest_attr = collision_api.CreateRestOffsetAttr()
                rest_attr.Set(_STACK_REST_OFFSET)
                tuned_colliders += 1

            rigid_api = PhysxSchema.PhysxRigidBodyAPI(prim)
            if not rigid_api:
                rigid_api = PhysxSchema.PhysxRigidBodyAPI.Apply(prim)
            linear_attr = rigid_api.GetLinearDampingAttr()
            if not linear_attr or not linear_attr.IsValid():
                linear_attr = rigid_api.CreateLinearDampingAttr()
            linear_attr.Set(_STACK_LINEAR_DAMPING)
            angular_attr = rigid_api.GetAngularDampingAttr()
            if not angular_attr or not angular_attr.IsValid():
                angular_attr = rigid_api.CreateAngularDampingAttr()
            angular_attr.Set(
                _STACK_ANGULAR_DAMPING * 4.0
                if self.task_name == gen5.TASK_NAME
                else _STACK_ANGULAR_DAMPING
            )
            sleep_attr = rigid_api.GetSleepThresholdAttr()
            if not sleep_attr or not sleep_attr.IsValid():
                sleep_attr = rigid_api.CreateSleepThresholdAttr()
            sleep_attr.Set(_STACK_SLEEP_THRESHOLD)
            # Imported package meshes are small enough that a fast hand
            # release can cross a thin contact shell in one 120 Hz step.
            # Continuous collision plus extra solver iterations prevents the
            # visible carton penetration without changing its mesh.
            for getter, creator, value in (
                ("GetEnableCCDAttr", "CreateEnableCCDAttr", True),
                ("GetEnableSpeculativeCCDAttr", "CreateEnableSpeculativeCCDAttr", True),
                ("GetSolverPositionIterationCountAttr", "CreateSolverPositionIterationCountAttr", 32),
                ("GetSolverVelocityIterationCountAttr", "CreateSolverVelocityIterationCountAttr", 4),
            ):
                attr = getattr(rigid_api, getter)()
                if not attr or not attr.IsValid():
                    attr = getattr(rigid_api, creator)()
                attr.Set(value)
            if prim.HasAPI(PhysxSchema.PhysxContactReportAPI):
                contact_report_api = PhysxSchema.PhysxContactReportAPI.Get(
                    self._stage,
                    prim.GetPath(),
                )
            else:
                contact_report_api = PhysxSchema.PhysxContactReportAPI.Apply(prim)
            contact_report_api.CreateThresholdAttr().Set(0.0)
            tuned_bodies += 1

        if tuned_colliders == 0:
            self._add_task_state_warning(
                "Could not tune stack friction: no colliders were found"
            )
        return tuned_colliders, tuned_bodies

    def _configure_c01_wood_physics(self) -> bool:
        """Restore complete, finite C01 wood articulation physics."""
        if self._stage is None or self.task_name != "t08_hammer_nail":
            return False
        wood_prim = self._find_rigid_body_prim("wood")
        if wood_prim is None:
            self._add_task_state_warning(
                "Could not tune C01 wood mass: rigid body is unavailable"
            )
            return False

        from pxr import Gf, PhysxSchema, UsdPhysics

        mass_api = UsdPhysics.MassAPI(wood_prim)
        if not mass_api:
            mass_api = UsdPhysics.MassAPI.Apply(wood_prim)
        for getter, creator, value in (
            (
                mass_api.GetMassAttr,
                mass_api.CreateMassAttr,
                float(_C01_WOOD_MASS),
            ),
            (
                mass_api.GetCenterOfMassAttr,
                mass_api.CreateCenterOfMassAttr,
                Gf.Vec3f(*_C01_WOOD_CENTER_OF_MASS),
            ),
            (
                mass_api.GetDiagonalInertiaAttr,
                mass_api.CreateDiagonalInertiaAttr,
                Gf.Vec3f(*_C01_WOOD_DIAGONAL_INERTIA),
            ),
            (
                mass_api.GetPrincipalAxesAttr,
                mass_api.CreatePrincipalAxesAttr,
                Gf.Quatf(1.0, Gf.Vec3f(0.0)),
            ),
        ):
            attribute = getter()
            if not attribute or not attribute.IsValid():
                attribute = creator()
            attribute.Set(value)

        # The wood is an articulation root because the nail is a prismatic
        # child.  Rigid-body solver opinions alone do not override the
        # articulation's imported one-iteration/default-sleep settings, so
        # author both levels.  Damping remains ordinary wakeable physics and
        # is deliberately matched to the hammer in the same task.
        rigid_api = PhysxSchema.PhysxRigidBodyAPI(wood_prim)
        if not rigid_api:
            rigid_api = PhysxSchema.PhysxRigidBodyAPI.Apply(wood_prim)
        for getter_name, creator_name, value in (
            (
                "GetLinearDampingAttr",
                "CreateLinearDampingAttr",
                _C01_WOOD_LINEAR_DAMPING,
            ),
            (
                "GetAngularDampingAttr",
                "CreateAngularDampingAttr",
                _C01_WOOD_ANGULAR_DAMPING,
            ),
            (
                "GetSleepThresholdAttr",
                "CreateSleepThresholdAttr",
                _C01_WOOD_SLEEP_THRESHOLD,
            ),
            (
                "GetSolverPositionIterationCountAttr",
                "CreateSolverPositionIterationCountAttr",
                _C01_SOLVER_POSITION_ITERATIONS,
            ),
            (
                "GetSolverVelocityIterationCountAttr",
                "CreateSolverVelocityIterationCountAttr",
                _C01_SOLVER_VELOCITY_ITERATIONS,
            ),
        ):
            attribute = getattr(rigid_api, getter_name)()
            if not attribute or not attribute.IsValid():
                attribute = getattr(rigid_api, creator_name)()
            attribute.Set(value)

        if UsdPhysics.ArticulationRootAPI(wood_prim):
            articulation_api = PhysxSchema.PhysxArticulationAPI(wood_prim)
            if not articulation_api:
                articulation_api = PhysxSchema.PhysxArticulationAPI.Apply(
                    wood_prim
                )
            for getter_name, creator_name, value in (
                (
                    "GetSolverPositionIterationCountAttr",
                    "CreateSolverPositionIterationCountAttr",
                    _C01_SOLVER_POSITION_ITERATIONS,
                ),
                (
                    "GetSolverVelocityIterationCountAttr",
                    "CreateSolverVelocityIterationCountAttr",
                    _C01_SOLVER_VELOCITY_ITERATIONS,
                ),
                (
                    "GetSleepThresholdAttr",
                    "CreateSleepThresholdAttr",
                    _C01_WOOD_SLEEP_THRESHOLD,
                ),
            ):
                attribute = getattr(articulation_api, getter_name)()
                if not attribute or not attribute.IsValid():
                    attribute = getattr(articulation_api, creator_name)()
                attribute.Set(value)
        return True

    def _configure_08_hammer_nail_physics(self, sim_utils: Any) -> bool:
        """Make C01 impacts physical, insertable, and resistant to tunneling."""
        if self._stage is None or self.task_name != "t08_hammer_nail":
            return False

        from pxr import PhysxSchema, Usd, UsdPhysics

        # MJCF collision groups are commonly imported as instance proxies.
        # Deinstance only the hammer and wood/nail roots before authoring CCD
        # and per-shape contact shells.
        task_paths: dict[str, str] = {}
        for object_name in ("hammer", "nail"):
            prim = self._find_prim(object_name)
            if prim is None or not prim.IsValid():
                continue
            top_prim = prim
            while top_prim.GetParent().IsValid() and str(
                top_prim.GetParent().GetPath()
            ) != _TASK_ROOT:
                top_prim = top_prim.GetParent()
            top_path = str(top_prim.GetPath())
            if top_path.startswith(f"{_TASK_ROOT}/"):
                task_paths[object_name] = top_path

        for path in sorted(set(task_paths.values())):
            sim_utils.make_uninstanceable(path, stage=self._stage)
        if task_paths:
            sim_utils.update_stage()
            # Cached prim handles may refer to the old instance proxies.
            for object_name in ("hammer", "nail"):
                self._prim_cache.pop(object_name, None)

        task_root = self._stage.GetPrimAtPath(_TASK_ROOT)
        nail_joint = next(
            (
                prim
                for prim in Usd.PrimRange(task_root)
                if prim.GetName() == "nail_slide_joint"
                and prim.IsA(UsdPhysics.PrismaticJoint)
            ),
            None,
        )
        if nail_joint is None:
            self._add_task_state_warning(
                "Could not tune C01 nail slide joint: joint is unavailable"
            )
            return False

        drive = UsdPhysics.DriveAPI.Get(nail_joint, "linear")
        if not drive:
            drive = UsdPhysics.DriveAPI.Apply(nail_joint, "linear")
        drive.GetTargetPositionAttr().Set(_D08_BUTTON_UP_TARGET)
        drive.GetTargetVelocityAttr().Set(0.0)
        drive.GetStiffnessAttr().Set(_C01_NAIL_JOINT_STIFFNESS)
        drive.GetDampingAttr().Set(_C01_NAIL_JOINT_DAMPING)
        drive.GetMaxForceAttr().Set(_C01_NAIL_JOINT_MAX_FORCE)
        nail_joint.GetAttribute("physxJoint:jointFriction").Set(
            _C01_NAIL_JOINT_FRICTION
        )

        if nail_joint.HasAPI(PhysxSchema.JointStateAPI, "linear"):
            joint_state = PhysxSchema.JointStateAPI.Get(nail_joint, "linear")
        else:
            joint_state = PhysxSchema.JointStateAPI.Apply(nail_joint, "linear")
        joint_state.GetPositionAttr().Set(0.0)
        joint_state.GetVelocityAttr().Set(0.0)

        hammer_prim = self._find_rigid_body_prim("hammer")
        nail_prim = self._find_rigid_body_prim("nail")
        if hammer_prim is None or nail_prim is None:
            self._add_task_state_warning(
                "Could not tune C01 hammer/nail bodies: a rigid body is unavailable"
            )
            return False
        for prim, mass in (
            (hammer_prim, _C01_HAMMER_MASS),
            (nail_prim, _C01_NAIL_MASS),
        ):
            mass_api = UsdPhysics.MassAPI(prim)
            if not mass_api:
                mass_api = UsdPhysics.MassAPI.Apply(prim)
            mass_attr = mass_api.GetMassAttr()
            if not mass_attr or not mass_attr.IsValid():
                mass_attr = mass_api.CreateMassAttr()
            mass_attr.Set(float(mass))

        tuned_bodies = 0
        tuned_colliders = 0
        for object_name, root_path in task_paths.items():
            root_prim = self._stage.GetPrimAtPath(root_path)
            contact_offset = (
                _C01_HAMMER_CONTACT_OFFSET
                if object_name == "hammer"
                else _C01_NAIL_CONTACT_OFFSET
            )
            for prim in Usd.PrimRange(root_prim):
                if prim.HasAPI(UsdPhysics.RigidBodyAPI):
                    rigid_api = PhysxSchema.PhysxRigidBodyAPI(prim)
                    if not rigid_api:
                        rigid_api = PhysxSchema.PhysxRigidBodyAPI.Apply(prim)
                    for getter_name, creator_name, value in (
                        (
                            "GetEnableCCDAttr",
                            "CreateEnableCCDAttr",
                            _C01_ENABLE_CCD,
                        ),
                        (
                            "GetEnableSpeculativeCCDAttr",
                            "CreateEnableSpeculativeCCDAttr",
                            _C01_ENABLE_SPECULATIVE_CCD,
                        ),
                        (
                            "GetSolverPositionIterationCountAttr",
                            "CreateSolverPositionIterationCountAttr",
                            _C01_SOLVER_POSITION_ITERATIONS,
                        ),
                        (
                            "GetSolverVelocityIterationCountAttr",
                            "CreateSolverVelocityIterationCountAttr",
                            _C01_SOLVER_VELOCITY_ITERATIONS,
                        ),
                        (
                            "GetMaxDepenetrationVelocityAttr",
                            "CreateMaxDepenetrationVelocityAttr",
                            _C01_MAX_DEPENETRATION_VELOCITY,
                        ),
                    ):
                        attr = getattr(rigid_api, getter_name)()
                        if not attr or not attr.IsValid():
                            attr = getattr(rigid_api, creator_name)()
                        attr.Set(value)
                    if object_name == "hammer":
                        # Model the same modest table-contact/air resistance
                        # used by the analytic rolling objects.  This remains
                        # ordinary wakeable rigid-body physics during pickup
                        # and impact; it only lets the broad-side reset contact
                        # reach a natural PhysX sleep state without clamping.
                        for getter_name, creator_name, value in (
                            (
                                "GetLinearDampingAttr",
                                "CreateLinearDampingAttr",
                                _C01_HAMMER_LINEAR_DAMPING,
                            ),
                            (
                                "GetAngularDampingAttr",
                                "CreateAngularDampingAttr",
                                _C01_HAMMER_ANGULAR_DAMPING,
                            ),
                            (
                                "GetSleepThresholdAttr",
                                "CreateSleepThresholdAttr",
                                _C01_HAMMER_SLEEP_THRESHOLD,
                            ),
                        ):
                            attr = getattr(rigid_api, getter_name)()
                            if not attr or not attr.IsValid():
                                attr = getattr(rigid_api, creator_name)()
                            attr.Set(value)
                    tuned_bodies += 1

                if not prim.HasAPI(UsdPhysics.CollisionAPI):
                    continue
                collision_api = PhysxSchema.PhysxCollisionAPI(prim)
                if not collision_api:
                    collision_api = PhysxSchema.PhysxCollisionAPI.Apply(prim)
                contact_attr = collision_api.GetContactOffsetAttr()
                if not contact_attr or not contact_attr.IsValid():
                    contact_attr = collision_api.CreateContactOffsetAttr()
                contact_attr.Set(contact_offset)
                rest_attr = collision_api.GetRestOffsetAttr()
                if not rest_attr or not rest_attr.IsValid():
                    rest_attr = collision_api.CreateRestOffsetAttr()
                rest_attr.Set(_C01_CONTACT_REST_OFFSET)
                tuned_colliders += 1

        if tuned_bodies < 2 or tuned_colliders == 0:
            self._add_task_state_warning(
                "C01 hammer/nail anti-tunneling physics was only partially applied "
                f"({tuned_bodies} bodies, {tuned_colliders} colliders)"
            )
        # Tensor contact reporting has differed by sensor/filter orientation
        # across Isaac Sim releases.  Author both bodies as report sources so
        # the runtime can query the pair in both directions.
        for report_prim in (hammer_prim, nail_prim):
            if report_prim.HasAPI(PhysxSchema.PhysxContactReportAPI):
                report_api = PhysxSchema.PhysxContactReportAPI.Get(
                    self._stage,
                    report_prim.GetPath(),
                )
            else:
                report_api = PhysxSchema.PhysxContactReportAPI.Apply(report_prim)
            report_api.CreateThresholdAttr().Set(0.0)
        return True

    def _configure_c06_camera_grasp_physics(self, sim_utils) -> tuple[int, bool]:
        """Make the articulated C06 camera light and grippy enough to lift."""
        if self._stage is None or self.task_name not in {"t23_photograph_logo", xy3.TASK_NAME}:
            return 0, False

        camera_prim = self._find_rigid_body_prim("camera")
        if camera_prim is None:
            self._add_task_state_warning(
                "Could not tune C06 camera grasp physics: rigid body is unavailable"
            )
            return 0, False

        physics_cfg = _C06_CAMERA_GRASP_PHYSICS
        camera_path = str(camera_prim.GetPath())
        collisions_path = f"{camera_path}/collisions"
        collisions_prim = self._stage.GetPrimAtPath(collisions_path)
        if not collisions_prim.IsValid():
            self._add_task_state_warning(
                "Could not tune C06 camera grasp physics: collision root is unavailable"
            )
            return 0, False

        # MJCF collision groups are imported as instance proxies.  Deinstance
        # only this four-shape subtree so material and helper-collision edits
        # remain narrow and the large camera visual asset stays instanced.
        sim_utils.make_uninstanceable(collisions_path, stage=self._stage)
        sim_utils.update_stage()
        camera_prim = self._stage.GetPrimAtPath(camera_path)
        collisions_prim = self._stage.GetPrimAtPath(collisions_path)

        material_path = "/World/PhysicsMaterials/HandsOnC06CameraGrasp"
        material_cfg = sim_utils.RigidBodyMaterialCfg(
            static_friction=physics_cfg.static_friction,
            dynamic_friction=physics_cfg.dynamic_friction,
            restitution=0.0,
            friction_combine_mode="max",
            restitution_combine_mode="min",
        )
        material_cfg.func(material_path, material_cfg)

        from pxr import PhysxSchema, Usd, UsdPhysics, UsdShade

        bound_colliders = 0
        disabled_helpers = 0
        for prim in Usd.PrimRange(collisions_prim):
            if not prim.HasAPI(UsdPhysics.CollisionAPI):
                continue
            prim_name = prim.GetName()
            if prim_name in {"camera_body_top_cap", "camera_shutter_touch_zone"}:
                UsdPhysics.CollisionAPI(prim).GetCollisionEnabledAttr().Set(False)
                disabled_helpers += 1
                continue
            if prim_name not in {"camera_body_collision", "camera_lens_collision"}:
                continue

            sim_utils.bind_physics_material(
                str(prim.GetPath()),
                material_path,
                stage=self._stage,
                stronger_than_descendants=True,
            )
            physx_collision_api = PhysxSchema.PhysxCollisionAPI(prim)
            if not physx_collision_api:
                physx_collision_api = PhysxSchema.PhysxCollisionAPI.Apply(prim)
            contact_attr = physx_collision_api.GetContactOffsetAttr()
            if not contact_attr or not contact_attr.IsValid():
                contact_attr = physx_collision_api.CreateContactOffsetAttr()
            contact_attr.Set(float(physics_cfg.contact_offset))
            rest_attr = physx_collision_api.GetRestOffsetAttr()
            if not rest_attr or not rest_attr.IsValid():
                rest_attr = physx_collision_api.CreateRestOffsetAttr()
            rest_attr.Set(float(physics_cfg.rest_offset))
            targets = (
                UsdShade.MaterialBindingAPI(prim)
                .GetDirectBindingRel("physics")
                .GetTargets()
            )
            if any(str(target) == material_path for target in targets):
                bound_colliders += 1

        mass_api = UsdPhysics.MassAPI(camera_prim)
        if not mass_api:
            mass_api = UsdPhysics.MassAPI.Apply(camera_prim)
        mass_attr = mass_api.GetMassAttr()
        if not mass_attr or not mass_attr.IsValid():
            mass_attr = mass_api.CreateMassAttr()
        mass_attr.Set(float(physics_cfg.mass))

        rigid_body_api = PhysxSchema.PhysxRigidBodyAPI(camera_prim)
        if not rigid_body_api:
            rigid_body_api = PhysxSchema.PhysxRigidBodyAPI.Apply(camera_prim)
        linear_damping_attr = rigid_body_api.GetLinearDampingAttr()
        if not linear_damping_attr or not linear_damping_attr.IsValid():
            linear_damping_attr = rigid_body_api.CreateLinearDampingAttr()
        linear_damping_attr.Set(float(physics_cfg.linear_damping))
        angular_damping_attr = rigid_body_api.GetAngularDampingAttr()
        if not angular_damping_attr or not angular_damping_attr.IsValid():
            angular_damping_attr = rigid_body_api.CreateAngularDampingAttr()
        angular_damping_attr.Set(float(physics_cfg.angular_damping))

        if bound_colliders == 0:
            self._add_task_state_warning(
                "Could not tune C06 camera friction: no collider accepted the material"
            )
        if disabled_helpers != 2:
            self._add_task_state_warning(
                "Expected to disable 2 C06 transparent helper colliders, "
                f"but disabled {disabled_helpers}"
            )
        return bound_colliders, True

    def _disable_imported_task_robots(self) -> int:
        if self._stage is None:
            return 0
        from pxr import Usd, UsdPhysics

        imported_roots = tuple(
            path
            for side in ("right", "left")
            for path in (
                f"{_TASK_ROOT}/base_{side}",
                f"{_TASK_ROOT}/Geometry/base_{side}",
            )
        )
        task_root = self._stage.GetPrimAtPath(_TASK_ROOT)
        disabled = 0
        for prim in list(Usd.PrimRange(task_root)):
            if not prim.IsA(UsdPhysics.Joint):
                continue
            joint = UsdPhysics.Joint(prim)
            targets = (
                list(joint.GetBody0Rel().GetTargets())
                + list(joint.GetBody1Rel().GetTargets())
            )
            if any(str(target).startswith(imported_roots) for target in targets):
                prim.SetActive(False)
                disabled += 1
        for root_path in imported_roots:
            imported_robot = self._stage.GetPrimAtPath(root_path)
            if imported_robot.IsValid() and imported_robot.IsActive():
                imported_robot.SetActive(False)
                disabled += 1
        return disabled

    def _hide_camera_debug_helpers(self) -> int:
        if self._stage is None:
            return 0
        from pxr import Usd, UsdGeom

        world = self._stage.GetPrimAtPath("/World")
        hidden = 0
        for prim in Usd.PrimRange(world):
            name = prim.GetName()
            if (
                name not in _CAMERA_DEBUG_PRIM_NAMES
                and not name.startswith("head_main_fov_")
            ):
                continue
            imageable = UsdGeom.Imageable(prim)
            if imageable:
                imageable.MakeInvisible()
                hidden += 1
        return hidden

    def _hide_b03_newton_center_rig_visuals(self) -> int:
        """Remove B03's decorative center housing from live/head cameras.

        The housing has no collision geometry, but the production head camera
        sits inside its imported mesh.  USD visibility on the imported MJCF
        instance is not honored consistently by RTX sensor render products, so
        deactivate this decoration for B03/Newton.  The physical right/left
        articulations remain active, visible, and simulated.
        """

        if (
            self._stage is None
            or self._physics_backend != "newton"
            or self.task_name != "t09_insert_peg"
        ):
            return 0
        center_rig = self._stage.GetPrimAtPath(
            "/World/HandsOnRobots/CenterRig"
        )
        if not center_rig.IsValid():
            return 0
        center_rig.SetActive(False)
        return 1

    def _hide_bc005_decorative_center_rig_visuals(self) -> int:
        """Remove both non-physical housings that block BC005 first person.

        The native robot assembly owns one CenterRig decoration and the task
        MJCF imports a second ``rokae_center_components`` copy.  Both contain
        only zero-contact body/head visuals and camera helpers; the simulated
        right/left ROKAE assemblies and all three authoritative recording
        cameras are independent prims.  Deactivate both copies so the
        behind-robot operator view can see the tray and gate between the arms.
        """

        if (
            self._stage is None
            or self.task_name != "loaded_tray_through_narrow_gate"
        ):
            return 0
        hidden = 0
        # Deactivate the converter-authored camera-helper joints before their
        # bodies.  Leaving those joints active while removing the imported
        # decoration makes PhysXSchema report dangling body relationships even
        # though the joints have no role in collection.
        for path in (
            f"{_TASK_ROOT}/joints/rokae_center_head_fixed_frame",
            f"{_TASK_ROOT}/joints/head_main_fov_helper_frame",
            "/World/HandsOnRobots/CenterRig",
            f"{_TASK_ROOT}/rokae_center_components",
        ):
            center_rig = self._stage.GetPrimAtPath(path)
            if not center_rig.IsValid():
                continue
            center_rig.SetActive(False)
            hidden += 1
        return hidden

    def _configure_bc005_operator_viewport_lens(self) -> bool:
        """Give BC005's behind-robot operator view the wide head-camera lens."""

        if (
            self._stage is None
            or self.task_name != "loaded_tray_through_narrow_gate"
        ):
            return False
        from pxr import UsdGeom

        camera_prim = self._stage.GetPrimAtPath("/OmniverseKit_Persp")
        if not camera_prim.IsValid() or not camera_prim.IsA(UsdGeom.Camera):
            return False
        camera = UsdGeom.Camera(camera_prim)
        vertical_aperture = float(
            camera.GetVerticalApertureAttr().Get()
            or _RECORDING_CAMERA_VERTICAL_APERTURE
        )
        focal_length = _focal_length_for_vertical_fov(
            HEAD_RECORDING_CAMERA_FOVY_DEG,
            vertical_aperture,
        )
        camera.GetFocalLengthAttr().Set(float(focal_length))
        print(
            "[HandsOn/IsaacLab] BC005 operator viewport lens: "
            f"fovy={HEAD_RECORDING_CAMERA_FOVY_DEG:g}deg, "
            f"focal_length={focal_length:.6f}, "
            f"vertical_aperture={vertical_aperture:.6f}",
            flush=True,
        )
        return True

    def _disable_newton_orphan_camera_helper_joints(self) -> int:
        """Remove imported camera-only joints that Newton correctly rejects.

        Isaac Sim 6's MJCF converter emits two fixed joints below the visual
        center-camera helper even though that helper has no articulation root.
        PhysX silently tolerates them; Newton validates the USD graph and
        refuses to finalize.  They do not participate in A01 physics or the
        three recording cameras, so deactivating only those joints preserves
        the scene while keeping Newton's model validation strict.
        """

        if self._physics_backend != "newton" or self._stage is None:
            return 0
        from pxr import Usd, UsdPhysics

        task_root = self._stage.GetPrimAtPath(_TASK_ROOT)
        disabled = 0
        for prim in list(Usd.PrimRange(task_root)):
            path = str(prim.GetPath())
            if not prim.IsA(UsdPhysics.Joint):
                continue
            if "/rokae_center_components/" not in path:
                continue
            if (
                "head_main_fov_helper_frame" not in path
                and "rokae_center_head_fixed_frame/PhysicsFixedJoint" not in path
            ):
                continue
            prim.SetActive(False)
            disabled += 1
        return disabled

    def _configure_c04_trigger_physics(self) -> bool:
        if self.task_name not in {"t50_water_plant", "eval_gen06_spray_shoe"} or self._stage is None:
            return False

        from pxr import PhysxSchema, Usd, UsdGeom, UsdPhysics

        joint_path = (
            f"{_TASK_ROOT}/joints/joint_0"
            if self.task_name != "eval_gen06_spray_shoe"
            else ""
        )
        joint = self._stage.GetPrimAtPath(joint_path) if joint_path else None
        if self.task_name == "eval_gen06_spray_shoe":
            # MJCF helper bodies are importer-version dependent. Resolve the
            # real spray hinge by its authored joint name instead of assuming
            # a particular link_1_helper nesting.
            joint = next(
                (prim for prim in Usd.PrimRange(self._stage.GetPrimAtPath(_TASK_ROOT))
                 if prim.GetName() == "joint_0" and prim.IsA(UsdPhysics.RevoluteJoint)),
                None,
            )
        if joint is None or not joint.IsValid():
            self._add_task_state_warning("Could not find the C04 trigger joint")
            return False

        drive = UsdPhysics.DriveAPI.Get(joint, "angular")
        if not drive:
            drive = UsdPhysics.DriveAPI.Apply(joint, "angular")
        drive.GetStiffnessAttr().Set(_C04_TRIGGER_STIFFNESS)
        drive.GetDampingAttr().Set(_C04_TRIGGER_DAMPING)
        drive.GetMaxForceAttr().Set(_C04_TRIGGER_MAX_FORCE)
        drive.GetTargetPositionAttr().Set(0.0)

        joint.GetAttribute("physxJoint:jointFriction").Set(_C04_TRIGGER_FRICTION)
        joint.GetAttribute("physxLimit:X:stiffness").Set(_C04_TRIGGER_STIFFNESS)
        joint.GetAttribute("physxLimit:X:damping").Set(_C04_TRIGGER_DAMPING)

        rigid_paths = {
            str(prim.GetPath())
            for prim in Usd.PrimRange(self._stage.GetPrimAtPath(_TASK_ROOT))
            if prim.HasAPI(UsdPhysics.RigidBodyAPI)
            and str(prim.GetPath()).startswith(f"{_TASK_ROOT}/link_2")
        }
        for path in sorted(rigid_paths):
            prim = self._stage.GetPrimAtPath(path)
            rigid_api = PhysxSchema.PhysxRigidBodyAPI(prim)
            if not rigid_api:
                rigid_api = PhysxSchema.PhysxRigidBodyAPI.Apply(prim)
            for getter_name, creator_name, value in (
                (
                    "GetLinearDampingAttr",
                    "CreateLinearDampingAttr",
                    _C04_RESET_LINEAR_DAMPING,
                ),
                (
                    "GetAngularDampingAttr",
                    "CreateAngularDampingAttr",
                    _C04_RESET_ANGULAR_DAMPING,
                ),
                (
                    "GetSleepThresholdAttr",
                    "CreateSleepThresholdAttr",
                    _C04_RESET_SLEEP_THRESHOLD,
                ),
            ):
                attribute = getattr(rigid_api, getter_name)()
                if not attribute or not attribute.IsValid():
                    attribute = getattr(rigid_api, creator_name)()
                attribute.Set(value)
            if prim.HasAPI(PhysxSchema.PhysxContactReportAPI):
                report_api = PhysxSchema.PhysxContactReportAPI.Get(
                    self._stage,
                    prim.GetPath(),
                )
            else:
                report_api = PhysxSchema.PhysxContactReportAPI.Apply(prim)
            report_api.CreateThresholdAttr().Set(0.0)

        if self.task_name == "eval_gen06_spray_shoe":
            # Keep the stationary shoe target kinematic, with its source
            # triangle colliders. A plant-cylinder substitute both disagrees
            # with the visible upper and breaks the spray occlusion query.
            shoe = self._find_rigid_body_prim("gen7_shoe")
            if shoe is not None:
                rigid = UsdPhysics.RigidBodyAPI(shoe)
                if not rigid:
                    rigid = UsdPhysics.RigidBodyAPI.Apply(shoe)
                kinematic = rigid.GetKinematicEnabledAttr()
                if not kinematic.IsValid():
                    kinematic = rigid.CreateKinematicEnabledAttr()
                kinematic.Set(True)
                shoe_path = str(shoe.GetPath())
                self._task_kinematic_body_paths.add(shoe_path)
                if shoe.HasAPI(UsdPhysics.ArticulationRootAPI):
                    shoe.RemoveAPI(UsdPhysics.ArticulationRootAPI)
                for child in list(Usd.PrimRange(shoe)):
                    if child.IsA(UsdPhysics.FixedJoint):
                        self._stage.RemovePrim(child.GetPath())

        return True

    def _configure_c05_mouse_button_physics(self) -> int:
        if self.task_name not in {"t14_move_and_click_mouse", "eval_comb02_open_laptop_and_click_mouse"} or self._stage is None:
            return 0

        from pxr import Gf, PhysxSchema, Usd, UsdPhysics

        task_prims = list(Usd.PrimRange(self._stage.GetPrimAtPath(_TASK_ROOT)))
        for name, (mass, com, inertia, axes) in _C05_MOUSE_MASS_PROPERTIES.items():
            body = next(
                (prim for prim in task_prims
                 if prim.GetName() == name and prim.HasAPI(UsdPhysics.RigidBodyAPI)),
                None,
            )
            if body is None:
                self._add_task_state_warning(f"Could not find C05 mouse body {name}")
                continue
            mass_api = UsdPhysics.MassAPI.Apply(body)
            mass_api.CreateMassAttr().Set(mass)
            mass_api.CreateCenterOfMassAttr().Set(Gf.Vec3f(*com))
            mass_api.CreateDiagonalInertiaAttr().Set(Gf.Vec3f(*inertia))
            mass_api.CreatePrincipalAxesAttr().Set(Gf.Quatf(axes[0], Gf.Vec3f(*axes[1:])))

        configured = 0
        for name in ("mouse_joint_0", "mouse_joint_1"):
            # The newer importer nests joints below Geometry/link_3/link_N;
            # the original importer put them under /joints. Match identity,
            # not a layout, so both get the same button spring and force cap.
            joint = next(
                (prim for prim in task_prims
                 if prim.GetName() == name and prim.IsA(UsdPhysics.PrismaticJoint)),
                None,
            )
            if joint is None:
                self._add_task_state_warning(f"Could not find C05 button joint {name}")
                continue

            drive = UsdPhysics.DriveAPI.Get(joint, "linear")
            if not drive:
                drive = UsdPhysics.DriveAPI.Apply(joint, "linear")
            drive.CreateTargetPositionAttr().Set(0.0)
            drive.CreateTargetVelocityAttr().Set(0.0)
            drive.CreateStiffnessAttr().Set(_C05_BUTTON_STIFFNESS)
            drive.CreateDampingAttr().Set(_C05_BUTTON_DAMPING)
            drive.CreateMaxForceAttr().Set(_C05_BUTTON_MAX_FORCE)
            PhysxSchema.PhysxJointAPI.Apply(joint).CreateJointFrictionAttr().Set(
                _C05_BUTTON_FRICTION
            )
            limit = PhysxSchema.PhysxLimitAPI.Apply(joint, "X")
            limit.CreateStiffnessAttr().Set(_C05_BUTTON_STIFFNESS)
            limit.CreateDampingAttr().Set(_C05_BUTTON_DAMPING)

            if joint.HasAPI(PhysxSchema.JointStateAPI, "linear"):
                state = PhysxSchema.JointStateAPI.Get(joint, "linear")
            else:
                state = PhysxSchema.JointStateAPI.Apply(joint, "linear")
            state.GetPositionAttr().Set(0.0)
            state.GetVelocityAttr().Set(0.0)
            configured += 1
        return configured

    def _configure_d08_button_physics(self) -> bool:
        """Hold the toaster button at zero and allow a short physical press."""
        if self.task_name not in {"d08_toast_bread", "d08_2_realistic_toast"} or self._stage is None:
            return False

        from pxr import PhysxSchema, UsdPhysics

        joint = self._stage.GetPrimAtPath(
            f"{_TASK_ROOT}/joints/d08_start_button_joint"
        )
        if not joint.IsValid():
            self._add_task_state_warning("Could not find the D08 toaster button joint")
            return False

        # The button is mounted through the toaster shell.  Letting PhysX solve
        # self-collision between the connected toaster links creates a false
        # contact at q=0.  Its own collider remains active for hand contact.
        joint_schema = UsdPhysics.Joint(joint)
        collision_enabled = joint_schema.GetCollisionEnabledAttr()
        if not collision_enabled or not collision_enabled.IsValid():
            collision_enabled = joint_schema.CreateCollisionEnabledAttr()
        collision_enabled.Set(False)

        drive = UsdPhysics.DriveAPI.Get(joint, "linear")
        if not drive:
            drive = UsdPhysics.DriveAPI.Apply(joint, "linear")
        drive.GetTargetPositionAttr().Set(0.0)
        drive.GetTargetVelocityAttr().Set(0.0)
        drive.GetStiffnessAttr().Set(_D08_BUTTON_STIFFNESS)
        drive.GetDampingAttr().Set(_D08_BUTTON_DAMPING)
        drive.GetMaxForceAttr().Set(_D08_BUTTON_MAX_FORCE)
        joint.GetAttribute("physxJoint:jointFriction").Set(
            _D08_BUTTON_FRICTION
        )
        joint.GetAttribute("physxLimit:X:stiffness").Set(
            _D08_BUTTON_STIFFNESS
        )
        joint.GetAttribute("physxLimit:X:damping").Set(_D08_BUTTON_DAMPING)

        if joint.HasAPI(PhysxSchema.JointStateAPI, "linear"):
            state = PhysxSchema.JointStateAPI.Get(joint, "linear")
        else:
            state = PhysxSchema.JointStateAPI.Apply(joint, "linear")
        state.GetPositionAttr().Set(0.0)
        state.GetVelocityAttr().Set(0.0)

        # The moving rack is attached to this link, so its combined gravity
        # load can pull the button to the lower limit before collection starts.
        # Keep the link weightless while retaining its hand-contact collider
        # and the position drive used for physical button presses.
        button_body = None
        for body_path in joint_schema.GetBody1Rel().GetTargets():
            candidate = self._stage.GetPrimAtPath(body_path)
            if candidate.IsValid():
                button_body = candidate
                break
        if button_body is None:
            self._add_task_state_warning(
                "Could not find the D08 toaster button body for gravity tuning"
            )
            return False
        if button_body.HasAPI(PhysxSchema.PhysxRigidBodyAPI):
            rigid_api = PhysxSchema.PhysxRigidBodyAPI.Get(
                self._stage, button_body.GetPath()
            )
        else:
            rigid_api = PhysxSchema.PhysxRigidBodyAPI.Apply(button_body)
        disable_gravity = rigid_api.GetDisableGravityAttr()
        if not disable_gravity or not disable_gravity.IsValid():
            disable_gravity = rigid_api.CreateDisableGravityAttr()
        disable_gravity.Set(True)
        return True

    def _configure_d09_cabinet_physics(self) -> bool:
        """Leave both D09 cabinet doors passive and operator-controlled."""
        if self.task_name != "t31_prepare_coffee" or self._stage is None:
            return False

        from pxr import PhysxSchema, Usd, UsdPhysics

        for joint_name in (
            "d09_cabinet_door_joint",
            "d09_cabinet_right_door_joint",
        ):
            joint = self._stage.GetPrimAtPath(
                f"{_TASK_ROOT}/joints/{joint_name}"
            )
            if not joint.IsValid():
                self._add_task_state_warning(
                    f"Could not find the D09 cabinet joint {joint_name}"
                )
                return False

            joint_schema = UsdPhysics.Joint(joint)
            collision_enabled = joint_schema.GetCollisionEnabledAttr()
            if not collision_enabled or not collision_enabled.IsValid():
                collision_enabled = joint_schema.CreateCollisionEnabledAttr()
            collision_enabled.Set(False)

            drive = UsdPhysics.DriveAPI.Get(joint, "angular")
            if not drive:
                drive = UsdPhysics.DriveAPI.Apply(joint, "angular")
            drive.GetTargetPositionAttr().Set(0.0)
            drive.GetTargetVelocityAttr().Set(0.0)
            drive.GetStiffnessAttr().Set(_D09_DOOR_STIFFNESS)
            drive.GetDampingAttr().Set(_D09_DOOR_DAMPING)
            drive.GetMaxForceAttr().Set(_D09_DOOR_MAX_FORCE)
            joint.GetAttribute("physxJoint:jointFriction").Set(0.04)
            joint.GetAttribute("physxLimit:X:stiffness").Set(0.0)
            joint.GetAttribute("physxLimit:X:damping").Set(_D09_DOOR_DAMPING)

            if joint.HasAPI(PhysxSchema.JointStateAPI, "angular"):
                state = PhysxSchema.JointStateAPI.Get(joint, "angular")
            else:
                state = PhysxSchema.JointStateAPI.Apply(joint, "angular")
            state.GetPositionAttr().Set(0.0)
            state.GetVelocityAttr().Set(0.0)

        cabinet_prim = self._find_rigid_body_prim("d09_cabinet")
        if cabinet_prim is None:
            self._add_task_state_warning(
                "Could not find the D09 cabinet body for contact tuning"
            )
            return False
        for prim in Usd.PrimRange(cabinet_prim):
            if not prim.HasAPI(UsdPhysics.CollisionAPI):
                continue
            collision_api = PhysxSchema.PhysxCollisionAPI(prim)
            if not collision_api:
                collision_api = PhysxSchema.PhysxCollisionAPI.Apply(prim)
            collision_api.CreateContactOffsetAttr().Set(0.0001)
            collision_api.CreateRestOffsetAttr().Set(0.0)

        # The mug's collision shell is authored 1 mm above the cabinet floor.
        # Keep the visual and physical mug poses coincident, but shrink the
        # two participating contact shells below that gap so the initial
        # cabinet↔mug manifold is not fabricated by PhysX's default offset.
        mug_prim = self._find_rigid_body_prim("d09_mug")
        if mug_prim is not None:
            for prim in Usd.PrimRange(mug_prim):
                if not prim.HasAPI(UsdPhysics.CollisionAPI):
                    continue
                collision_api = PhysxSchema.PhysxCollisionAPI(prim)
                if not collision_api:
                    collision_api = PhysxSchema.PhysxCollisionAPI.Apply(prim)
                collision_api.CreateContactOffsetAttr().Set(0.0001)
                collision_api.CreateRestOffsetAttr().Set(0.0)

        return True

    def _configure_d07_drawer_physics(self) -> bool:
        """Hold the office drawer closed until an operator pulls it."""
        if self.task_name != "d07_organize_office_desk" or self._stage is None:
            return False

        from pxr import PhysxSchema, Usd, UsdPhysics

        joint = self._stage.GetPrimAtPath(
            f"{_TASK_ROOT}/joints/d07_drawer_joint"
        )
        if not joint.IsValid():
            self._add_task_state_warning("Could not find the D07 drawer joint")
            return False

        joint_schema = UsdPhysics.Joint(joint)
        collision_enabled = joint_schema.GetCollisionEnabledAttr()
        if not collision_enabled or not collision_enabled.IsValid():
            collision_enabled = joint_schema.CreateCollisionEnabledAttr()
        collision_enabled.Set(False)

        # The tray bottom is authored only 3 mm above the cabinet base.  The
        # imported 20 mm default contact shells overlap even though the actual
        # shapes do not, and that false self-contact drives the slide all the
        # way to 0.18 m during the origin gate.  Use a narrow analytic shell
        # for both connected drawer links.
        drawer_prim = self._find_rigid_body_prim("d07_drawer")
        if drawer_prim is None:
            self._add_task_state_warning("Could not find the D07 drawer body")
            return False
        for prim in Usd.PrimRange(drawer_prim):
            if not prim.HasAPI(UsdPhysics.CollisionAPI):
                continue
            collision_api = PhysxSchema.PhysxCollisionAPI(prim)
            if not collision_api:
                collision_api = PhysxSchema.PhysxCollisionAPI.Apply(prim)
            collision_api.CreateContactOffsetAttr().Set(0.001)
            collision_api.CreateRestOffsetAttr().Set(0.0)

        drive = UsdPhysics.DriveAPI.Get(joint, "linear")
        if not drive:
            drive = UsdPhysics.DriveAPI.Apply(joint, "linear")
        drive.GetTargetPositionAttr().Set(0.0)
        drive.GetTargetVelocityAttr().Set(0.0)
        drive.GetStiffnessAttr().Set(_D07_DRAWER_STIFFNESS)
        drive.GetDampingAttr().Set(_D07_DRAWER_DAMPING)
        drive.GetMaxForceAttr().Set(_D07_DRAWER_MAX_FORCE)
        joint.GetAttribute("physxJoint:jointFriction").Set(0.15)
        joint.GetAttribute("physxLimit:X:stiffness").Set(
            _D07_DRAWER_STIFFNESS
        )
        joint.GetAttribute("physxLimit:X:damping").Set(_D07_DRAWER_DAMPING)

        if joint.HasAPI(PhysxSchema.JointStateAPI, "linear"):
            state = PhysxSchema.JointStateAPI.Get(joint, "linear")
        else:
            state = PhysxSchema.JointStateAPI.Apply(joint, "linear")
        state.GetPositionAttr().Set(0.0)
        state.GetVelocityAttr().Set(0.0)
        return True

    def _configure_d10_dishwasher_physics(self) -> bool:
        """Reset D10 closed, then leave its door/rack manually movable."""
        if self.task_name != "d10_load_dishwasher" or self._stage is None:
            return False

        import isaaclab.sim as sim_utils
        from pxr import PhysxSchema, Usd, UsdPhysics

        joint_specs = (
            (
                "d10_door_joint",
                "angular",
                _D10_DOOR_STIFFNESS,
                _D10_DOOR_DAMPING,
                _D10_DOOR_MAX_FORCE,
            ),
            (
                "d10_rack_joint",
                "linear",
                _D10_RACK_STIFFNESS,
                _D10_RACK_DAMPING,
                _D10_RACK_MAX_FORCE,
            ),
        )
        for name, drive_type, stiffness, damping, max_force in joint_specs:
            joint = self._stage.GetPrimAtPath(f"{_TASK_ROOT}/joints/{name}")
            if not joint.IsValid():
                self._add_task_state_warning(
                    f"Could not find the D10 dishwasher joint {name}"
                )
                return False

            joint_schema = UsdPhysics.Joint(joint)
            collision_enabled = joint_schema.GetCollisionEnabledAttr()
            if not collision_enabled or not collision_enabled.IsValid():
                collision_enabled = joint_schema.CreateCollisionEnabledAttr()
            collision_enabled.Set(False)

            drive = UsdPhysics.DriveAPI.Get(joint, drive_type)
            if not drive:
                drive = UsdPhysics.DriveAPI.Apply(joint, drive_type)
            drive.GetTargetPositionAttr().Set(0.0)
            drive.GetTargetVelocityAttr().Set(0.0)
            drive.GetStiffnessAttr().Set(stiffness)
            drive.GetDampingAttr().Set(damping)
            drive.GetMaxForceAttr().Set(max_force)
            # Drive stiffness is intentionally zero: target position 0 is a
            # reset state, not a latch.  Keep a small passive limit response
            # so the link does not jitter at the end of its travel.
            joint.GetAttribute("physxJoint:jointFriction").Set(0.04)
            joint.GetAttribute("physxLimit:X:stiffness").Set(1.0)
            joint.GetAttribute("physxLimit:X:damping").Set(0.15)

            if joint.HasAPI(PhysxSchema.JointStateAPI, drive_type):
                state = PhysxSchema.JointStateAPI.Get(joint, drive_type)
            else:
                state = PhysxSchema.JointStateAPI.Apply(joint, drive_type)
            state.GetPositionAttr().Set(0.0)
            state.GetVelocityAttr().Set(0.0)

        # The door is physically 13 mm clear of the cabinet side, but the
        # importer's default 20 mm contact shells overlap.  That false contact
        # used to kick the hinge open by roughly 1.2 rad during origin settle.
        # Preserve the real shapes while using a narrow analytic shell on all
        # links in this one articulation.
        dishwasher_prim = self._find_rigid_body_prim("d10_dishwasher")
        if dishwasher_prim is None:
            self._add_task_state_warning("Could not find the D10 dishwasher body")
            return False
        for prim in Usd.PrimRange(dishwasher_prim):
            if not prim.HasAPI(UsdPhysics.CollisionAPI):
                continue
            collision_api = PhysxSchema.PhysxCollisionAPI(prim)
            if not collision_api:
                collision_api = PhysxSchema.PhysxCollisionAPI.Apply(prim)
            collision_api.CreateContactOffsetAttr().Set(0.001)
            collision_api.CreateRestOffsetAttr().Set(0.0)
        self._configure_named_reset_stability(
            sim_utils,
            ("d10_mug", "d10_bowl", "d10_plate"),
            linear_damping=0.45,
            angular_damping=6.0,
            sleep_threshold=0.01,
            warning_label="D10 dish",
            strip_redundant_articulation_root=True,
        )
        return True

