    def _configure_ycb07_timer_physics(self) -> int:
        if self.task_name != _YCB07_TASK_NAME or self._stage is None:
            return 0

        from pxr import PhysxSchema, UsdPhysics

        configured = 0
        for index, joint_name in enumerate(_YCB07_BUTTON_JOINTS):
            joint = self._stage.GetPrimAtPath(f"{_TASK_ROOT}/joints/{joint_name}")
            if not joint.IsValid():
                self._add_task_state_warning(
                    f"Could not find YCB07 button joint {joint_name}"
                )
                continue
            drive = UsdPhysics.DriveAPI.Get(joint, "linear")
            if not drive:
                drive = UsdPhysics.DriveAPI.Apply(joint, "linear")
            is_mode_switch = index == _YCB07_BUTTON_INDEX["mode"]
            drive.GetTargetPositionAttr().Set(0.0)
            drive.GetTargetVelocityAttr().Set(0.0)
            drive.GetStiffnessAttr().Set(100.0 if is_mode_switch else 650.0)
            drive.GetDampingAttr().Set(3.0 if is_mode_switch else 8.0)
            drive.GetMaxForceAttr().Set(1.0 if is_mode_switch else 3.0)
            joint.GetAttribute("physxJoint:jointFriction").Set(
                0.01 if is_mode_switch else 0.02
            )
            if joint.HasAPI(PhysxSchema.JointStateAPI, "linear"):
                state = PhysxSchema.JointStateAPI.Get(joint, "linear")
            else:
                state = PhysxSchema.JointStateAPI.Apply(joint, "linear")
            state.GetPositionAttr().Set(0.0)
            state.GetVelocityAttr().Set(0.0)
            configured += 1

        for name in (_YCB07_TIMER_NAME, *_YCB07_BUTTON_BODIES):
            body = self._find_rigid_body_prim(name)
            if body is None:
                self._add_task_state_warning(
                    f"Could not configure YCB07 contact reporting for {name}"
                )
                continue
            if body.HasAPI(PhysxSchema.PhysxContactReportAPI):
                report_api = PhysxSchema.PhysxContactReportAPI.Get(
                    self._stage,
                    body.GetPath(),
                )
            else:
                report_api = PhysxSchema.PhysxContactReportAPI.Apply(body)
            report_api.CreateThresholdAttr().Set(0.0)
        return configured

    def _configure_ycb05_physics(self, sim_utils: Any) -> int:
        """Tune only damping/contact reports and the passive trigger return."""
        if self.task_name != YCB05_TASK_NAME or self._stage is None:
            return 0

        from pxr import PhysxSchema, Usd, UsdPhysics

        task_root = self._stage.GetPrimAtPath(_TASK_ROOT)
        joint = next(
            (
                prim
                for prim in Usd.PrimRange(task_root)
                if prim.GetName() == YCB05_TRIGGER_JOINT_NAME
                and prim.IsA(UsdPhysics.PrismaticJoint)
            ),
            None,
        )
        if joint is None:
            self._add_task_state_warning("Could not find the YCB05 trigger joint")
            return 0

        drive = UsdPhysics.DriveAPI.Get(joint, "linear")
        if not drive:
            drive = UsdPhysics.DriveAPI.Apply(joint, "linear")
        drive.GetTargetPositionAttr().Set(0.0)
        drive.GetTargetVelocityAttr().Set(0.0)
        drive.GetStiffnessAttr().Set(_YCB05_TRIGGER_STIFFNESS)
        drive.GetDampingAttr().Set(_YCB05_TRIGGER_DAMPING)
        drive.GetMaxForceAttr().Set(_YCB05_TRIGGER_MAX_FORCE)
        joint.GetAttribute("physxJoint:jointFriction").Set(_YCB05_TRIGGER_FRICTION)
        joint.GetAttribute("physxLimit:X:stiffness").Set(_YCB05_TRIGGER_STIFFNESS)
        joint.GetAttribute("physxLimit:X:damping").Set(_YCB05_TRIGGER_DAMPING)
        if joint.HasAPI(PhysxSchema.JointStateAPI, "linear"):
            joint_state = PhysxSchema.JointStateAPI.Get(joint, "linear")
        else:
            joint_state = PhysxSchema.JointStateAPI.Apply(joint, "linear")
        joint_state.GetPositionAttr().Set(0.0)
        joint_state.GetVelocityAttr().Set(0.0)

        # The source trigger is embedded in the housing at rest.  Keep all
        # hand-trigger contacts, but explicitly filter the adjacent parent
        # housing pair so PhysX cannot depenetrate the trigger to 4 mm before
        # the operator touches it.  The MJCF carries the same exclusion; this
        # USD authoring makes the runtime contract independent of importer
        # handling of <contact><exclude>.
        filtered_pairs = 0
        drill_prim = self._find_rigid_body_prim(YCB05_DRILL_NAME)
        trigger_prim = self._find_rigid_body_prim(YCB05_TRIGGER_BODY_NAME)
        if drill_prim is None or trigger_prim is None:
            self._add_task_state_warning(
                "Could not filter the YCB05 trigger from its drill housing"
            )
        else:
            filtered_api = UsdPhysics.FilteredPairsAPI(trigger_prim)
            if not filtered_api:
                filtered_api = UsdPhysics.FilteredPairsAPI.Apply(trigger_prim)
            filtered_api.CreateFilteredPairsRel().AddTarget(drill_prim.GetPath())
            filtered_pairs = 1

        tuned = self._configure_named_reset_stability(
            sim_utils,
            (YCB05_DRILL_NAME, YCB05_WOOD_NAME),
            linear_damping=_YCB05_RESET_LINEAR_DAMPING,
            angular_damping=_YCB05_RESET_ANGULAR_DAMPING,
            sleep_threshold=_YCB05_RESET_SLEEP_THRESHOLD,
            warning_label="YCB05 YCB bodies",
        )
        configured_reports = 0
        for name in (
            YCB05_DRILL_NAME,
            YCB05_TRIGGER_BODY_NAME,
            YCB05_WOOD_NAME,
            "table",
        ):
            prim = self._find_rigid_body_prim(name)
            if prim is None:
                self._add_task_state_warning(
                    f"Could not configure YCB05 contact reporting for {name}"
                )
                continue
            if prim.HasAPI(PhysxSchema.PhysxContactReportAPI):
                report_api = PhysxSchema.PhysxContactReportAPI.Get(
                    self._stage, prim.GetPath()
                )
            else:
                report_api = PhysxSchema.PhysxContactReportAPI.Apply(prim)
            report_api.CreateThresholdAttr().Set(0.0)
            rigid_api = PhysxSchema.PhysxRigidBodyAPI(prim)
            if not rigid_api:
                rigid_api = PhysxSchema.PhysxRigidBodyAPI.Apply(prim)
            ccd = rigid_api.GetEnableCCDAttr()
            if not ccd or not ccd.IsValid():
                ccd = rigid_api.CreateEnableCCDAttr()
            ccd.Set(name in {YCB05_DRILL_NAME, YCB05_TRIGGER_BODY_NAME})
            configured_reports += 1
        return 1 + filtered_pairs + tuned + configured_reports

    def _configure_c08_tongs_spring_physics(self) -> bool:
        """Make the tongs spring open while preserving physical ice contact."""
        if self.task_name != "c08_tongs_ice_cubes" or self._stage is None:
            return False

        from pxr import PhysxSchema, Usd, UsdPhysics

        task_root = self._stage.GetPrimAtPath(_TASK_ROOT)
        joint = next(
            (
                prim
                for prim in Usd.PrimRange(task_root)
                if prim.GetName() == "c08_tongs_joint"
                and prim.IsA(UsdPhysics.RevoluteJoint)
            ),
            None,
        )
        if joint is None:
            self._add_task_state_warning(
                "Could not configure C08 tongs spring: hinge joint is unavailable"
            )
            return False

        drive = UsdPhysics.DriveAPI.Get(joint, "angular")
        if not drive:
            drive = UsdPhysics.DriveAPI.Apply(joint, "angular")
        rest_degrees = math.degrees(_C08_TONGS_REST_RAD)
        drive.GetTargetPositionAttr().Set(rest_degrees)
        drive.GetTargetVelocityAttr().Set(0.0)
        drive.GetStiffnessAttr().Set(_C08_TONGS_SPRING_STIFFNESS)
        drive.GetDampingAttr().Set(_C08_TONGS_SPRING_DAMPING)
        drive.GetMaxForceAttr().Set(_C08_TONGS_SPRING_MAX_FORCE)
        joint.GetAttribute("physxJoint:jointFriction").Set(
            _C08_TONGS_JOINT_FRICTION
        )

        if joint.HasAPI(PhysxSchema.JointStateAPI, "angular"):
            state = PhysxSchema.JointStateAPI.Get(joint, "angular")
        else:
            state = PhysxSchema.JointStateAPI.Apply(joint, "angular")
        state.GetPositionAttr().Set(rest_degrees)
        state.GetVelocityAttr().Set(0.0)

        # The live glove now owns the jaw DOF.  Do not author the former
        # tongs/ice CollisionGroup filter: the pads must physically push and
        # oppose the cube before the two-surface anti-slip latch can engage.
        self._c08_tongs_ice_collision_filtered = False
        return True

    def _initialize_c08_tongs_open_state(self) -> bool:
        """Force the live and cached reset states to the spring rest angle."""
        if self.task_name != "c08_tongs_ice_cubes" or self._torch is None:
            return False
        dof_state = self._task_dof_views.get("c08_tongs_joint")
        if dof_state is None:
            self._add_task_state_warning(
                "Could not initialize C08 tongs open: DOF view is unavailable"
            )
            return False

        view, dof_index, _initial_position = dof_state
        try:
            positions = view.get_dof_positions().clone()
            velocities = view.get_dof_velocities().clone()
            positions[:, dof_index] = _C08_TONGS_REST_RAD
            velocities[:, dof_index] = 0.0
            indices = self._torch.arange(
                int(view.count),
                dtype=self._torch.long,
                device=self._isaac_device,
            )
            view.set_dof_positions(positions, indices)
            view.set_dof_velocities(velocities, indices)
            for (
                _path,
                cached_view,
                _indices,
                _root_pose,
                _root_velocity,
                cached_positions,
                cached_velocities,
            ) in self._task_reset_articulation_states:
                if cached_view is not view:
                    continue
                cached_positions[:, dof_index] = _C08_TONGS_REST_RAD
                cached_velocities[:, dof_index] = 0.0
            self._task_dof_views["c08_tongs_joint"] = (
                view,
                dof_index,
                _C08_TONGS_REST_RAD,
            )
            print(
                "[HandsOn/IsaacLab] C08 tongs spring initialized open "
                f"at {_C08_TONGS_REST_RAD:.3f} rad",
                flush=True,
            )
            return True
        except Exception as exc:
            self._add_task_state_warning(
                f"Could not initialize C08 tongs open state: {exc}"
            )
            return False

