    def _configure_c11_contact_reporting(self) -> int:
        if self.task_name != "c11_xylophone_sequence" or self._stage is None:
            return 0

        from pxr import PhysxSchema

        configured = 0
        missing: list[str] = []
        for name in ("c11_mallet", *_C11_KEY_NAMES):
            body_prim = self._find_rigid_body_prim(name)
            if body_prim is None:
                missing.append(name)
                continue
            if body_prim.HasAPI(PhysxSchema.PhysxContactReportAPI):
                report_api = PhysxSchema.PhysxContactReportAPI.Get(
                    self._stage,
                    body_prim.GetPath(),
                )
            else:
                report_api = PhysxSchema.PhysxContactReportAPI.Apply(body_prim)
            report_api.CreateThresholdAttr().Set(0.0)
            configured += 1
        expected = 1 + len(_C11_KEY_NAMES)
        if missing or configured != expected:
            details = (
                "none" if not missing else ",".join(sorted(missing))
            )
            message = (
                "C11 contact reporting contract is incomplete: "
                f"configured={configured}/{expected}, missing={details}"
            )
            self._add_task_state_warning(message)
            raise RuntimeError(message)
        return configured

    def _validate_c11_complete_hand_collision_topology(self) -> int:
        """Fail closed if C11 loses any authored Wuji palm/finger collider."""

        if self.task_name != "c11_xylophone_sequence" or self._stage is None:
            return 0

        from pxr import Usd, UsdPhysics

        collider_paths: list[str] = []
        for side in ("Right", "Left"):
            root_path = f"/World/HandsOnRobots/{side}Robot"
            root_prim = self._stage.GetPrimAtPath(root_path)
            if not root_prim.IsValid():
                continue
            for prim in Usd.PrimRange(
                root_prim,
                Usd.TraverseInstanceProxies(),
            ):
                normalized_path = str(prim.GetPath()).lower()
                if (
                    "palm" not in normalized_path
                    and "finger" not in normalized_path
                ):
                    continue
                collision_api = UsdPhysics.CollisionAPI(prim)
                if not collision_api:
                    continue
                enabled_attr = collision_api.GetCollisionEnabledAttr()
                if (
                    enabled_attr
                    and enabled_attr.IsValid()
                    and enabled_attr.Get() is False
                ):
                    continue
                collider_paths.append(str(prim.GetPath()))

        expected = _smooth_grasp_expected_hand_collider_count(self.hand_type)
        if len(collider_paths) != expected:
            message = (
                "C11 complete-hand collision topology changed: "
                f"found={len(collider_paths)}/{expected}; "
                f"hand_type={self.hand_type}; paths={collider_paths}"
            )
            self._add_task_state_warning(message)
            raise RuntimeError(message)
        return len(collider_paths)
