    def _c04_right_hand_body_paths(self) -> list[str]:
        if self._stage is None:
            return []

        from pxr import Usd, UsdPhysics

        root = self._stage.GetPrimAtPath(
            "/World/HandsOnRobots/RightRobot"
        )
        paths: list[str] = []
        for prim in Usd.PrimRange(root):
            name = prim.GetName()
            if not prim.HasAPI(UsdPhysics.RigidBodyAPI):
                continue
            if name == "right_palm_link" or name.startswith("right_finger"):
                paths.append(str(prim.GetPath()))
        return paths

    def _ycb04_hand_body_paths(self) -> list[str]:
        """Return rigid palm/finger links for both hands used by YCB04."""
        if self._stage is None:
            return []

        from pxr import Usd, UsdPhysics

        paths: list[str] = []
        for side in ("Right", "Left"):
            root = self._stage.GetPrimAtPath(
                f"/World/HandsOnRobots/{side}Robot"
            )
            if not root.IsValid():
                continue
            prefix = side.lower()
            for prim in Usd.PrimRange(root):
                name = prim.GetName().lower()
                if not prim.HasAPI(UsdPhysics.RigidBodyAPI):
                    continue
                if name == f"{prefix}_palm_link" or name.startswith(
                    f"{prefix}_finger"
                ):
                    paths.append(str(prim.GetPath()))
        return paths

    def _ycb07_hand_body_paths(
        self,
        side: str,
        *,
        fingertips_only: bool,
    ) -> list[str]:
        """Return YCB07's physical hand/chassis contact filter paths.

        YCB07 distinguishes a right fingertip press from a left-hand chassis
        brace.  Resolve only rigid Wuji links under the requested robot root;
        using the generic whole-robot expression would include arm links and
        create unnecessary contact pairs in the PhysX GPU view.
        """

        if self._stage is None:
            return []
        side = str(side).strip().lower()
        if side not in {"left", "right"}:
            return []

        from pxr import Usd, UsdPhysics

        root = self._stage.GetPrimAtPath(
            f"/World/HandsOnRobots/{side.capitalize()}Robot"
        )
        if not root.IsValid():
            return []

        paths: list[str] = []
        for prim in Usd.PrimRange(root):
            if not prim.HasAPI(UsdPhysics.RigidBodyAPI):
                continue
            name = prim.GetName().lower()
            if fingertips_only:
                # Wuji revisions expose fingertip links either as *_tip or
                # as the terminal *_link4. Accept both authored variants.
                if name.startswith(f"{side}_finger") and (
                    "tip" in name or name.endswith("_link4")
                ):
                    paths.append(str(prim.GetPath()))
            elif name == f"{side}_palm_link" or name.startswith(
                f"{side}_finger"
            ):
                paths.append(str(prim.GetPath()))
        return paths

    def _c02_hand_body_paths(self) -> list[str]:
        """Return collision-reporting bodies for every simulated hand."""
        if self._stage is None:
            return []

        from pxr import Usd, UsdPhysics

        paths: list[str] = []
        for side in ("Right", "Left"):
            root = self._stage.GetPrimAtPath(
                f"/World/HandsOnRobots/{side}Robot"
            )
            if root is None or not root.IsValid():
                continue
            prefix = side.lower()
            for prim in Usd.PrimRange(root):
                name = prim.GetName()
                if not prim.HasAPI(UsdPhysics.RigidBodyAPI):
                    continue
                if (
                    name == f"{prefix}_palm_link"
                    or name.startswith(f"{prefix}_finger")
                ):
                    paths.append(str(prim.GetPath()))
        return paths

    def _c02_hand_body_paths_for_side(self, side: str) -> list[str]:
        """Return only one hand's physical bodies for C02 contact truth."""
        if side not in {"right", "left"} or self._stage is None:
            return []
        from pxr import Usd, UsdPhysics

        root = self._stage.GetPrimAtPath(
            f"/World/HandsOnRobots/{side.capitalize()}Robot"
        )
        if root is None or not root.IsValid():
            return []
        paths: list[str] = []
        for prim in Usd.PrimRange(root):
            name = prim.GetName()
            if not prim.HasAPI(UsdPhysics.RigidBodyAPI):
                continue
            if name == f"{side}_palm_link" or name.startswith(f"{side}_finger"):
                paths.append(str(prim.GetPath()))
        return paths

    def _hs005_hand_body_paths(self, side: str) -> list[str]:
        if self._stage is None or side not in {"left", "right"}:
            return []
        from pxr import Usd, UsdPhysics

        root = self._stage.GetPrimAtPath(
            f"/World/HandsOnRobots/{side.capitalize()}Robot"
        )
        paths: list[str] = []
        for prim in Usd.PrimRange(root):
            name = prim.GetName()
            if not prim.HasAPI(UsdPhysics.RigidBodyAPI):
                continue
            if name == f"{side}_palm_link" or name.startswith(f"{side}_finger"):
                paths.append(str(prim.GetPath()))
        return paths

    @staticmethod
    def _a01_newton_right_hand_shape_label(label: str) -> bool:
        normalized = str(label).lower()
        leaf = normalized.rsplit("/", 1)[-1]
        if "/world/handsonrobots/rightrobot/" not in normalized:
            return False
        return bool(
            leaf == "right_palm_link_col2"
            or (
                leaf.startswith("right_finger")
                and leaf.endswith("_col2")
            )
        )

    @staticmethod
    def _a01_newton_bucket_shape_label(label: str) -> bool:
        normalized = str(label).lower()
        leaf = normalized.rsplit("/", 1)[-1]
        if not normalized.startswith(f"{_TASK_ROOT.lower()}/"):
            return False
        if "/bucket/" in normalized:
            return True
        return leaf in {
            "bucket_back",
            "bucket_front",
            "bucket_l",
            "bucket_r",
            "bucket_left",
            "bucket_right",
            "bucket_bottom",
            "handle1",
            "handle2",
            "handle3",
        }

    @staticmethod
    def _a01_contact_pairs_include_hand_bucket(
        shape0: np.ndarray,
        shape1: np.ndarray,
        hand_shape_indices: frozenset[int],
        bucket_shape_indices: frozenset[int],
    ) -> bool:
        for first, second in zip(
            np.asarray(shape0, dtype=np.int64).reshape(-1),
            np.asarray(shape1, dtype=np.int64).reshape(-1),
        ):
            first_index = int(first)
            second_index = int(second)
            if (
                first_index in hand_shape_indices
                and second_index in bucket_shape_indices
            ) or (
                second_index in hand_shape_indices
                and first_index in bucket_shape_indices
            ):
                return True
        return False

    def _cache_a01_newton_contact_shape_indices(self) -> tuple[int, int]:
        if (
            self._a01_newton_hand_shape_indices is not None
            and self._a01_newton_bucket_shape_indices is not None
        ):
            return (
                len(self._a01_newton_hand_shape_indices),
                len(self._a01_newton_bucket_shape_indices),
            )

        from isaaclab_newton.physics import NewtonManager

        model = NewtonManager.get_model()
        labels = list(getattr(model, "shape_label", ()) or ())
        hand_indices = frozenset(
            index
            for index, label in enumerate(labels)
            if self._a01_newton_right_hand_shape_label(str(label))
        )
        bucket_indices = frozenset(
            index
            for index, label in enumerate(labels)
            if self._a01_newton_bucket_shape_label(str(label))
        )
        if not hand_indices or not bucket_indices:
            raise RuntimeError(
                "Newton shape labels did not resolve the A01 right hand and "
                f"bucket (hand_shapes={len(hand_indices)}, "
                f"bucket_shapes={len(bucket_indices)})"
            )
        self._a01_newton_hand_shape_indices = hand_indices
        self._a01_newton_bucket_shape_indices = bucket_indices
        return len(hand_indices), len(bucket_indices)

    def _init_a01_hand_bucket_contact_reporting(self) -> None:
        self._a01_hand_bucket_contact_view = None
        if self.task_name != "t26_place_fruit_in_bucket" or not self._robots:
            return

        if self._physics_backend == "newton":
            try:
                hand_count, bucket_count = (
                    self._cache_a01_newton_contact_shape_indices()
                )
                print(
                    "[HandsOn/IsaacLab] A01 hand/bucket contact reporting "
                    f"ready (backend=newton, hand_shapes={hand_count}, "
                    f"bucket_shapes={bucket_count})",
                    flush=True,
                )
            except Exception as exc:
                self._a01_contact_reporting_warning_emitted = True
                self._add_task_state_warning(
                    f"A01 Newton hand/bucket contact reporting is unavailable: {exc}"
                )
            return

        physics_sim_view = self._robots["right"]._physics_sim_view
        hand_paths = self._c04_right_hand_body_paths()
        bucket_prim = self._find_rigid_body_prim("bucket")
        if physics_sim_view is None or not hand_paths or bucket_prim is None:
            self._add_task_state_warning(
                "A01 PhysX hand/bucket contact reporting is unavailable"
            )
            return
        try:
            view = physics_sim_view.create_rigid_contact_view(
                str(bucket_prim.GetPath()),
                filter_patterns=hand_paths,
                max_contact_data_count=max(64, len(hand_paths) * 8),
            )
            if (
                view is not None
                and int(view.sensor_count) > 0
                and int(view.filter_count) > 0
            ):
                self._a01_hand_bucket_contact_view = view
            else:
                self._add_task_state_warning(
                    "A01 PhysX hand/bucket contact view has no sensors or filters"
                )
        except Exception as exc:
            self._add_task_state_warning(
                f"Could not initialize A01 PhysX hand/bucket contact reporting: {exc}"
            )

    @staticmethod
    def _a01_newton_contact_array_prefix(value: Any, count: int) -> np.ndarray:
        if count <= 0:
            return np.empty((0,), dtype=np.int64)
        try:
            import warp as wp

            tensor = wp.to_torch(value).reshape(-1)[:count]
            return tensor.detach().cpu().numpy()
        except Exception:
            array = value.numpy() if hasattr(value, "numpy") else value
            return np.asarray(array).reshape(-1)[:count]

    def _a01_newton_hand_touches_bucket(self) -> bool:
        from isaaclab_newton.physics import NewtonManager

        self._cache_a01_newton_contact_shape_indices()
        contacts = NewtonManager.get_contacts()
        if contacts is None:
            return False
        count_value = contacts.rigid_contact_count
        count_array = (
            count_value.numpy()
            if hasattr(count_value, "numpy")
            else np.asarray(count_value)
        )
        contact_count = int(np.asarray(count_array).reshape(-1)[0])
        if contact_count <= 0:
            return False
        shape0 = self._a01_newton_contact_array_prefix(
            contacts.rigid_contact_shape0,
            contact_count,
        )
        shape1 = self._a01_newton_contact_array_prefix(
            contacts.rigid_contact_shape1,
            contact_count,
        )
        return self._a01_contact_pairs_include_hand_bucket(
            shape0,
            shape1,
            self._a01_newton_hand_shape_indices or frozenset(),
            self._a01_newton_bucket_shape_indices or frozenset(),
        )

    def _a01_hand_touches_bucket(self) -> bool:
        try:
            if self._physics_backend == "newton":
                touching = self._a01_newton_hand_touches_bucket()
            else:
                touching = (
                    self._c04_contact_force(
                        self._a01_hand_bucket_contact_view
                    )
                    > 0.0
                )
        except Exception as exc:
            touching = False
            if not self._a01_contact_reporting_warning_emitted:
                self._a01_contact_reporting_warning_emitted = True
                self._add_task_state_warning(
                    f"Could not read A01 hand/bucket contacts: {exc}"
                )
        self._last_a01_hand_bucket_contact = bool(touching)
        return self._last_a01_hand_bucket_contact

    def _init_c02_hand_marble_contact_view(self) -> None:
        """Track right-hand contacts and left-hand lift attempts separately."""
        self._c02_marble_hand_contact_view = None
        self._c02_marble_hand_contact_views = {}
        self._c02_failure_monitor_available = False
        if self.task_name != "t36_scoop_marbles" or not self._robots:
            return
        physics_sim_view = next(iter(self._robots.values()))._physics_sim_view
        marble_prim = self._find_rigid_body_prim("golf_ball")
        if physics_sim_view is None or marble_prim is None:
            self._add_task_state_warning(
                "C02 hand/marble failure contact reporting is unavailable"
            )
            return
        try:
            for side in ("right", "left"):
                hand_paths = self._c02_hand_body_paths_for_side(side)
                if not hand_paths:
                    continue
                view = physics_sim_view.create_rigid_contact_view(
                    str(marble_prim.GetPath()),
                    filter_patterns=hand_paths,
                    max_contact_data_count=max(64, len(hand_paths) * 8),
                )
                if (
                    view is not None
                    and int(view.sensor_count) > 0
                    and int(view.filter_count) > 0
                ):
                    self._c02_marble_hand_contact_views[side] = view
            # Both channels are required to certify the asymmetric contact
            # policy. Keep the legacy aggregate alias for callers/tests.
            self._c02_marble_hand_contact_view = (
                self._c02_marble_hand_contact_views.get("right")
            )
            self._c02_failure_monitor_available = set(
                self._c02_marble_hand_contact_views
            ) == {"right", "left"}
            if not self._c02_failure_monitor_available:
                self._add_task_state_warning(
                    "C02 hand/marble contact views are missing a hand channel"
                )
        except Exception as exc:
            self._add_task_state_warning(
                "Could not initialize C02 hand/marble contact reporting: "
                f"{exc}"
            )

    def _c02_hand_marble_contact_reading(
        self, side: str | None = None
    ) -> tuple[float, bool]:
        if side is None:
            views = getattr(self, "_c02_marble_hand_contact_views", {})
            if views:
                readings = [
                    self._c02_hand_marble_contact_reading(name)
                    for name in ("right", "left")
                    if name in views
                ]
                if not readings or not all(available for _force, available in readings):
                    return 0.0, False
                return float(sum(force for force, _available in readings)), True
            # Compatibility with older callers that install the aggregate view.
            view = getattr(self, "_c02_marble_hand_contact_view", None)
        else:
            view = getattr(self, "_c02_marble_hand_contact_views", {}).get(side)
        if view is None:
            return 0.0, False
        try:
            matrix = view.get_contact_force_matrix(self._sim_dt)
            if hasattr(matrix, "detach"):
                matrix = matrix.detach().cpu().numpy()
            forces = np.asarray(matrix, dtype=np.float64)
            if forces.size == 0 or not np.all(np.isfinite(forces)):
                return 0.0, False
            return float(np.linalg.norm(forces, axis=-1).sum()), True
        except Exception:
            return 0.0, False

    def _c02_marble_is_in_spoon(self) -> bool:
        try:
            marble = self._pose_for_role("target")
            spoon = getattr(self, "_poses", {}).get("spoon")
        except Exception:
            return False
        if spoon is None or not np.all(np.isfinite(marble)) or not np.all(np.isfinite(spoon)):
            return False
        spoon_matrix = _pose_vector_to_matrix(spoon)
        marble_local = _invert_pose_matrix(spoon_matrix) @ _pose_vector_to_matrix(marble)
        rel = marble_local[:3, 3]
        return bool(
            self._z_axis_alignment(spoon) >= float(np.cos(np.deg2rad(45.0)))
            and abs(float(rel[0])) <= 0.025
            and 0.030 <= float(rel[1]) <= 0.102
            and -0.008 <= float(rel[2]) <= 0.060
        )
    def _ycb05_right_hand_paths_by_finger(self) -> dict[str, list[str]]:
        """Resolve Wuji thumb/index/middle/ring/pinky rigid-link paths."""
        groups = {
            "thumb": [],
            "index": [],
            "middle": [],
            "ring": [],
            "pinky": [],
            "palm": [],
        }
        if self._stage is None:
            return groups
        from pxr import Usd, UsdPhysics

        root = self._stage.GetPrimAtPath("/World/HandsOnRobots/RightRobot")
        finger_names = {
            "right_finger1": "thumb",
            "right_finger2": "index",
            "right_finger3": "middle",
            "right_finger4": "ring",
            "right_finger5": "pinky",
        }
        for prim in Usd.PrimRange(root):
            if not prim.HasAPI(UsdPhysics.RigidBodyAPI):
                continue
            name = prim.GetName()
            if name == "right_palm_link":
                groups["palm"].append(str(prim.GetPath()))
                continue
            for prefix, group in finger_names.items():
                if name.startswith(prefix):
                    groups[group].append(str(prim.GetPath()))
                    break
        return groups

    def _init_ycb05_contact_views(self) -> None:
        self._ycb05_contact_views = {}
        self._ycb05_contact_grace = {}
        if self.task_name != YCB05_TASK_NAME or not self._robots:
            return
        physics_sim_view = self._robots["right"]._physics_sim_view
        groups = self._ycb05_right_hand_paths_by_finger()
        drill_prim = self._find_rigid_body_prim(YCB05_DRILL_NAME)
        trigger_prim = self._find_rigid_body_prim(YCB05_TRIGGER_BODY_NAME)
        wood_prim = self._find_rigid_body_prim(YCB05_WOOD_NAME)
        table_prim = self._find_rigid_body_prim("table")
        if (
            physics_sim_view is None
            or drill_prim is None
            or trigger_prim is None
            or wood_prim is None
            or table_prim is None
            or not all(groups[name] for name in ("thumb", "index", "middle", "ring", "pinky"))
        ):
            self._add_task_state_warning(
                "YCB05 contact reporting is unavailable or finger mapping is incomplete"
            )
            return

        def create_view(key: str, sensor_path: str, filters: list[str]) -> None:
            try:
                view = physics_sim_view.create_rigid_contact_view(
                    sensor_path,
                    filter_patterns=filters,
                    max_contact_data_count=max(64, len(filters) * 12),
                )
                if (
                    view is not None
                    and int(view.sensor_count) == 1
                    and int(view.filter_count) == len(filters)
                ):
                    self._ycb05_contact_views[key] = view
                    self._ycb05_contact_grace[key] = 0
                else:
                    self._add_task_state_warning(
                        f"YCB05 contact view {key} has no sensors or filters"
                    )
            except Exception as exc:
                self._add_task_state_warning(
                    f"Could not initialize YCB05 contact view {key}: {exc}"
                )

        drill_path = str(drill_prim.GetPath())
        trigger_path = str(trigger_prim.GetPath())
        wood_path = str(wood_prim.GetPath())
        table_path = str(table_prim.GetPath())
        create_view("trigger_index", trigger_path, groups["index"])
        wrong_paths = [
            path
            for group in ("thumb", "middle", "ring", "pinky", "palm")
            for path in groups[group]
        ]
        create_view("trigger_wrong", trigger_path, wrong_paths)
        for group in ("thumb", "middle", "ring", "pinky"):
            create_view(f"handle_{group}", drill_path, groups[group])
        create_view("wood_drill", wood_path, [drill_path, trigger_path])
        create_view(
            "wood_hand",
            wood_path,
            [path for paths in groups.values() for path in paths],
        )
        create_view("drill_table", drill_path, [table_path])
        create_view("trigger_table", trigger_path, [table_path])

    def _init_b04_contact_views(self) -> None:
        """Report actual right-hand contacts for every stack body."""
        self._b04_block_contact_views = {}
        if self.task_name not in {"t44_stack_blocks", gen5.TASK_NAME} or not self._robots:
            return
        physics_sim_view = self._task_tensor_sim_view()
        hand_paths = self._c04_right_hand_body_paths()
        if physics_sim_view is None or not hand_paths:
            self._add_task_state_warning(
                "B04 right-hand contact reporting is unavailable"
            )
            return

        max_contacts = max(64, len(hand_paths) * 8)
        try:
            for name in self._stack_block_half_extents:
                block_prim = self._find_rigid_body_prim(name)
                if block_prim is None:
                    continue
                view = physics_sim_view.create_rigid_contact_view(
                    str(block_prim.GetPath()),
                    filter_patterns=hand_paths,
                    max_contact_data_count=max_contacts,
                )
                if (
                    view is not None
                    and int(view.sensor_count) > 0
                    and int(view.filter_count) > 0
                ):
                    self._b04_block_contact_views[name] = view
        except Exception as exc:
            self._b04_block_contact_views = {}
            self._add_task_state_warning(
                f"Could not initialize B04 right-hand contact reporting: {exc}"
            )
            return

        if len(self._b04_block_contact_views) != len(self._stack_block_half_extents):
            self._b04_block_contact_views = {}
            self._add_task_state_warning(
                "B04 contact reporting did not resolve all four block bodies"
            )

    def _ycb02_hand_body_paths(self) -> list[str]:
        if self._stage is None:
            return []
        from pxr import Usd, UsdPhysics

        paths: list[str] = []
        for side in ("right", "left"):
            root = self._stage.GetPrimAtPath(
                f"/World/HandsOnRobots/{side.capitalize()}Robot"
            )
            if not root.IsValid():
                continue
            for prim in Usd.PrimRange(root):
                name = prim.GetName()
                if not prim.HasAPI(UsdPhysics.RigidBodyAPI):
                    continue
                if name == f"{side}_palm_link" or name.startswith(
                    f"{side}_finger"
                ):
                    paths.append(str(prim.GetPath()))
        return paths

    def _init_ycb02_contact_views(self) -> None:
        """Bind ball/cup/table/hand contact truth for every active variant."""
        self._ycb02_contact_views = {}
        self._ycb02_contact_pairs_available = False
        if self.task_name != ycb02.TASK_NAME or not self._robots:
            return

        physics_sim_view = next(iter(self._robots.values()))._physics_sim_view
        hand_paths = self._ycb02_hand_body_paths()
        table_prim = self._find_rigid_body_prim("table")
        if physics_sim_view is None or not hand_paths or table_prim is None:
            self._add_task_state_warning(
                "YCB02 physical contact reporting is unavailable"
            )
            return

        expected = len(ycb02.BALL_NAMES) * (2 + len(ycb02.CUP_NAMES)) + len(
            ycb02.CUP_NAMES
        )
        print(
            f"[HandsOn/IsaacLab] Initializing {expected} YCB02 contact views...",
            flush=True,
        )
        try:
            table_path = str(table_prim.GetPath())
            cup_paths = {
                name: str(self._find_rigid_body_prim(name).GetPath())
                for name in ycb02.CUP_NAMES
                if self._find_rigid_body_prim(name) is not None
            }
            if len(cup_paths) != len(ycb02.CUP_NAMES):
                raise RuntimeError("not all cup rigid bodies resolved")

            for ball_name in ycb02.BALL_NAMES:
                ball_prim = self._find_rigid_body_prim(ball_name)
                if ball_prim is None:
                    raise RuntimeError(f"{ball_name} rigid body unresolved")
                ball_path = str(ball_prim.GetPath())
                filters = {
                    "hand": hand_paths,
                    "table": [table_path],
                    **{
                        cup_name: [cup_path]
                        for cup_name, cup_path in cup_paths.items()
                    },
                }
                for role, patterns in filters.items():
                    view = physics_sim_view.create_rigid_contact_view(
                        ball_path,
                        filter_patterns=patterns,
                        max_contact_data_count=max(64, len(patterns) * 8),
                    )
                    if (
                        view is None
                        or int(view.sensor_count) < 1
                        or int(view.filter_count) < 1
                    ):
                        raise RuntimeError(
                            f"empty {ball_name}/{role} contact view"
                        )
                    self._ycb02_contact_views[(ball_name, role)] = view

            for cup_name, cup_path in cup_paths.items():
                view = physics_sim_view.create_rigid_contact_view(
                    cup_path,
                    filter_patterns=[table_path],
                    max_contact_data_count=64,
                )
                if (
                    view is None
                    or int(view.sensor_count) < 1
                    or int(view.filter_count) < 1
                ):
                    raise RuntimeError(f"empty {cup_name}/table contact view")
                self._ycb02_contact_views[(cup_name, "table")] = view
        except Exception as exc:
            self._ycb02_contact_views = {}
            self._add_task_state_warning(
                f"Could not initialize YCB02 contact reporting: {exc}"
            )
            return

        self._ycb02_contact_pairs_available = (
            len(self._ycb02_contact_views) == expected
        )
        if not self._ycb02_contact_pairs_available:
            self._ycb02_contact_views = {}
            self._add_task_state_warning(
                "YCB02 contact reporting did not resolve every required pair"
            )
        else:
            print(
                f"[HandsOn/IsaacLab] YCB02 contact views ready: {expected}",
                flush=True,
            )


    def _init_ycb09_contact_views(self) -> None:
        """Bind hand, target support, and carry-interruption contact evidence."""
        self._ycb09_contact_views = {}
        self._ycb09_contact_pairs_available = False
        if self.task_name != ycb09.TASK_NAME or not self._robots:
            return

        physics_sim_view = self._robots["right"]._physics_sim_view
        hand_paths = self._c04_right_hand_body_paths()
        glass_prim = self._find_rigid_body_prim(ycb09.GLASS_NAME)
        plate_prim = self._find_rigid_body_prim(ycb09.PLATE_NAME)
        table_prim = self._find_rigid_body_prim("table")
        if (
            physics_sim_view is None
            or not hand_paths
            or glass_prim is None
            or plate_prim is None
            or table_prim is None
        ):
            self._add_task_state_warning(
                "YCB09 glass/plate/table/hand contact reporting is unavailable"
            )
            return

        glass_path = str(glass_prim.GetPath())
        plate_path = str(plate_prim.GetPath())
        table_path = str(table_prim.GetPath())
        filters = {
            "glass_hand": (glass_path, hand_paths),
            "glass_plate": (glass_path, [plate_path]),
            "glass_table": (glass_path, [table_path]),
            "plate_table": (plate_path, [table_path]),
        }
        try:
            for role, (sensor_path, filter_paths) in filters.items():
                view = physics_sim_view.create_rigid_contact_view(
                    sensor_path,
                    filter_patterns=filter_paths,
                    max_contact_data_count=max(64, len(filter_paths) * 8),
                )
                if (
                    view is None
                    or int(view.sensor_count) != 1
                    or int(view.filter_count) != len(filter_paths)
                ):
                    raise RuntimeError(f"empty {role} contact view")
                self._ycb09_contact_views[role] = view
        except Exception as exc:
            self._ycb09_contact_views = {}
            self._add_task_state_warning(
                f"Could not initialize YCB09 contact reporting: {exc}"
            )
            return

        self._ycb09_contact_pairs_available = set(
            self._ycb09_contact_views
        ) == set(filters)
        if not self._ycb09_contact_pairs_available:
            self._ycb09_contact_views = {}
            self._add_task_state_warning(
                "YCB09 contact reporting did not resolve every required pair"
            )

    def _ycb09_contact_force(self, role: str) -> tuple[float, bool]:
        if not self._ycb09_contact_pairs_available:
            return 0.0, False
        view = self._ycb09_contact_views.get(role)
        if view is None:
            return 0.0, False
        try:
            matrix = view.get_contact_force_matrix(self._sim_dt)
            if hasattr(matrix, "detach"):
                matrix = matrix.detach().cpu().numpy()
            forces = np.asarray(matrix, dtype=np.float64)
            if forces.size == 0 or forces.shape[-1] != 3 or not np.all(np.isfinite(forces)):
                return 0.0, False
            return float(np.linalg.norm(forces, axis=-1).sum()), True
        except Exception:
            # A missing hand report must not look like a clean release, and a
            # missing support report must never establish physical support.
            return 0.0, False

    def _init_08_hammer_nail_contact_view(self) -> None:
        """Report physical hammer-body contacts against the articulated nail."""
        self._08_hammer_nail_contact_view = None
        self._08_hammer_nail_contact_views = []
        if self.task_name != "t08_hammer_nail" or not self._robots:
            return
        physics_sim_view = next(iter(self._robots.values()))._physics_sim_view
        hammer_prim = self._find_rigid_body_prim("hammer")
        nail_prim = self._find_rigid_body_prim("nail")
        if physics_sim_view is None or hammer_prim is None or nail_prim is None:
            self._add_task_state_warning(
                "C01 hammer/nail contact reporting is unavailable"
            )
            return
        errors: list[str] = []
        for sensor_prim, filter_prim in (
            (hammer_prim, nail_prim),
            (nail_prim, hammer_prim),
        ):
            try:
                view = physics_sim_view.create_rigid_contact_view(
                    str(sensor_prim.GetPath()),
                    filter_patterns=[str(filter_prim.GetPath())],
                    max_contact_data_count=64,
                )
                if (
                    view is not None
                    and int(view.sensor_count) > 0
                    and int(view.filter_count) > 0
                ):
                    self._08_hammer_nail_contact_views.append(view)
                else:
                    errors.append(
                        f"{sensor_prim.GetName()} sensor has no sensors or filters"
                    )
            except Exception as exc:
                errors.append(f"{sensor_prim.GetName()} sensor: {exc}")

        if self._08_hammer_nail_contact_views:
            # Keep the original field as a compatibility alias for callers
            # that inspect the first contact view.
            self._08_hammer_nail_contact_view = (
                self._08_hammer_nail_contact_views[0]
            )
        else:
            detail = "; ".join(errors) if errors else "no contact views resolved"
            self._add_task_state_warning(
                f"Could not initialize C01 hammer/nail contact reporting: {detail}"
            )

    def _init_c04_contact_views(self) -> None:
        self._c04_trigger_contact_view = None
        self._c04_grasp_contact_views = []
        if self.task_name not in {"t50_water_plant", "eval_gen06_spray_shoe"} or not self._robots:
            return
        physics_sim_view = self._task_tensor_sim_view()
        hand_paths = self._c04_right_hand_body_paths()
        if physics_sim_view is None or not hand_paths:
            self._add_task_state_warning("C04 hand contact reporting is unavailable")
            return

        max_contacts = max(64, len(hand_paths) * 8)
        if self.task_name == "eval_gen06_spray_shoe":
            trigger = self._find_rigid_body_prim("link_0")
            bottle = self._find_rigid_body_prim("link_2")
            if trigger is None or bottle is None:
                raise RuntimeError("GEN7 original trigger/bottle rigid body missing")
            self._c04_trigger_contact_view = physics_sim_view.create_rigid_contact_view(
                str(trigger.GetPath()), filter_patterns=hand_paths,
                max_contact_data_count=max_contacts,
            )
            grasp = physics_sim_view.create_rigid_contact_view(
                str(bottle.GetPath()), filter_patterns=hand_paths,
                max_contact_data_count=max_contacts,
            )
            for view in (self._c04_trigger_contact_view, grasp):
                if view is None or int(view.sensor_count) < 1 or int(view.filter_count) < 1:
                    raise RuntimeError("GEN7 physical hand contact sensor unavailable")
            self._c04_grasp_contact_views = [grasp]
            print("[GEN7 contacts] trigger=" + str(trigger.GetPath()) + " bottle=" + str(bottle.GetPath()), flush=True)
            return

        try:
            self._c04_trigger_contact_view = physics_sim_view.create_rigid_contact_view(
                f"{_TASK_ROOT}/link_2/link_0",
                filter_patterns=hand_paths,
                max_contact_data_count=max_contacts,
            )
            for path in (
                f"{_TASK_ROOT}/link_2/link_1",
                f"{_TASK_ROOT}/link_2/link_2",
            ):
                view = physics_sim_view.create_rigid_contact_view(
                    path,
                    filter_patterns=hand_paths,
                    max_contact_data_count=max_contacts,
                )
                if int(view.sensor_count) > 0 and int(view.filter_count) > 0:
                    self._c04_grasp_contact_views.append(view)
        except Exception as exc:
            self._c04_trigger_contact_view = None
            self._c04_grasp_contact_views = []
            self._add_task_state_warning(
                f"Could not initialize C04 hand contact reporting: {exc}"
            )

    def _init_c06_shutter_contact_view(self) -> None:
        # The shutter is a child of the free camera articulation.  Creating a
        # rigid-contact tensor view for that child requires a contact-report
        # API on the same prim, which corrupts the Isaac Sim 5.1 GPU
        # narrowphase table during the first reset.  C06 instead validates
        # right-hand ownership from the visible Wuji fingertips and keeps the
        # real prismatic-joint travel as the press condition.
        self._c06_shutter_contact_view = None

    def _init_ycb07_contact_views(self) -> None:
        self._ycb07_button_contact_views = {"right": {}, "left": {}}
        self._ycb07_chassis_contact_views = {"right": None, "left": None}
        if self.task_name != _YCB07_TASK_NAME or not self._robots:
            return
        physics_sim_view = next(iter(self._robots.values()))._physics_sim_view
        timer_prim = self._find_rigid_body_prim(_YCB07_TIMER_NAME)
        if physics_sim_view is None or timer_prim is None:
            self._add_task_state_warning(
                "YCB07 timer/hand contact reporting is unavailable"
            )
            return

        errors: list[str] = []
        for side in ("right", "left"):
            tip_paths = self._ycb07_hand_body_paths(
                side,
                fingertips_only=True,
            )
            hand_paths = self._ycb07_hand_body_paths(
                side,
                fingertips_only=False,
            )
            try:
                chassis_view = physics_sim_view.create_rigid_contact_view(
                    str(timer_prim.GetPath()),
                    filter_patterns=hand_paths,
                    max_contact_data_count=max(64, len(hand_paths) * 8),
                )
                if (
                    chassis_view is not None
                    and int(chassis_view.sensor_count) > 0
                    and int(chassis_view.filter_count) > 0
                ):
                    self._ycb07_chassis_contact_views[side] = chassis_view
                else:
                    errors.append(f"{side} chassis contact view is empty")
            except Exception as exc:
                errors.append(f"{side} chassis: {exc}")

            for index, body_name in enumerate(_YCB07_BUTTON_BODIES):
                button_prim = self._find_rigid_body_prim(body_name)
                if button_prim is None or not tip_paths:
                    errors.append(f"{side} {body_name}: prim/fingertips unavailable")
                    continue
                try:
                    view = physics_sim_view.create_rigid_contact_view(
                        str(button_prim.GetPath()),
                        filter_patterns=tip_paths,
                        max_contact_data_count=max(64, len(tip_paths) * 8),
                    )
                    if (
                        view is not None
                        and int(view.sensor_count) > 0
                        and int(view.filter_count) > 0
                    ):
                        self._ycb07_button_contact_views[side][index] = view
                    else:
                        errors.append(f"{side} {body_name}: empty contact view")
                except Exception as exc:
                    errors.append(f"{side} {body_name}: {exc}")
        if errors:
            self._add_task_state_warning(
                "YCB07 contact reporting is incomplete: " + "; ".join(errors)
            )

