    @staticmethod
    def _task_specific_pair_distance(task_name: str, name_a: str, name_b: str) -> float:
        return float(
            _TASK_SPECIFIC_RESET_PAIR_DISTANCE.get(
                (task_name, frozenset((name_a, name_b))),
                _TASK_SPECIFIC_RESET_DEFAULT_PAIR_DISTANCE,
            )
        )

    def _b04_point_footprint_margin(
        self,
        point_xyz: np.ndarray,
        body_xy: np.ndarray,
        body_name: str,
    ) -> float:
        """Signed 3-D margin from a robot origin to a swept B04 block.

        B04 randomizes yaw after choosing XY.  Its collision-safe envelope is
        therefore a vertical cylinder whose radius is the block's full XY
        half-diagonal.  Retain that conservative rotation envelope, but use
        the block's real support height as well: the inactive left hand is
        raised roughly 0.6 m above the table and cannot collide with a block
        even when its XY projection overlaps the staging lane.
        """
        point = np.asarray(point_xyz, dtype=np.float64).reshape(3)
        xy = np.asarray(body_xy, dtype=np.float64).reshape(2)
        half_height = float(_STACK_BLOCK_HALF_EXTENTS[body_name][2])
        center_z = _TABLE_TOP_Z + float(self.delta_h[0]) + half_height
        radial_offset = (
            float(np.linalg.norm(point[:2] - xy))
            - _B04_RESET_FOOTPRINT_RADII[body_name]
        )
        vertical_offset = abs(float(point[2]) - center_z) - half_height
        outside = np.maximum(
            np.asarray([radial_offset, vertical_offset], dtype=np.float64),
            0.0,
        )
        if np.any(outside > 0.0):
            distance = float(np.linalg.norm(outside))
        else:
            # Inside the finite swept cylinder, the least-negative component
            # is the signed distance to its closest surface.
            distance = max(radial_offset, vertical_offset)
        return distance - _B04_RESET_HAND_CLEARANCE_MARGIN

    def _ycb09_point_footprint_margin(
        self,
        point_xyz: np.ndarray,
        body_xy: np.ndarray,
        body_name: str,
    ) -> float:
        """Signed 3-D reset clearance for an original YCB09 body.

        A 2-D projection rejects every valid YCB09 layout because several
        reset-home arm origins pass above the task lanes.  Screen against the
        exact finite swept cylinder instead, retaining the shared 85 mm robot
        origin safety margin without treating elevated links as table-plane
        collisions.
        """
        point = np.asarray(point_xyz, dtype=np.float64).reshape(3)
        xy = np.asarray(body_xy, dtype=np.float64).reshape(2)
        radius = {
            ycb09.GLASS_NAME: ycb09.GLASS_FOOTPRINT_RADIUS_M,
            ycb09.PLATE_NAME: ycb09.PLATE_FOOTPRINT_RADIUS_M,
        }[body_name]
        local_min_z, local_max_z = {
            ycb09.GLASS_NAME: (
                ycb09.GLASS_LOCAL_MIN_Z_M,
                ycb09.GLASS_LOCAL_MAX_Z_M,
            ),
            ycb09.PLATE_NAME: (
                ycb09.PLATE_LOCAL_MIN_Z_M,
                ycb09.PLATE_LOCAL_MAX_Z_M,
            ),
        }[body_name]
        half_height = 0.5 * float(local_max_z - local_min_z)
        center_z = (
            _TABLE_TOP_Z
            + float(self.delta_h[0])
            + half_height
        )
        radial_offset = float(np.linalg.norm(point[:2] - xy)) - float(radius)
        vertical_offset = abs(float(point[2]) - center_z) - half_height
        outside = np.maximum(
            np.asarray([radial_offset, vertical_offset], dtype=np.float64),
            0.0,
        )
        if np.any(outside > 0.0):
            distance = float(np.linalg.norm(outside))
        else:
            distance = max(radial_offset, vertical_offset)
        return distance - _TASK_OBJECT_HAND_CLEARANCE

    def _b05_point_footprint_margin(
        self,
        point_xyz: np.ndarray,
        body_xy: np.ndarray,
        body_name: str,
    ) -> float:
        """Signed 3-D point-to-box margin for B05's swept yaw envelope.

        The active right hand starts above the thin lid.  Treating every robot
        body origin as if it lived in the table plane rejects every valid B05
        lane, makes the sampler return ``None``, and silently restores the old
        overlapping authored poses.  Include the exact support height so an
        elevated hand is accepted while a genuinely intersecting hand still
        fails closed.
        """
        point = np.asarray(point_xyz, dtype=np.float64).reshape(3)
        half_height = _B05_HALF_HEIGHTS[body_name]
        body_center = np.asarray(
            [
                float(body_xy[0]),
                float(body_xy[1]),
                _TABLE_TOP_Z
                + float(self.delta_h[0])
                + _B05_RESET_SUPPORT_CLEARANCE
                + half_height,
            ],
            dtype=np.float64,
        )
        half_extents = np.asarray(
            [
                *_B05_RESET_FOOTPRINT_HALF_EXTENTS[body_name],
                half_height,
            ],
            dtype=np.float64,
        )
        offset = (
            np.abs(point - body_center)
            - half_extents
        )
        outside = np.maximum(offset, 0.0)
        if np.any(outside > 0.0):
            distance = float(np.linalg.norm(outside))
        else:
            # A point inside the footprint has a negative signed clearance.
            distance = float(np.max(offset))
        return distance - _B05_OBJECT_HAND_CLEARANCE_MARGIN

    @staticmethod
    def _b05_pair_footprint_margin(
        xy_a: np.ndarray,
        name_a: str,
        xy_b: np.ndarray,
        name_b: str,
    ) -> float:
        """Conservative separating-axis margin across B05's yaw band."""
        center_delta = np.abs(
            np.asarray(xy_a, dtype=np.float64)
            - np.asarray(xy_b, dtype=np.float64)
        )
        axis_gaps = (
            center_delta
            - _B05_RESET_FOOTPRINT_HALF_EXTENTS[name_a]
            - _B05_RESET_FOOTPRINT_HALF_EXTENTS[name_b]
            - _B05_OBJECT_CLEARANCE_MARGIN
        )
        # Axis-aligned OBBs are disjoint when at least one separating axis has
        # non-negative clearance.  Returning the best axis preserves that
        # signed fail-closed condition for the sampler.
        return float(np.max(axis_gaps))

    def _task_specific_reset_layout_margin(
        self,
        xy_by_name: dict[str, np.ndarray],
        hand_points: tuple[np.ndarray, ...],
    ) -> float:
        margin = math.inf
        for name, xy in xy_by_name.items():
            if self.task_name == _FU006_TASK_NAME and name == "fu006_charger":
                hand_clearance = min(
                    (
                        float(np.linalg.norm(xy - point[:2]))
                        - float(np.linalg.norm(_FU006_CHARGER_HALF_EXTENTS[:2]))
                        - _FU006_RESET_CLEARANCE_MARGIN
                        for point in hand_points
                    ),
                    default=math.inf,
                )
                drawer_axis_gaps = np.maximum(
                    _FU006_DRAWER_FOOTPRINT_MIN
                    - xy
                    - _FU006_CHARGER_HALF_EXTENTS[:2],
                    xy
                    - _FU006_DRAWER_FOOTPRINT_MAX
                    - _FU006_CHARGER_HALF_EXTENTS[:2],
                ) - _FU006_RESET_CLEARANCE_MARGIN
                margin = min(
                    margin,
                    hand_clearance,
                    float(np.max(drawer_axis_gaps)),
                )
            elif self.task_name == ycb09.TASK_NAME:
                hand_clearance = min(
                    (
                        self._ycb09_point_footprint_margin(
                            point,
                            xy,
                            name,
                        )
                        for point in hand_points
                    ),
                    default=math.inf,
                )
                margin = min(margin, hand_clearance)
            elif self.task_name == "t03_cover_box":
                hand_clearance = min(
                    (
                        self._b05_point_footprint_margin(
                            point,
                            xy,
                            name,
                        )
                        for point in hand_points
                    ),
                    default=math.inf,
                )
                margin = min(margin, hand_clearance)
            elif self.task_name == "t44_stack_blocks":
                hand_clearance = min(
                    (
                        self._b04_point_footprint_margin(
                            point,
                            xy,
                            name,
                        )
                        for point in hand_points
                    ),
                    default=math.inf,
                )
                margin = min(margin, hand_clearance)
            elif self.task_name == gen5.TASK_NAME:
                half = np.asarray(gen5.half_extents()[name][:2], dtype=np.float64)
                half_height = float(gen5.half_extents()[name][2])
                center = np.asarray(
                    [float(xy[0]), float(xy[1]),
                     _TABLE_TOP_Z + float(self.delta_h[0]) + half_height],
                    dtype=np.float64,
                )
                # Signed point-to-box distance, including the actual object
                # footprint rather than treating a carton as a point mass.
                point_margins = []
                for point in hand_points:
                    offset = np.abs(np.asarray(point, dtype=np.float64) - center) - np.asarray([*half, half_height])
                    outside = np.maximum(offset, 0.0)
                    distance = float(np.linalg.norm(outside)) if np.any(outside > 0.0) else float(np.max(offset))
                    point_margins.append(distance - _GEN5_RESET_HAND_CLEARANCE)
                # Interface-only probes expose TCP origins, while the live
                # wrist/camera collision extends roughly 20 cm to the left.
                # Apply the measured conservative rectangle as an additional
                # reset guard so the authored carton cannot start in that
                # swept volume when no articulation is available.
                rect = _GEN5_RIGHT_HAND_RESET_RECT
                gap = np.maximum(
                    np.maximum(rect[0] - np.asarray(xy), np.asarray(xy) - rect[1]),
                    0.0,
                ) - half
                rect_margin = float(np.max(gap)) - 0.005
                margin = min(margin, min(point_margins, default=math.inf), rect_margin)
            else:
                hand_clearance = min(
                    (
                        float(np.linalg.norm(xy - point[:2]))
                        for point in hand_points
                    ),
                    default=math.inf,
                )
                margin = min(margin, hand_clearance - _TASK_OBJECT_HAND_CLEARANCE)

        names = sorted(xy_by_name)
        for index, name_a in enumerate(names):
            for name_b in names[index + 1 :]:
                if self.task_name == "t03_cover_box":
                    pair_margin = self._b05_pair_footprint_margin(
                        xy_by_name[name_a],
                        name_a,
                        xy_by_name[name_b],
                        name_b,
                    )
                elif self.task_name == "t44_stack_blocks":
                    pair_margin = (
                        float(
                            np.linalg.norm(
                                xy_by_name[name_a] - xy_by_name[name_b]
                            )
                        )
                        - _B04_RESET_FOOTPRINT_RADII[name_a]
                        - _B04_RESET_FOOTPRINT_RADII[name_b]
                        - _B04_RESET_OBJECT_CLEARANCE_MARGIN
                    )
                elif self.task_name == gen5.TASK_NAME:
                    ext_a = np.asarray(gen5.half_extents()[name_a][:2], dtype=np.float64)
                    ext_b = np.asarray(gen5.half_extents()[name_b][:2], dtype=np.float64)
                    axis_gaps = (
                        np.abs(np.asarray(xy_by_name[name_a]) - np.asarray(xy_by_name[name_b]))
                        - ext_a - ext_b - 0.010
                    )
                    pair_margin = float(np.max(axis_gaps))
                else:
                    distance = float(
                        np.linalg.norm(xy_by_name[name_a] - xy_by_name[name_b])
                    )
                    pair_margin = distance - self._task_specific_pair_distance(
                        self.task_name,
                        name_a,
                        name_b,
                    )
                margin = min(margin, pair_margin)
        return float(margin)

    def _customize_task_reset_pose(
        self,
        name: str,
        pose_xyzw: np.ndarray,
        *,
        applied_height: float,
    ) -> np.ndarray:
        """Apply a task's support pose after generic reset randomization."""
        if self.task_name == gen1.TASK_NAME and name == gen1.BODY_NAME:
            pose = gen1.sample_reset_pose(
                self._random, gen1.geometry(), _TABLE_TOP_Z + applied_height,
                randomize=self.randomize,
            )
            self._gen1_sampled_reset_pose = pose.copy()
            result = np.asarray(pose_xyzw).copy()
            result[:, :3] = pose[:3]
            result[:, 3:7] = pose[[4, 5, 6, 3]]
            print(f"[HandsOn/IsaacLab] GEN1 reset pose WXYZ: {pose.tolist()}", flush=True)
            return result
        if self.task_name == gen2_geometry.TASK_NAME and name in gen2_geometry.BODY_NAMES:
            result = np.asarray(pose_xyzw, dtype=np.float64).copy()
            support_z = (
                _TABLE_TOP_Z
                - gen2_geometry.SUPPORT_MIN_Z[name]
                + gen2_geometry.CONTACT_OFFSET
                + applied_height
            )
            if result.ndim == 1:
                result[2] = support_z
            else:
                result[:, 2] = support_z
            return result
        return pose_xyzw

    def _reset_box_clears_hands(
        self, pose, half_extents, center_local=(0.0, 0.0, 0.0)
    ) -> bool:
        """Screen a rotated object box against the complete Wuji hand envelope.

        Capsules are covered by overlapping spheres, including the distal
        fingertip offset; arm origins retain the shared conservative margin.
        These shapes are analytic reset checks only, never scene colliders.
        """
        if not self._robots:
            return True
        centers, radii = [], []
        for robot in self._robots.values():
            poses = robot.data.body_pose_w[0]
            if hasattr(poses, "detach"):
                poses = poses.detach().cpu().numpy()
            for name, body_pose in zip(robot.body_names, poses):
                name = str(name).lower()
                transform = _pose_vector_to_matrix(np.asarray(body_pose))
                origin, rotation = transform[:3, 3], transform[:3, :3]
                if "palm" in name:
                    centers.append(origin + rotation @ np.array([0.0, 0.0, 0.035]))
                    radii.append(float(np.linalg.norm([0.035, 0.026, 0.055])))
                elif "finger" in name:
                    for link, radius, half_length in (
                        ("link1", 0.008, 0.012),
                        ("link2", 0.007, 0.017),
                        ("link3", 0.0065, 0.017),
                        ("link4", 0.006, 0.014),
                    ):
                        if link in name:
                            for z in np.linspace(-half_length, half_length, 9):
                                centers.append(origin + rotation[:, 2] * z)
                                radii.append(radius + half_length / 8)
                    if "link4" in name:
                        tip_z = 0.0313 if "finger1" in name else 0.0267
                        centers.append(origin + rotation @ np.array([-0.00105, 0.0, tip_z]))
                        radii.append(0.0088)
                elif "base" not in name:
                    centers.append(origin)
                    radii.append(_TASK_OBJECT_HAND_CLEARANCE)
        if not centers:
            raise RuntimeError("Cannot read robot collision envelopes during task reset")
        transform = _pose_vector_to_matrix(np.asarray(pose, dtype=np.float64))
        local = (np.asarray(centers) - transform[:3, 3]) @ transform[:3, :3]
        offsets = np.abs(local - np.asarray(center_local)) - np.asarray(half_extents)
        distances = np.linalg.norm(np.maximum(offsets, 0.0), axis=1)
        return bool(np.all(distances - np.asarray(radii) >= 0.003))

    def _task_specific_reset_xy_positions(self) -> dict[str, np.ndarray] | None:
        if self.task_name == ycb02.TASK_NAME:
            return self._ycb02_reset_xy_positions()

        if self.task_name == YCB05_TASK_NAME:
            if not self._ycb05_sampled_reset_poses:
                raise RuntimeError("YCB05 reset layout was not sampled before pose write")
            for attempt in range(128):
                layout = self._ycb05_sampled_reset_poses
                if (self._reset_box_clears_hands(layout[YCB05_DRILL_NAME], (.030, .092, .094))
                        and self._reset_box_clears_hands(layout[YCB05_WOOD_NAME], (.044, .101, .043))):
                    return {name: pose[:2].copy() for name, pose in layout.items()}
                if not self.randomize:
                    break
                self._ycb05_sampled_reset_poses = sample_ycb05_layout(
                    self._random, randomize=True, table_top_z=_TABLE_TOP_Z + float(self.delta_h[0]))
            raise RuntimeError("YCB05 cannot sample a layout clear of the reset hands")
        if self.task_name == "t25_place_cup_on_plate":
            return self._a02_reset_xy_positions()
        if self.task_name == "t24_place_ball_in_bowl":
            return self._a03_reset_xy_positions()
        if self.task_name == "t04_cover_pitcher":
            return self._b01_reset_xy_positions()
        bounds_by_name = _TASK_SPECIFIC_RESET_XY_BOUNDS.get(self.task_name)
        if bounds_by_name is None:
            return None
        if not self.randomize:
            if self.task_name == _FU006_TASK_NAME:
                return {"fu006_charger": _FU006_CHARGER_RESET_XY.copy()}
            if self.task_name == "t03_cover_box":
                return {
                    name: xy.copy()
                    for name, xy in _B05_RESET_XY_FALLBACK.items()
                }
            if self.task_name == gen2_geometry.TASK_NAME:
                return {
                    name: np.asarray(bounds, dtype=np.float64).mean(axis=0)
                    for name, bounds in gen2_geometry.RESET_XY_BOUNDS.items()
                }
            if self.task_name == gen5.TASK_NAME:
                return {
                    name: np.asarray(bounds, dtype=np.float64).mean(axis=0)
                    for name, bounds in gen5.RESET_XY_BOUNDS.items()
                }
            return None

        hand_points = (
            *self._reset_robot_body_points("right"),
            *self._reset_robot_body_points("left"),
        )
        best: dict[str, np.ndarray] | None = None
        best_margin = -math.inf
        for _ in range(_TASK_OBJECT_RESET_MAX_ATTEMPTS):
            sample_order = list(bounds_by_name)
            self._random.shuffle(sample_order)
            candidate: dict[str, np.ndarray] = {}
            failed = False

            for name in sample_order:
                bounds = bounds_by_name[name]
                accepted_xy: np.ndarray | None = None
                accepted_margin = -math.inf

                for _candidate_index in range(_TASK_OBJECT_RESET_CANDIDATES_PER_OBJECT):
                    sampled_xy = self._random.uniform(bounds[0], bounds[1])
                    # FU006 stages the charger just outside the cabinet's
                    # negative-Y footprint.  Its task-specific footprint and
                    # hand-clearance checks below are the authoritative reset
                    # screen; the generic tabletop centre clamp would move it
                    # back toward the cabinet and invalidate those bounds.
                    xy = (
                        np.asarray(sampled_xy, dtype=np.float64)
                        if self.task_name in {_FU006_TASK_NAME, gen5.TASK_NAME}
                        else constrain_recording_object_xy(sampled_xy)
                    )
                    partial_candidate = dict(candidate)
                    partial_candidate[name] = xy
                    margin = self._task_specific_reset_layout_margin(
                        partial_candidate,
                        hand_points,
                    )
                    if margin > accepted_margin:
                        accepted_xy = xy
                        accepted_margin = margin
                    if margin >= _TASK_OBJECT_RESET_MIN_CLEARANCE_SLACK:
                        accepted_xy = xy
                        accepted_margin = margin
                        break

                if (
                    accepted_xy is None
                    or accepted_margin < _TASK_OBJECT_RESET_MIN_CLEARANCE_SLACK
                ):
                    failed = True
                    break

                candidate[name] = accepted_xy

            if failed or set(candidate) != set(bounds_by_name):
                continue

            margin = self._task_specific_reset_layout_margin(candidate, hand_points)
            if margin > best_margin:
                best = {name: xy.copy() for name, xy in candidate.items()}
                best_margin = margin
            if margin >= _TASK_OBJECT_RESET_MIN_CLEARANCE_SLACK:
                return candidate

        if best is not None and best_margin >= _TASK_OBJECT_RESET_MIN_CLEARANCE_SLACK:
            return best
        if self.task_name == "t44_stack_blocks":
            raise RuntimeError(
                "t44_stack_blocks 无法生成完整旋转包络无穿模初始布局"
            )
        if self.task_name == "t03_cover_box":
            # The full robot-origin screen is intentionally conservative and
            # can reject every sample even though the proven opposite-Y lanes
            # are physically clear.  Never fall back to the overlapping source
            # poses: retain bounded seeded position randomization around the
            # static layout that is validated in the real simulator.
            common_x = float(self._random.uniform(-0.010, 0.010))
            return {
                "Clear_Box": _B05_RESET_XY_FALLBACK["Clear_Box"]
                + np.asarray(
                    [common_x, self._random.uniform(-0.010, 0.010)],
                    dtype=np.float64,
                ),
                "Box_lid": _B05_RESET_XY_FALLBACK["Box_lid"]
                + np.asarray(
                    [common_x, self._random.uniform(-0.010, 0.010)],
                    dtype=np.float64,
                ),
            }
        if self.task_name == gen2_geometry.TASK_NAME:
            return {
                name: np.asarray(xy, dtype=np.float64)
                + (self._random.uniform(-0.005, 0.005, size=2) if self.randomize else 0.0)
                for name, xy in gen2_geometry.DEFAULT_XY.items()
            }
        if self.task_name == ycb09.TASK_NAME:
            diagnostics: dict[str, dict[str, Any]] = {}
            for name, bounds in bounds_by_name.items():
                best_margin = -math.inf
                best_xy = np.asarray(bounds, dtype=np.float64).mean(axis=0)
                limiting_point = np.zeros(3, dtype=np.float64)
                for x in np.linspace(float(bounds[0, 0]), float(bounds[1, 0]), 7):
                    for y in np.linspace(float(bounds[0, 1]), float(bounds[1, 1]), 7):
                        xy = np.asarray([x, y], dtype=np.float64)
                        point_margins = [
                            (
                                self._ycb09_point_footprint_margin(
                                    point,
                                    xy,
                                    name,
                                ),
                                point,
                            )
                            for point in hand_points
                        ]
                        candidate_margin, candidate_point = min(
                            point_margins,
                            key=lambda item: item[0],
                        )
                        if candidate_margin > best_margin:
                            best_margin = float(candidate_margin)
                            best_xy = xy.copy()
                            limiting_point = np.asarray(
                                candidate_point,
                                dtype=np.float64,
                            ).copy()
                diagnostics[name] = {
                    "best_margin_m": best_margin,
                    "best_xy": best_xy.round(6).tolist(),
                    "limiting_robot_origin": limiting_point.round(6).tolist(),
                }
            raise RuntimeError(
                "YCB09 could not sample a supported, collision-free randomized "
                f"layout; clearance diagnostics={diagnostics}"
            )
        if self.task_name == _FU006_TASK_NAME:
            return {"fu006_charger": _FU006_CHARGER_RESET_XY.copy()}
        if self.task_name == gen5.TASK_NAME:
            result = {}
            for name, xy in gen5.RESET_XY.items():
                jitter = self._random.uniform(-0.005, 0.005, size=2) if self.randomize else np.zeros(2)
                result[name] = np.asarray(xy, dtype=np.float64) + jitter
            return result
        return None

    def _hl015_cover_reset_xy(self, count: int = 1) -> np.ndarray:
        """Sample independent, reachable cover centers for HL015.

        The strip, plug, and cable share a group yaw.  The cover is a separate
        pickup and must not inherit that group's XY transform: doing so pushes
        its authored ``(-0.05, 0.30)`` pose beyond the shared workspace, where
        the generic clamp creates a large point mass on the boundary.  Keep
        the cover's existing yaw semantics (the caller still applies the group
        yaw to its orientation), but draw its center directly from the
        validated upper lane.
        """
        sample_count = max(1, int(count))
        if not self.randomize:
            center = _HL015_COVER_XY_BOUNDS.mean(axis=0)
            return np.broadcast_to(center, (sample_count, 2)).copy()
        return np.asarray(
            self._random.uniform(
                _HL015_COVER_XY_BOUNDS[0],
                _HL015_COVER_XY_BOUNDS[1],
                size=(sample_count, 2),
            ),
            dtype=np.float64,
        )

    def _apply_hs005_pose_randomization(self) -> None:
        """Apply the exact seeded B320-HS005 reset envelope to dynamic roots."""
        if self.task_name != _HS005_TASK_NAME:
            return

        selected = _sample_hs005_reset_offsets(
            self._random,
            randomize=bool(self.randomize),
        )

        values = {
            "hs005_bottle": (selected[0], selected[1], selected[2]),
            "hs005_brush": (selected[3], selected[4], selected[5]),
        }
        reset_z = _HS005_RESET_ROOT_Z_BY_SCENE.get(
            selected_simulation_scene(),
            _HS005_RESET_ROOT_Z_BY_SCENE[HS005_MODERN_APARTMENT_SINK_SCENE],
        )
        for name, (dx, dy, yaw) in values.items():
            view = self._task_body_views.get(name)
            entry = next(
                (
                    item
                    for item in self._task_reset_body_states
                    if item[1] is view
                ),
                None,
            )
            if entry is None:
                raise RuntimeError(f"HS005 reset truth is missing dynamic body {name}")
            path, reset_view, indices, root_pose, root_velocity = entry
            base_reset_pose = (
                np.asarray(
                    [*_HS005_BOTTLE_RESET_XY, reset_z[0], 0.0, 0.0, 0.0, 1.0],
                    dtype=np.float64,
                )
                if name == "hs005_bottle"
                else np.asarray(
                    [
                        *_HS005_BRUSH_STABLE_RESET_POSE_XYZW[:2],
                        reset_z[1],
                        *_HS005_BRUSH_STABLE_RESET_POSE_XYZW[3:],
                    ],
                    dtype=np.float64,
                )
            )
            base_pose = np.repeat(
                base_reset_pose.reshape(1, 7),
                int(root_pose.shape[0]),
                axis=0,
            )
            randomized_pose = _randomized_physx_pose(
                base_pose,
                xy_offset=np.asarray([dx, dy], dtype=np.float64),
                z_offset=0.0,
                yaw_degrees=yaw,
            )
            pose_tensor = self._torch.as_tensor(
                randomized_pose,
                dtype=root_pose.dtype,
                device=root_pose.device,
            )
            self._write_rigid_reset_state(
                path,
                reset_view,
                indices,
                pose_tensor,
                self._torch.zeros_like(root_velocity),
            )
            pose_xyzw = randomized_pose.reshape(-1, 7)[0]
            pose_wxyz = np.concatenate(
                [pose_xyzw[:3], pose_xyzw[6:7], pose_xyzw[3:6]]
            ).astype(np.float64)
            if name == "hs005_bottle":
                self._hs005_bottle_reset_pose = pose_wxyz
            else:
                self._hs005_brush_reset_pose = pose_wxyz

        self._hs005_reset_parameters[:] = np.asarray(
            [
                *selected[:3],
                *selected[3:],
                self._hs005_friction,
                self._hs005_bottle_mass_scale,
                self._hs005_brush_mass_scale,
            ],
            dtype=np.float64,
        )

    def _apply_hs005_dynamics_parameters(self) -> None:
        if self.task_name not in {_HS005_TASK_NAME, _XY4_TASK_NAME} or self._stage is None:
            return
        from pxr import UsdPhysics

        masses = {
            "hs005_bottle": _HS005_BOTTLE_MASS_KG * self._hs005_bottle_mass_scale,
            "hs005_brush": _HS005_BRUSH_MASS_KG * self._hs005_brush_mass_scale,
        }
        for name, mass in masses.items():
            prim = self._find_rigid_body_prim(name)
            if prim is None:
                raise RuntimeError(f"HS005 mass owner is missing: {name}")
            mass_api = UsdPhysics.MassAPI(prim)
            if not mass_api:
                mass_api = UsdPhysics.MassAPI.Apply(prim)
            mass_api.CreateMassAttr().Set(float(mass))

        material_prim = self._stage.GetPrimAtPath(
            getattr(self, "_hs005_material_path",
                    f"{_TASK_ROOT}/HS005Assets/Looks/HS005PhysicsMaterial")
        )
        if not material_prim.IsValid():
            raise RuntimeError("HS005 physics material is missing")
        material_api = UsdPhysics.MaterialAPI(material_prim)
        material_api.CreateStaticFrictionAttr().Set(float(self._hs005_friction))
        material_api.CreateDynamicFrictionAttr().Set(float(self._hs005_friction))

    def _apply_ycb01_reset_layout(
        self,
        reset_state_by_path: Mapping[str, tuple[Any, Any, Any, Any]],
        reset_articulation_by_path: Mapping[str, tuple[Any, Any, Any, Any]],
        *,
        applied_height: float,
    ) -> None:
        """Author all three YCB01 free-body poses from one sampled gate frame."""
        hand_points = (
            *self._reset_robot_body_points("right"),
            *self._reset_robot_body_points("left"),
        )
        layout: dict[str, np.ndarray] | None = None
        for _ in range(64):
            candidate = sample_ycb01_layout(
                self._random,
                randomize=self.randomize,
                table_top_z=_TABLE_TOP_Z + applied_height,
            )
            ball_center = candidate[YCB01_BALL_NAME][:3]
            ball_hand_distance = min(
                (
                    float(np.linalg.norm(ball_center - point[:3]))
                    for point in hand_points
                ),
                default=math.inf,
            )
            if ball_hand_distance >= 0.075:
                layout = candidate
                break
            if not self.randomize:
                break
        if layout is None:
            raise RuntimeError("YCB01 could not sample a robot-clear reset layout")

        # Keep the authored gate pose unchanged and mirror only the ball's
        # travel contract.  A positive local-Y start is an image-left start
        # and therefore travels toward local -Y; a negative start travels
        # toward local +Y as in the historical episodes.
        ball_local = world_to_ycb01_gate(
            layout[YCB01_BALL_NAME][:3],
            layout["gate_frame"],
        )
        self._ycb01_travel_direction = (
            -1.0 if float(ball_local[1]) > 0.0 else 1.0
        )

        for name in (YCB01_BALL_NAME, *YCB01_GATE_BODY_NAMES):
            prim = self._find_rigid_body_prim(name)
            if prim is None:
                raise RuntimeError(f"YCB01 reset body is unavailable: {name}")
            path = str(prim.GetPath())
            state = self._reset_transform_state_for_path(
                path,
                reset_state_by_path,
                reset_articulation_by_path,
            )
            if state is None:
                raise RuntimeError(f"YCB01 reset tensor is unavailable: {name}")
            state_kind, view, indices, root_pose, root_velocity = state
            pose_wxyz = layout[name]
            pose_xyzw = np.concatenate(
                [pose_wxyz[:3], pose_wxyz[4:7], pose_wxyz[3:4]]
            ).reshape(1, 7)
            pose_xyzw = np.repeat(pose_xyzw, int(root_pose.shape[0]), axis=0)
            pose_tensor = self._torch.as_tensor(
                pose_xyzw,
                dtype=root_pose.dtype,
                device=root_pose.device,
            )
            zero_velocity = self._torch.zeros_like(root_velocity)
            if state_kind == "articulation":
                view.set_root_transforms(pose_tensor, indices)
                view.set_root_velocities(zero_velocity, indices)
                self._record_authored_task_reset_write(
                    path,
                    transform_xyzw=pose_tensor,
                    velocity=zero_velocity,
                )
            else:
                self._write_rigid_reset_state(
                    path,
                    view,
                    indices,
                    pose_tensor,
                    zero_velocity,
                )

        self._ycb01_sampled_reset_poses = {
            name: pose.copy() for name, pose in layout.items()
        }
        self._ycb01_gate_frame_pose = layout["gate_frame"].copy()
        self._ycb01_reset_post_poses = {
            name: layout[name].copy() for name in YCB01_GATE_BODY_NAMES
        }
        print(
            "[HandsOn/IsaacLab] YCB01 reset layout: "
            f"gate={self._ycb01_gate_frame_pose[:2].round(4).tolist()}, "
            f"ball={layout[YCB01_BALL_NAME][:2].round(4).tolist()}, "
            f"width={YCB01_GATE_WIDTH_M:.3f}m",
            flush=True,
        )

    def _apply_task_pose_randomization(self) -> None:
        if self.task_name == xy3.TASK_NAME:
            xy3_runtime.apply_reset_layout(self)
            return
        if not self._task_reset_body_states and not self._task_reset_articulation_states:
            return
        if self.task_name == _HS005_TASK_NAME:
            self._apply_hs005_pose_randomization()
            return
        if not self.randomize and self.task_name not in {
            gen1.TASK_NAME,
            "eval_gen06_spray_shoe",
            "t26_place_fruit_in_bucket",
            "t19_orient_cup_upright",
            "t04_cover_pitcher",
            "t09_insert_peg",
            "t44_stack_blocks",
            "t08_hammer_nail",
            "t36_scoop_marbles",
            "t50_water_plant",
            "t14_move_and_click_mouse",
            "t23_photograph_logo",
            "c07_pitcher_pour_cup",
            "t11_line_up_blocks",
            # YCB01 owns an explicit deterministic three-body layout even
            # when scene randomization is disabled.  Skipping this task here
            # leaves ``_ycb01_reset_post_poses`` empty, which silently turns
            # off crossing/contact evaluation on the normal preview path.
            YCB01_TASK_NAME,
            # YCB02 owns a deterministic complete seven-body layout even when
            # scene randomization is disabled.  Without this entry the generic
            # reset path returns before calling its sampler and leaves the
            # authored XML positions (including out-of-frame inactive bodies)
            # in place.
            ycb02.TASK_NAME,
            "t28_place_tableware",
            _HL015_TASK_NAME,
            "t03_cover_box",
            _FU006_TASK_NAME,

            YCB05_TASK_NAME,

            YCB10_TASK_NAME,
        }:
            return

        gen7_reset_xy = None
        if self.task_name == "eval_gen06_spray_shoe":
            from . import eval_gen06_spray_shoe_scene as gen7
            gen7_reset_xy, _ = gen7.sample_layout(self)
        c01_reset_pose = (
            self._c01_reset_pose()
            if self.task_name == "t08_hammer_nail"
            else None
        )
        c01_hammer_yaw = (
            c01_reset_pose[0] if c01_reset_pose is not None else None
        )
        c01_reset_xy = (
            c01_reset_pose[1] if c01_reset_pose is not None else None
        )
        c04_reset_layout = (
            self._c04_reset_layout()
            if self.task_name == "t50_water_plant"
            else None
        )
        c04_reset_xy = (
            c04_reset_layout[0] if c04_reset_layout is not None else None
        )
        c04_reset_yaw = (
            c04_reset_layout[1] if c04_reset_layout is not None else None
        )
        c05_reset_xy = (
            self._c05_reset_xy_positions()
            if self.task_name == "t14_move_and_click_mouse"
            else None
        )
        c06_reset_pose = (
            self._c06_reset_pose()
            if self.task_name == "t23_photograph_logo"
            else None
        )
        c06_reset_xy = (
            c06_reset_pose[0] if c06_reset_pose is not None else None
        )
        c06_reset_yaw = (
            c06_reset_pose[1] if c06_reset_pose is not None else None
        )
        c07_reset_layout = (
            self._c07_reset_layout()
            if self.task_name == "c07_pitcher_pour_cup"
            else None
        )
        c07_reset_xy = c07_reset_layout[0] if c07_reset_layout is not None else None
        c07_reset_yaw = c07_reset_layout[1] if c07_reset_layout is not None else None
        c08_reset_layout = (
            self._c08_reset_layout()
            if self.task_name == "c08_tongs_ice_cubes"
            else None
        )
        c08_reset_xy = c08_reset_layout[0] if c08_reset_layout is not None else None
        c08_reset_yaw = c08_reset_layout[1] if c08_reset_layout is not None else None
        a01_reset_xy = self._a01_reset_xy_positions()
        task_reset_xy = self._task_specific_reset_xy_positions()
        c_tool_grouped = self.task_name in _C_TOOL_GROUP_RANDOMIZED_TASKS
        c_tool_group_yaw = (
            float(self._random.uniform(*_C_TOOL_GROUP_YAW_BOUNDS_DEG))
            if c_tool_grouped
            and self.randomize
            and self.task_name != "c08_tongs_ice_cubes"
            else 0.0
        )
        c_tool_group_pivot = _C_TOOL_GROUP_PIVOTS.get(self.task_name)
        c_tool_group_yaw_rad = math.radians(c_tool_group_yaw)
        c_tool_group_rotation = np.asarray(
            [
                [math.cos(c_tool_group_yaw_rad), -math.sin(c_tool_group_yaw_rad)],
                [math.sin(c_tool_group_yaw_rad), math.cos(c_tool_group_yaw_rad)],
            ],
            dtype=np.float64,
        )

        reset_state_by_path = {
            path: (view, indices, pose, velocity)
            for path, view, indices, pose, velocity in self._task_reset_body_states
        }
        reset_articulation_by_path = {
            path: (view, indices, root_pose, root_velocity)
            for (
                path,
                view,
                indices,
                root_pose,
                root_velocity,
                _joint_pos,
                _joint_vel,
            ) in self._task_reset_articulation_states
        }

        table_state = None
        table_prim = self._find_rigid_body_prim("table")
        if table_prim is not None:
            table_state = reset_state_by_path.get(str(table_prim.GetPath()))
        applied_height = float(self.delta_h[0]) if table_state is not None else 0.0
        if table_state is None and abs(float(self.delta_h[0])) > 1e-12:
            self.delta_h[:] = 0.0
            self._add_task_state_warning(
                "Table rigid body is unavailable; table-height randomization was skipped"
            )
        elif table_state is not None:
            view, indices, root_pose, root_velocity = table_state
            randomized_pose = _randomized_physx_pose(
                root_pose.detach().cpu().numpy(),
                xy_offset=np.zeros(2, dtype=np.float64),
                z_offset=applied_height,
                yaw_degrees=0.0,
            )
            pose_tensor = self._torch.as_tensor(
                randomized_pose,
                dtype=root_pose.dtype,
                device=root_pose.device,
            )
            self._write_rigid_reset_state(
                str(table_prim.GetPath()),
                view,
                indices,
                pose_tensor,
                self._torch.zeros_like(root_velocity),
            )

        if self.task_name == YCB01_TASK_NAME:
            self._apply_ycb01_reset_layout(
                reset_state_by_path,
                reset_articulation_by_path,
                applied_height=applied_height,
            )
            return

        ycb10_reset_pose = None
        if self.task_name == YCB10_TASK_NAME:
            for attempt in range(128):
                ycb10_reset_pose = sample_ycb10_reset(
                    self._random, randomize=self.randomize,
                    table_top_z=_TABLE_TOP_Z + applied_height)
                if self._reset_box_clears_hands(ycb10_reset_pose, (.010, .061, .010)):
                    break
                if not self.randomize or attempt == 127:
                    raise RuntimeError("YCB10 cannot sample a marker clear of the reset hands")

        common_xy = (
            self._random.uniform(
                -_TASK_OBJECT_COMMON_XY_JITTER,
                _TASK_OBJECT_COMMON_XY_JITTER,
                size=2,
            )
            if self.randomize
            and self.task_name
            not in {
                "t08_hammer_nail",
                "t50_water_plant",
                "t14_move_and_click_mouse",
                "t23_photograph_logo",
                "c07_pitcher_pour_cup",
                "c08_tongs_ice_cubes",
                "t06_fit_device_cover",

                YCB05_TASK_NAME,
                ycb09.TASK_NAME,

                YCB10_TASK_NAME,
            }
            else np.zeros(2, dtype=np.float64)
        )
        if self.task_name == "t41_sort_nested_cups" and self.randomize:
            for attempt in range(128):
                common_xy = self._random.uniform([-.080, -.100], [.080, .100])
                stack_pose = np.asarray([-.25 + common_xy[0], common_xy[1],
                                         _TABLE_TOP_Z + applied_height + .048,
                                         1., 0., 0., 0.])
                if self._reset_box_clears_hands(stack_pose, (.040, .040, .048)):
                    break
                if attempt == 127:
                    raise RuntimeError("YCB04 cannot sample a nested stack clear of the reset hands")
        # The cups begin nested with millimetres of radial clearance.  Keep
        # their relative transform exact and randomize the stack as one body;
        # independent offsets can start PhysX with intersecting cup walls.
        ycb04_common_yaw = (
            float(self._random.uniform(-60.0, 60.0))
            if self.task_name == "t41_sort_nested_cups" and self.randomize
            else 0.0
        )
        if (
            self.task_name == "t11_line_up_blocks"
            and c_tool_group_pivot is not None
        ):
            # Keep the complete rotated group rigid when the set-square root
            # would leave the recording workspace.  Clamping only that one
            # body invalidates the block-vs-tool clearance proof; translate
            # the shared randomized offset instead, preserving every sampled
            # relative pose and all independent block yaws.
            common_xy = self._c12_workspace_safe_common_xy(
                c_tool_group_rotation,
                c_tool_group_pivot,
                common_xy,
            )
        c12_reset_xy = (
            self._c12_randomized_block_xy(
                c_tool_group_rotation,
                c_tool_group_pivot,
                common_xy,
            )
            if self.task_name == "t11_line_up_blocks"
            and self.randomize
            and c_tool_group_pivot is not None
            else None
        )
        if self.task_name == _FU006_TASK_NAME:
            # The drawer articulation root is world-fixed and its DOF is
            # restored through reduced-coordinate truth.  Only randomize the
            # free charger actor.
            logical_names = list(self._spec.target_objects)
        elif self.task_name == "t08_hammer_nail":
            # The nail is a prismatic child of the free wood articulation.
            # Move the articulation root so the nail stays seated in the wood.
            logical_names = ["hammer", "wood"]
        elif self.task_name == "t23_photograph_logo":
            # The logo is fixed to the table and already follows its height.
            logical_names = list(self._spec.target_objects)
        elif self.task_name == "c07_pitcher_pour_cup":
            logical_names = list(self._spec.target_objects) + [
                self._spec.receptacle,
                "c07_return_zone",
            ]
        elif self.task_name == ycb02.TASK_NAME:
            logical_names = [*ycb02.CUP_NAMES, *ycb02.BALL_NAMES]
        else:
            logical_names = list(self._spec.target_objects)
            if self._spec.receptacle != "table":
                logical_names.append(self._spec.receptacle)
        if c_tool_grouped or self.task_name == "t28_place_tableware":
            logical_names.extend(sorted(self._task_extra_pose_names()))
            logical_names = list(dict.fromkeys(logical_names))
        if self.task_name == "t36_scoop_marbles":
            logical_names.append("spoon")

        randomized_paths: set[str] = set()
        randomized_names: list[str] = []
        b03_peg_randomized_pose: np.ndarray | None = None
        hl015_cover_xy: np.ndarray | None = None
        for name in logical_names:
            prim = self._find_rigid_body_prim(name)
            if prim is None:
                continue
            path = str(prim.GetPath())
            if path in randomized_paths:
                continue
            state = self._reset_transform_state_for_path(
                path,
                reset_state_by_path,
                reset_articulation_by_path,
            )
            if state is None:
                continue
            state_kind, view, indices, root_pose, root_velocity = state
            relative_xy = (
                self._random.uniform(
                    -_TASK_OBJECT_RELATIVE_XY_JITTER,
                    _TASK_OBJECT_RELATIVE_XY_JITTER,
                    size=2,
                )
                if self.randomize
                and self.task_name
                not in {
                    "t08_hammer_nail",
                    "t50_water_plant",
                    "c07_pitcher_pour_cup",
                    "c08_tongs_ice_cubes",
                    ycb02.TASK_NAME,
                    "t41_sort_nested_cups",

                    YCB05_TASK_NAME,
                    ycb09.TASK_NAME,

                    YCB10_TASK_NAME,
                }
                else np.zeros(2, dtype=np.float64)
            )
            if c_tool_grouped and name not in self._spec.target_objects:
                relative_xy = np.zeros(2, dtype=np.float64)
            if self.task_name == "t09_insert_peg":
                yaw_degrees = self._b03_reset_yaw_degrees(name)
            elif self.task_name == "t03_cover_box":
                yaw_degrees = (
                    float(self._random.uniform(*_B05_YAW_BOUNDS_DEG))
                    if self.randomize
                    else 0.0
                )
            elif self.task_name == gen2_geometry.TASK_NAME:
                # GEN2's footprint/hand-clearance screen encloses only this
                # yaw range. The generic +/-35 degree reset can rotate the
                # large lid into the stationary wrist after that screen.
                yaw_degrees = (
                    float(self._random.uniform(*gen2_geometry.YAW_BOUNDS_DEG))
                    if self.randomize else 0.0
                )
            elif self.task_name == "t08_hammer_nail":
                yaw_degrees = (
                    float(c01_hammer_yaw)
                    if name == "hammer"
                    else 0.0
                )
            elif self.task_name == "t50_water_plant":
                yaw_degrees = (
                    float(c04_reset_yaw)
                    if c04_reset_yaw is not None
                    and name in self._spec.target_objects
                    else 0.0
                )
            elif self.task_name == "t23_photograph_logo":
                yaw_degrees = (
                    float(c06_reset_yaw)
                    if c06_reset_yaw is not None
                    else 0.0
                )
            elif self.task_name == YCB05_TASK_NAME:
                sampled_pose = self._ycb05_sampled_reset_poses[name]
                yaw_degrees = math.degrees(
                    2.0
                    * math.atan2(
                        float(sampled_pose[6]),
                        float(sampled_pose[3]),
                    )
                )
            elif self.task_name == YCB10_TASK_NAME:
                yaw_degrees = 0.0
            elif c07_reset_yaw is not None:
                yaw_degrees = float(c07_reset_yaw.get(name, 0.0))
            elif c08_reset_yaw is not None:
                yaw_degrees = float(c08_reset_yaw.get(name, 0.0))
            elif (
                self.task_name == "t11_line_up_blocks"
                and name in _C12_BLOCK_NAMES
            ):
                yaw_degrees = c_tool_group_yaw + (
                    float(self._random.uniform(*_C12_BLOCK_YAW_BOUNDS_DEG))
                    if self.randomize
                    else 0.0
                )
            elif (
                self.task_name == "t11_line_up_blocks"
                and name == "c12_set_square"
            ):
                # The block sampler screens against set-square segments
                # rotated by the group yaw.  Giving the tool another local
                # yaw after that screen invalidates the proof and can put a
                # randomized block through its hypotenuse.
                yaw_degrees = c_tool_group_yaw
            elif c_tool_grouped:
                local_yaw = (
                    float(self._random.uniform(-12.0, 12.0))
                    if self.randomize and name in self._spec.target_objects
                    else 0.0
                )
                yaw_degrees = c_tool_group_yaw + local_yaw
            elif self.task_name == "t26_place_fruit_in_bucket":
                yaw_degrees = (
                    0.0
                    if name == "bucket"
                    or name in _NO_RANDOMIZED_YAW_OBJECTS
                    or not self.randomize
                    else float(self._random.uniform(*_A01_YAW_BOUNDS_DEG))
                )
            elif self.task_name == "t25_place_cup_on_plate":
                yaw_degrees = (
                    0.0
                    if name in _NO_RANDOMIZED_YAW_OBJECTS or not self.randomize
                    else float(self._random.uniform(*_A02_YAW_BOUNDS_DEG))
                )
            elif self.task_name == "t24_place_ball_in_bowl":
                yaw_degrees = (
                    float(self._random.uniform(*_A03_YAW_BOUNDS_DEG))
                    if self.randomize
                    else 0.0
                )
            elif self.task_name == "t36_scoop_marbles":
                # Randomize the horizontal orientation independently of the
                # fixed, shallow resting tilt baked into the spoon pose.
                yaw_degrees = (
                    0.0
                    if name == "golf_ball" or not self.randomize
                    else float(self._random.uniform(-180.0, 180.0))
                )
            elif self.task_name == ycb02.TASK_NAME:
                yaw_degrees = (
                    float(self._random.uniform(-180.0, 180.0))
                    if self.randomize
                    else 0.0
                )
            elif self.task_name == "t41_sort_nested_cups":
                yaw_degrees = ycb04_common_yaw
            elif self.task_name == "t04_cover_pitcher":
                yaw_degrees = (
                    0.0
                    if name in _NO_RANDOMIZED_YAW_OBJECTS or not self.randomize
                    else float(self._random.uniform(*_B01_YAW_BOUNDS_DEG))
                )
            elif self.task_name == "t14_move_and_click_mouse":
                yaw_degrees = (
                    float(
                        self._random.uniform(
                            _C05_MOUSE_YAW_BOUNDS_DEG[0],
                            _C05_MOUSE_YAW_BOUNDS_DEG[1],
                        )
                    )
                    if self.randomize and name in self._spec.target_objects
                    else 0.0
                )
            elif self.task_name == "t06_fit_device_cover":
                yaw_degrees = (
                    float(self._random.uniform(-35.0, 35.0))
                    if self.randomize
                    and name in {"device_body", "device_cover"}
                    else 0.0
                )
            else:
                yaw_degrees = (
                    0.0
                    if name in _NO_RANDOMIZED_YAW_OBJECTS or not self.randomize
                    else float(
                        self._random.uniform(
                            _TASK_OBJECT_YAW_BOUNDS_DEG[0],
                            _TASK_OBJECT_YAW_BOUNDS_DEG[1],
                        )
                    )
                )
            xy_offset = common_xy + relative_xy
            if c_tool_grouped and c_tool_group_pivot is not None:
                root_pose_np = root_pose.detach().cpu().numpy()
                base_xy = np.asarray(root_pose_np[0, :2], dtype=np.float64)
                grouped_xy = (
                    c_tool_group_pivot
                    + c_tool_group_rotation @ (base_xy - c_tool_group_pivot)
                    + common_xy
                    + relative_xy
                )
                xy_offset = grouped_xy - base_xy
            root_pose_np = root_pose.detach().cpu().numpy()
            if self.task_name == "t08_hammer_nail" and name == "hammer":
                root_pose_np = root_pose_np.copy()
                root_pose_np[:, 3:7] = _C01_HAMMER_FLAT_RESET_QUAT_XYZW
            elif self.task_name == "t19_orient_cup_upright" and name == "a_cup":
                root_pose_np = root_pose_np.copy()
                root_pose_np[:, 3:7] = _A06_SIDE_REST_QUAT_XYZW
            elif self.task_name == "t36_scoop_marbles" and name == "spoon":
                root_pose_np = root_pose_np.copy()
                root_pose_np[:, 3:7] = _C02_SPOON_REST_QUAT_XYZW
            randomized_pose = _randomized_physx_pose(
                root_pose_np,
                xy_offset=xy_offset,
                z_offset=applied_height,
                yaw_degrees=yaw_degrees,
            )
            if ycb10_reset_pose is not None and name == "ycb10_marker":
                randomized_pose[:, :3] = ycb10_reset_pose[:3]
                randomized_pose[:, 3:7] = np.asarray(
                    [
                        ycb10_reset_pose[4],
                        ycb10_reset_pose[5],
                        ycb10_reset_pose[6],
                        ycb10_reset_pose[3],
                    ],
                    dtype=np.float64,
                )
            if self.task_name == _HL015_TASK_NAME and name == "hl015_cover":
                # The cover is intentionally independent of the C-tool group
                # translation/rotation.  Keep the sampled value around for
                # the final write below so no later task-specific override can
                # turn it into a boundary-clipped point mass.
                hl015_cover_xy = self._hl015_cover_reset_xy(
                    randomized_pose.shape[0]
                )
                randomized_pose[:, :2] = hl015_cover_xy
            else:
                randomized_pose[:, :2] = _constrain_task_xy_to_workspace(
                    self.task_name,
                    randomized_pose[:, :2],
                )
            if a01_reset_xy is not None and name in a01_reset_xy:
                randomized_pose[:, :2] = a01_reset_xy[name]
            if task_reset_xy is not None and name in task_reset_xy:
                randomized_pose[:, :2] = task_reset_xy[name]
            if self.task_name == YCB05_TASK_NAME:
                randomized_pose[:, 2] = self._ycb05_sampled_reset_poses[name][2]
            if (
                self.task_name == "t26_place_fruit_in_bucket"
                and name in _A01_SUPPORT_LOCAL_MIN_Z
            ):
                randomized_pose[:, 2] = (
                    _TABLE_TOP_Z
                    - _A01_SUPPORT_LOCAL_MIN_Z[name]
                    + applied_height
                )
            if (
                self.task_name == "t25_place_cup_on_plate"
                and name in _A02_SUPPORT_LOCAL_MIN_Z
            ):
                randomized_pose[:, 2] = (
                    _TABLE_TOP_Z
                    - _A02_SUPPORT_LOCAL_MIN_Z[name]
                    + applied_height
                )
            if (
                self.task_name == "t24_place_ball_in_bowl"
                and name in _A03_SUPPORT_LOCAL_MIN_Z
            ):
                randomized_pose[:, 2] = (
                    _TABLE_TOP_Z
                    - _A03_SUPPORT_LOCAL_MIN_Z[name]
                    + applied_height
                )
            if self.task_name == ycb02.TASK_NAME:
                support_local_min_z = {
                    **ycb02.CUP_SUPPORT_LOCAL_MIN_Z_M,
                    **ycb02.BALL_SUPPORT_LOCAL_MIN_Z_M,
                }.get(name)
                if support_local_min_z is not None:
                    randomized_pose[:, 2] = (
                        _TABLE_TOP_Z
                        - support_local_min_z
                        + applied_height
                    )

            if self.task_name == ycb09.TASK_NAME:
                support_local_min_z = {
                    ycb09.GLASS_NAME: ycb09.GLASS_LOCAL_MIN_Z_M,
                    ycb09.PLATE_NAME: ycb09.PLATE_LOCAL_MIN_Z_M,
                }.get(name)
                if support_local_min_z is not None:
                    randomized_pose[:, 2] = (
                        _TABLE_TOP_Z - support_local_min_z + applied_height
                    )
            if self.task_name == "t19_orient_cup_upright" and name == "a_cup":
                randomized_pose[:, 2] = (
                    _TABLE_TOP_Z
                    - _A06_SIDE_REST_SUPPORT_LOCAL_MIN_Z
                    + applied_height
                )
            if (
                self.task_name == "t04_cover_pitcher"
                and name in _B01_SUPPORT_LOCAL_MIN_Z
            ):
                randomized_pose[:, 2] = (
                    _TABLE_TOP_Z
                    - _B01_SUPPORT_LOCAL_MIN_Z[name]
                    + applied_height
                )
            if (
                self.task_name == "t03_cover_box"
                and name in _B05_SUPPORT_LOCAL_MIN_Z
            ):
                # The shared YCB MJCF was authored against a 0.92 m tabletop,
                # while this Isaac task uses 0.89 m.  Place both flat supports
                # directly on the actual table instead of letting them fall
                # about 3 cm during the recording-origin settle window.
                randomized_pose[:, 2] = (
                    _TABLE_TOP_Z
                    - _B05_SUPPORT_LOCAL_MIN_Z[name]
                    + _B05_RESET_SUPPORT_CLEARANCE
                    + applied_height
                )
            if (
                self.task_name == "t44_stack_blocks"
                and name in _B04_SUPPORT_LOCAL_MIN_Z
            ):
                randomized_pose[:, 2] = (
                    _TABLE_TOP_Z
                    - _B04_SUPPORT_LOCAL_MIN_Z[name]
                    + applied_height
                )
            if (
                self.task_name == gen5.TASK_NAME
                and name in _GEN5_SUPPORT_LOCAL_MIN_Z
            ):
                # GEN5 uses the same measured local collision bottoms as the
                # shared stack predicates. Write each carton directly onto
                # the actual table plane so no reset frame starts embedded.
                randomized_pose[:, 2] = (
                    _TABLE_TOP_Z
                    - _GEN5_SUPPORT_LOCAL_MIN_Z[name]
                    + applied_height
                )
            if (
                self.task_name == gen2_geometry.TASK_NAME
                and name in gen2_geometry.SUPPORT_MIN_Z
            ):
                randomized_pose[:, 2] = (
                    _TABLE_TOP_Z
                    - gen2_geometry.SUPPORT_MIN_Z[name]
                    + gen2_geometry.CONTACT_OFFSET
                    + applied_height
                )
            if c01_reset_xy is not None:
                randomized_pose[:, :2] = c01_reset_xy[name]
                support_local_min_z = {
                    "hammer": _C01_HAMMER_SUPPORT_LOCAL_MIN_Z,
                    "wood": _C01_WOOD_SUPPORT_LOCAL_MIN_Z,
                }.get(name)
                if support_local_min_z is not None:
                    randomized_pose[:, 2] = (
                        _TABLE_TOP_Z
                        - support_local_min_z
                        + (
                            _C02_RESET_SUPPORT_CLEARANCE
                            if name == "spoon"
                            else 0.0
                        )
                        + applied_height
                    )
            if self.task_name == "t36_scoop_marbles":
                support_local_min_z = _C02_SUPPORT_LOCAL_MIN_Z.get(name)
                if support_local_min_z is not None:
                    # The shared YCB scene is authored for a 0.92 m tabletop,
                    # while the ROKAE collection scene is 0.89 m.  Writing the
                    # collision bottom directly to the real support plane
                    # removes the old ~30 mm reset fall without any velocity
                    # clamp or post-step pose correction.
                    randomized_pose[:, 2] = (
                        _TABLE_TOP_Z
                        - support_local_min_z
                        + (
                            _C02_RESET_SUPPORT_CLEARANCE
                            if name == "spoon"
                            else 0.0
                        )
                        + applied_height
                    )
            if c04_reset_xy is not None:
                if name in self._spec.target_objects and "spray" in c04_reset_xy:
                    randomized_pose[:, :2] = c04_reset_xy["spray"]
                    randomized_pose[:, 2] = (
                        _TABLE_TOP_Z
                        - _C04_SPRAY_SUPPORT_LOCAL_MIN_Z
                        + applied_height
                    )
                elif name == self._spec.receptacle and name in c04_reset_xy:
                    randomized_pose[:, :2] = c04_reset_xy[name]
            if c05_reset_xy is not None:
                reset_xy = (
                    c05_reset_xy[0]
                    if name in self._spec.target_objects
                    else c05_reset_xy[1]
                )
                randomized_pose[:, :2] = reset_xy
            if c06_reset_xy is not None and name in self._spec.target_objects:
                randomized_pose[:, :2] = c06_reset_xy
            if self.task_name == _YCB07_TASK_NAME and name == _YCB07_TIMER_NAME:
                randomized_pose[:, :2] = self._ycb07_reset_xy
                randomized_pose[:, 2] = (
                    _TABLE_TOP_Z
                    - _YCB07_SUPPORT_LOCAL_MIN_Z
                    + _YCB07_RESET_SUPPORT_CLEARANCE
                    + applied_height
                )
            if c07_reset_xy is not None and name in c07_reset_xy:
                randomized_pose[:, :2] = c07_reset_xy[name]
                if name == "c07_pitcher":
                    randomized_pose[:, 2] = (
                        _TABLE_TOP_Z
                        - _C07_PITCHER_SUPPORT_LOCAL_MIN_Z
                        + applied_height
                    )
                elif name == "c07_cup":
                    randomized_pose[:, 2] = (
                        _TABLE_TOP_Z
                        - _C07_CUP_SUPPORT_LOCAL_MIN_Z
                        + applied_height
                    )
                elif name in _C07_PARTICLE_NAMES:
                    randomized_pose[:, 2] = (
                        _C07_PARTICLE_SUPPORT_ROOT_Z + applied_height
                    )
            if c08_reset_xy is not None and name in c08_reset_xy:
                randomized_pose[:, :2] = c08_reset_xy[name]
            if (
                self.task_name in {"t02_connect_charger_and_cable", _HL015_TASK_NAME}
                and name in _C10_SUPPORT_LOCAL_MIN_Z
            ):
                randomized_pose[:, 2] = (
                    _TABLE_TOP_Z
                    - _C10_SUPPORT_LOCAL_MIN_Z[name]
                    + applied_height
                )
            if self.task_name == _FU006_TASK_NAME and name == "fu006_charger":
                randomized_pose[:, 2] = (
                    _TABLE_TOP_Z
                    - _FU006_CHARGER_SUPPORT_LOCAL_MIN_Z
                    + applied_height
                )
            if c12_reset_xy is not None and name in c12_reset_xy:
                randomized_pose[:, :2] = c12_reset_xy[name]
            if (
                self.task_name == "t11_line_up_blocks"
                and name in _C12_SUPPORT_LOCAL_MIN_Z
            ):
                randomized_pose[:, 2] = (
                    _TABLE_TOP_Z
                    - _C12_SUPPORT_LOCAL_MIN_Z[name]
                    + applied_height
                )
            if (
                self.task_name == "t09_insert_peg"
                and (name in self._spec.target_objects or name == self._spec.receptacle)
                and self.randomize
            ):
                support_name = (
                    "industreal_round_peg_8mm"
                    if name in self._spec.target_objects
                    else "industreal_tray_insert_round_peg_8mm"
                )
                randomized_pose[:, 2] = (
                    _B03_TABLE_TOP_Z
                    - _B03_SUPPORT_LOCAL_MIN_Z[support_name]
                    + applied_height
                )
                randomized_pose = self._b03_reset_pose_for_name(name, randomized_pose)
            if (
                self.task_name == "t09_insert_peg"
                and name in self._spec.target_objects
                and b03_peg_randomized_pose is None
            ):
                randomized_pose = self._b03_sample_clear_peg_reset_pose(
                    randomized_pose,
                )
                b03_peg_randomized_pose = randomized_pose.copy()
            if (
                self.task_name == "t09_insert_peg"
                and name == self._spec.receptacle
                and b03_peg_randomized_pose is not None
            ):
                randomized_pose = self._b03_sample_clear_socket_reset_pose(
                    b03_peg_randomized_pose,
                    randomized_pose,
                )
            if self.task_name == _HL015_TASK_NAME and name == "hl015_cover":
                # Keep the independently sampled lane authoritative even if a
                # future task-specific XY override is added above this final
                # reset write.  Reusing the exact sample avoids a second RNG
                # draw and preserves seeded replay.
                if hl015_cover_xy is None:
                    raise RuntimeError("HL015 cover reset sample is missing")
                randomized_pose[:, :2] = hl015_cover_xy
            if gen7_reset_xy is not None:
                from . import eval_gen06_spray_shoe_scene as gen7
                key = "spray" if name in self._spec.target_objects else name
                manifest = gen7.asset_manifest()
                bounds = manifest["bottle_bounds" if key == "spray" else "shoe_bounds"]
                randomized_pose[:, :2] = gen7_reset_xy[key]
                randomized_pose[:, 2] = _TABLE_TOP_Z - float(bounds[0][2]) + applied_height
                half_yaw = math.radians(self._gen7_reset_yaws[key]) / 2.0
                randomized_pose[:, 3:7] = (0.0, 0.0, math.sin(half_yaw), math.cos(half_yaw))
            randomized_pose = self._customize_task_reset_pose(
                name,
                randomized_pose,
                applied_height=applied_height,
            )
            pose_tensor = self._torch.as_tensor(
                randomized_pose,
                dtype=root_pose.dtype,
                device=root_pose.device,
            )
            if state_kind == "articulation":
                view.set_root_transforms(pose_tensor, indices)
                zero_root_velocity = self._torch.zeros_like(root_velocity)
                view.set_root_velocities(zero_root_velocity, indices)
                self._record_authored_task_reset_write(
                    path,
                    transform_xyzw=pose_tensor,
                    velocity=zero_root_velocity,
                )
            else:
                self._write_rigid_reset_state(
                    path,
                    view,
                    indices,
                    pose_tensor,
                    self._torch.zeros_like(root_velocity),
                )
            randomized_paths.add(path)
            randomized_names.append(name)

        if self.task_name == ycb02.TASK_NAME:
            required_names = set((*ycb02.CUP_NAMES, *ycb02.BALL_NAMES))
            randomized_name_set = set(randomized_names)
            missing_names = sorted(required_names - randomized_name_set)
            if missing_names:
                raise RuntimeError(
                    "YCB02 reset did not write every randomized body: "
                    f"missing={missing_names}, "
                    f"wrote={sorted(randomized_name_set)}"
                )

        print(
            "[HandsOn/IsaacLab] Randomized ABC object poses: "
            f"table_delta_h={applied_height:.4f}m, "
                f"common_xy=({common_xy[0]:+.4f}, {common_xy[1]:+.4f})m, "
                f"c01_hammer_yaw={c01_hammer_yaw if c01_hammer_yaw is not None else 'n/a'}, "
                f"c04_spray_xy={c04_reset_xy['spray'].round(4).tolist() if c04_reset_xy is not None else 'n/a'}, "
                f"c04_plant_xy={c04_reset_xy['plant'].round(4).tolist() if c04_reset_xy is not None else 'n/a'}, "
                f"c04_spray_yaw={c04_reset_yaw if c04_reset_yaw is not None else 'n/a'}, "
                f"c06_camera_xy={c06_reset_xy.round(4).tolist() if c06_reset_xy is not None else 'n/a'}, "
                f"c06_camera_yaw={c06_reset_yaw if c06_reset_yaw is not None else 'n/a'}, "
                f"c07_pitcher_xy={c07_reset_xy['c07_pitcher'].round(4).tolist() if c07_reset_xy is not None else 'n/a'}, "
                f"c07_cup_xy={c07_reset_xy['c07_cup'].round(4).tolist() if c07_reset_xy is not None else 'n/a'}, "
                f"hl015_cover_xy={hl015_cover_xy[0].round(4).tolist() if hl015_cover_xy is not None else 'n/a'}, "
                f"c_tool_group_yaw={c_tool_group_yaw if c_tool_grouped else 'n/a'}, "
                f"objects={','.join(randomized_names) or 'none'}",
                flush=True,
            )

    @staticmethod
    def _free_body_names(task_mjcf: Path) -> tuple[str, ...]:
        root = ET.parse(task_mjcf).getroot()
        names: list[str] = []
        for body in root.iter("body"):
            has_free_joint = any(
                child.tag == "freejoint"
                or (child.tag == "joint" and child.attrib.get("type") == "free")
                for child in body
            )
            name = body.attrib.get("name")
            if has_free_joint and name:
                names.append(name)
        return tuple(names)

    def _task_state_candidate_names(self, task_mjcf: Path) -> set[str]:
        names = set(self._spec.target_objects) | {
            self._spec.receptacle,
            "wood",
            "table",
        }
        names.update(self._task_extra_pose_names())
        names.update(self._free_body_names(task_mjcf))
        if self.task_name == ycb02.TASK_NAME:
            # The YCB02 contract is stricter than the generic ``freejoint``
            # discovery path: every cup and ball must have its own cached
            # rigid-body view so the complete random layout can be written at
            # reset.  Keep this explicit even if a future MJCF preprocessor
            # stops expanding one of the included object files.
            names.update((*ycb02.CUP_NAMES, *ycb02.BALL_NAMES))
        return names

    def _configure_ground_truth_contact_reports(self, task_mjcf: Path) -> None:
        """Enable task-body reports before the first simulation reset."""

        if self._stage is None:
            raise RuntimeError(
                "PhysX contact recording requires the constructed USD stage"
            )
        prim_paths = []
        for name in sorted(self._task_state_candidate_names(task_mjcf)):
            prim = self._find_rigid_body_prim(name)
            if prim is not None:
                prim_path = str(prim.GetPath())
                if self._task_detailed_contact_sensor_is_enabled(prim_path):
                    prim_paths.append(prim_path)
        self._physx_contact_sensor_paths_preconfigured = tuple(
            dict.fromkeys(prim_paths)
        )
        if self.task_name in _PHYSX_TENSOR_ONLY_CONTACT_REPORT_TASKS:
            # Applying PhysxContactReportAPI to KA005-2's fixed articulation
            # root before the first reset triggers a GPU narrowphase fault in
            # Isaac Sim 5.1.  Keep the exact sensor paths so the recording
            # trace creates its public RigidContactView fallback after reset;
            # no contact validity or penetration gate is relaxed.
            self._physx_contact_report_paths_preconfigured = ()
        else:
            self._physx_contact_report_paths_preconfigured = (
                configure_physx_contact_reports_for_recording(
                    self._stage,
                    prim_paths,
                )
            )

    def _task_detailed_contact_sensor_is_enabled(self, path: str) -> bool:
        """Return whether recording should attach a detailed contact sensor."""

        del path
        return True

    def _task_articulation_root_is_writable(self, path: str) -> bool:
        """Return whether reset/replay may write an articulation root.

        Reduced-coordinate joints can remain writable even when an
        articulation is fixed directly to the world.  Task subclasses may
        therefore protect only the root tensor while retaining the DOF state
        in the normal reset and recording contracts.
        """

        if self.task_name == _FU006_TASK_NAME and str(path).startswith(
            _FU006_DRAWER_ROOT
        ):
            return False
        return True

    def _task_articulation_dofs_are_writable(self, path: str) -> bool:
        """Return whether reset/replay may write articulation DOF tensors."""

        return True

    def _task_articulation_root_velocity_is_writable(self, path: str) -> bool:
        """Return whether a velocity-only boundary may write this root."""

        return self._task_articulation_root_is_writable(path)

    def _task_articulation_dof_velocity_is_writable(self, path: str) -> bool:
        """Return whether a velocity-only boundary may write these DOFs."""

        return self._task_articulation_dofs_are_writable(path)

    def _task_reset_write_is_required(
        self,
        path: str,
        *,
        state_kind: Literal["articulation", "rigid_body"],
    ) -> bool:
        """Return whether a failed cached-state write must abort reset.

        Shared ABC tasks historically keep running after a task-object write
        failure and surface the problem through ``_isaac_warnings``.  Custom
        task families may override this hook for dynamic state that is required
        for a truthful reset while preserving that compatibility by default.
        """

        del path, state_kind
        return False

    def _validate_ycb02_cached_scene_state(self) -> None:
        """Fail closed if the complete YCB02 reset cache is not available.

        YCB02 deliberately resets all three cups and all four candidates. A
        generic MJCF free-body discovery miss would
        otherwise leave one actor at its authored pose while reporting a
        successful reset.  Validate both the name-to-view map and the backing
        reset state (rigid-body or reduced-coordinate articulation) before any
        sampler can publish a layout.
        """

        if self.task_name != ycb02.TASK_NAME:
            return
        required = (*ycb02.CUP_NAMES, *ycb02.BALL_NAMES)
        required_set = set(required)
        missing_views = sorted(required_set - set(self._task_body_views))

        reset_paths = {
            str(entry[0]) for entry in self._task_reset_body_states
        }
        reset_paths.update(
            str(entry[0]) for entry in self._task_reset_articulation_states
        )
        missing_prims: list[str] = []
        missing_writes: list[str] = []
        resolved_paths: dict[str, str] = {}
        articulation_roots = tuple(
            str(entry[0]) for entry in self._task_reset_articulation_states
        )
        for name in required:
            prim = self._find_rigid_body_prim(name)
            if prim is None:
                missing_prims.append(name)
                continue
            path = str(prim.GetPath())
            resolved_paths[name] = path
            if path not in reset_paths and not any(
                path == root or path.startswith(f"{root}/")
                for root in articulation_roots
            ):
                missing_writes.append(name)

        duplicate_paths = sorted(
            path
            for path in set(resolved_paths.values())
            if list(resolved_paths.values()).count(path) > 1
        )
        if missing_views or missing_prims or missing_writes or duplicate_paths:
            raise RuntimeError(
                "YCB02 reset state is incomplete: "
                f"missing_views={missing_views}, "
                f"missing_prims={sorted(missing_prims)}, "
                f"missing_writes={sorted(missing_writes)}, "
                f"duplicate_paths={duplicate_paths}"
            )

    def _capture_task_scene_state(self, task_mjcf: Path) -> None:
        """Cache live PhysX state so reset does not need to reload the stage."""
        self._task_physics_sim_view = None
        self._task_kinematic_body_paths.clear()
        self._task_articulation_views.clear()
        self._task_reset_body_states.clear()
        self._task_reset_articulation_states.clear()
        self._task_body_views.clear()
        self._task_dof_views.clear()
        if self._stage is None or not self._robots:
            return
        if self._physics_backend == "newton":
            self._capture_newton_task_scene_state(task_mjcf)
            return
        try:
            physics_sim_view = _create_torch_task_physics_sim_view()
        except Exception as exc:
            raise RuntimeError(
                "Could not create the Torch-backed PhysX task-state view"
            ) from exc
        self._task_physics_sim_view = physics_sim_view

        from pxr import Usd, UsdPhysics

        task_root = self._stage.GetPrimAtPath(_TASK_ROOT)
        for prim in Usd.PrimRange(task_root):
            if not prim.IsActive() or not prim.HasAPI(UsdPhysics.ArticulationRootAPI):
                continue
            path = str(prim.GetPath())
            # The MJCF importer marks its structural worldBody container as an
            # articulation root even though PhysX does not create an
            # articulation for it.  Querying it only produces tensor errors;
            # the real task articulations are its descendants and are cached
            # independently below.
            if path in {f"{_TASK_ROOT}/worldBody", f"{_TASK_ROOT}/Geometry"}:
                continue
            imported_robot_roots = tuple(
                root
                for side in ("right", "left")
                for root in (
                    f"{_TASK_ROOT}/base_{side}",
                    f"{_TASK_ROOT}/Geometry/base_{side}",
                )
            )
            if path.startswith(imported_robot_roots):
                continue
            try:
                view = physics_sim_view.create_articulation_view(path)
                if int(view.count) < 1:
                    continue
                indices = self._torch.arange(
                    int(view.count),
                    dtype=self._torch.long,
                    device=self._isaac_device,
                )
                joint_pos = _torch_view(view.get_dof_positions()).clone()
                # The MJCF importer also tags free rigid bodies (including the
                # B03 peg and socket) as articulation roots with zero DOFs.
                # They are the same PhysX actors exposed by the rigid-body
                # views built below, so keeping both would restore each root
                # twice.  Only cache genuine reduced-coordinate articulations
                # here; zero-DOF free bodies use the rigid-body path.
                if int(joint_pos.shape[-1]) == 0:
                    continue
                self._task_reset_articulation_states.append(
                    (
                        path,
                        view,
                        indices,
                        _torch_view(view.get_root_transforms()).clone(),
                        _torch_view(view.get_root_velocities()).clone(),
                        joint_pos,
                        _torch_view(view.get_dof_velocities()).clone(),
                    )
                )
                metatype = view.get_metatype(0)
                for dof_name, dof_index in metatype.dof_indices.items():
                    index = int(dof_index)
                    self._task_dof_views.setdefault(
                        str(dof_name),
                        (view, index, float(joint_pos[0, index].item())),
                    )
            except Exception as exc:
                self._add_task_state_warning(f"Could not snapshot articulation {path}: {exc}")

        articulation_root_paths = {
            path for path, *_rest in self._task_reset_articulation_states
        }
        articulation_view_by_path = {
            path: (view, indices)
            for path, view, indices, *_rest in self._task_reset_articulation_states
        }
        logical_names = set(self._spec.target_objects) | {
            self._spec.receptacle,
            "wood",
            "table",
        }
        logical_names.update(self._task_extra_pose_names())
        candidate_names = self._task_state_candidate_names(task_mjcf)
        reset_view_by_path: dict[str, Any] = {}
        for name in sorted(candidate_names):
            prim = self._find_rigid_body_prim(name)
            if prim is None:
                continue
            path = str(prim.GetPath())
            matching_articulation_paths = [
                root_path
                for root_path in articulation_root_paths
                if path == root_path or path.startswith(f"{root_path}/")
            ]
            if matching_articulation_paths:
                root_path = max(
                    matching_articulation_paths,
                    key=len,
                )
                self._task_articulation_views[name] = (
                    articulation_view_by_path[root_path]
                )
            view = reset_view_by_path.get(path)
            if view is None:
                try:
                    view = physics_sim_view.create_rigid_body_view(path)
                    if int(view.count) < 1:
                        continue
                    rigid_api = UsdPhysics.RigidBodyAPI(prim)
                    kinematic_attr = rigid_api.GetKinematicEnabledAttr()
                    if kinematic_attr.IsValid() and bool(kinematic_attr.Get()):
                        self._task_kinematic_body_paths.add(path)
                    indices = self._torch.arange(
                        int(view.count),
                        dtype=self._torch.long,
                        device=self._isaac_device,
                    )
                    reset_view_by_path[path] = view
                    # Restore an articulation root and all of its moving links
                    # only through the reduced-coordinate view above.  A root
                    # registered here would be written twice (collapsing some
                    # free-root hinges), while PhysX rejects rigid setters for
                    # non-root links outright.
                    if _is_independent_task_rigid_body_path(
                        path,
                        articulation_root_paths,
                    ):
                        self._task_reset_body_states.append(
                            (
                                path,
                                view,
                                indices,
                                _torch_view(view.get_transforms()).clone(),
                                _torch_view(view.get_velocities()).clone(),
                            )
                        )
                except Exception as exc:
                    self._add_task_state_warning(f"Could not snapshot rigid body {path}: {exc}")
                    continue
            self._task_body_views[name] = view

        # Bind logical aliases that resolve to an already snapshotted body.
        for name in sorted(logical_names):
            if name in self._task_body_views:
                continue
            prim = self._find_rigid_body_prim(name)
            if prim is not None:
                view = reset_view_by_path.get(str(prim.GetPath()))
                if view is not None:
                    self._task_body_views[name] = view

        self._validate_ycb02_cached_scene_state()

        protected_articulation_roots = sum(
            not self._task_articulation_root_is_writable(path)
            for path, *_rest in self._task_reset_articulation_states
        )
        protected_articulation_dofs = sum(
            not self._task_articulation_dofs_are_writable(path)
            for path, *_rest in self._task_reset_articulation_states
        )
        print(
            "[HandsOn/IsaacLab] Cached task reset state: "
            f"{len(self._task_reset_body_states)} rigid bodies, "
            f"{len(self._task_reset_articulation_states)} articulations, "
            f"{protected_articulation_roots} fixed articulation roots protected, "
            f"{protected_articulation_dofs} articulation DOF sets protected",
            flush=True,
        )

    def _capture_newton_task_scene_state(self, task_mjcf: Path) -> None:
        """Cache A01 task roots through Newton's native selection API."""

        logical_names = set(self._spec.target_objects) | {
            self._spec.receptacle,
            "wood",
            "table",
        }
        logical_names.update(self._task_extra_pose_names())
        candidate_names = self._task_state_candidate_names(task_mjcf)
        reset_view_by_path: dict[str, Any] = {}
        for name in sorted(candidate_names):
            prim = self._find_rigid_body_prim(name)
            if prim is None:
                continue
            path = str(prim.GetPath())
            view = reset_view_by_path.get(path)
            if view is None:
                try:
                    view = _NewtonTaskBodyView(path)
                    indices = self._torch.arange(
                        int(view.count),
                        dtype=self._torch.long,
                        device=self._isaac_device,
                    )
                    pose = view.get_transforms().clone()
                    velocity = view.get_velocities().clone()
                    self._task_reset_body_states.append(
                        (path, view, indices, pose, velocity)
                    )
                    reset_view_by_path[path] = view
                except Exception as exc:
                    self._add_task_state_warning(
                        f"Could not snapshot Newton rigid body {path}: {exc}"
                    )
                    continue
            self._task_body_views[name] = view

        for name in sorted(logical_names):
            if name in self._task_body_views:
                continue
            prim = self._find_rigid_body_prim(name)
            if prim is not None:
                view = reset_view_by_path.get(str(prim.GetPath()))
                if view is not None:
                    self._task_body_views[name] = view

        self._validate_ycb02_cached_scene_state()

        print(
            "[HandsOn/IsaacLab] Cached Newton task reset state: "
            f"{len(self._task_reset_body_states)} rigid roots",
            flush=True,
        )

    def _restore_task_scene_state(self) -> None:
        for (
            path,
            view,
            indices,
            root_pose,
            root_velocity,
            joint_pos,
            joint_vel,
        ) in self._task_reset_articulation_states:
            try:
                root_is_writable = self._task_articulation_root_is_writable(path)
                dofs_are_writable = self._task_articulation_dofs_are_writable(path)
                if root_is_writable:
                    view.set_root_transforms(root_pose, indices)
                    view.set_root_velocities(root_velocity, indices)
                if dofs_are_writable and joint_pos.shape[-1] > 0:
                    view.set_dof_positions(joint_pos, indices)
                    view.set_dof_velocities(joint_vel, indices)
                if root_is_writable or dofs_are_writable:
                    self._record_authored_task_reset_write(
                        path,
                        transform_xyzw=root_pose if root_is_writable else None,
                        velocity=root_velocity if root_is_writable else None,
                        dof_position=joint_pos if dofs_are_writable else None,
                        dof_velocity=joint_vel if dofs_are_writable else None,
                    )
            except Exception as exc:
                if self._task_reset_write_is_required(
                    path,
                    state_kind="articulation",
                ):
                    raise RuntimeError(
                        "Required task articulation reset write failed for "
                        f"{path}: {exc}"
                    ) from exc
                self._add_task_state_warning(
                    f"Could not restore articulation {path}: {exc}"
                )
        for path, view, indices, pose, velocity in self._task_reset_body_states:
            try:
                self._write_rigid_reset_state(
                    path,
                    view,
                    indices,
                    pose,
                    velocity,
                )
            except Exception as exc:
                if self._task_reset_write_is_required(
                    path,
                    state_kind="rigid_body",
                ):
                    raise RuntimeError(
                        "Required task rigid-body reset write failed for "
                        f"{path}: {exc}"
                    ) from exc
                self._add_task_state_warning(
                    f"Could not restore rigid body {path}: {exc}"
                )

    def _add_task_state_warning(self, detail: str) -> None:
        message = f"Task reset state warning: {detail}"
        if message not in self._isaac_warnings:
            self._isaac_warnings.append(message)
            print(f"[HandsOn/IsaacLab] {message}", flush=True)

    def _find_rigid_body_prim(self, name: str):
        if self._stage is None:
            return None
        from pxr import UsdPhysics

        prim = self._find_prim(name)
        while prim is not None and prim.IsValid() and str(prim.GetPath()).startswith(_TASK_ROOT):
            if prim.HasAPI(UsdPhysics.RigidBodyAPI):
                return prim
            prim = prim.GetParent()
        return None

    def _init_recording_cameras(self) -> None:
        if not self.image_obs or self._deferred_camera_render:
            return
        try:
            import isaaclab.sim as sim_utils
            from isaaclab.sensors import Camera, CameraCfg

            recording_renderer_cfg_type = None
            if self._physics_backend == "newton" and not getattr(self, "_evaluation_rtx_cameras", False):
                # CameraCfg defaults to Isaac RTX.  On the Newton backend that
                # renderer can create a valid render product whose RGB buffer
                # remains black because it follows the PhysX/Fabric scene.
                # Bind sensors to Newton's renderer so images and physics read
                # the same GPU-resident world state.
                from isaaclab_newton.renderers import NewtonWarpRendererCfg

                recording_renderer_cfg_type = NewtonWarpRendererCfg

            legacy_wrist_cameras = _bool_env(
                "HANDSON_ISAACLAB_LEGACY_WRIST_CAMERAS",
                False,
            )
            self._legacy_wrist_cameras = legacy_wrist_cameras
            head_horizontal_aperture = (
                _RECORDING_CAMERA_VERTICAL_APERTURE
                * float(self._render_width)
                / float(self._render_height)
            )
            wrist_width, wrist_height = self._wrist_recording_camera_output_size
            wrist_horizontal_aperture = (
                _RECORDING_CAMERA_VERTICAL_APERTURE
                * float(wrist_width)
                / float(wrist_height)
            )
            camera_sizes = {
                "head_camera": (self._render_width, self._render_height),
                "wrist_left_camera": self._wrist_recording_camera_output_size,
                "wrist_right_camera": self._wrist_recording_camera_output_size,
            }
            camera_lenses = {
                "head_camera": {
                    "focal_length": _focal_length_for_vertical_fov(
                        _HEAD_RECORDING_CAMERA_FOVY
                    ),
                    "focus_distance": 1.2,
                    "horizontal_aperture": head_horizontal_aperture,
                    "vertical_aperture": _RECORDING_CAMERA_VERTICAL_APERTURE,
                    "clipping_range": (0.0008, 10.0),
                },
                "wrist_left_camera": {
                    "focal_length": (
                        _focal_length_for_vertical_fov(60.0)
                        if legacy_wrist_cameras
                        else _focal_length_for_horizontal_fov(
                            _WRIST_RECORDING_CAMERA_HFOV_BY_SIDE["left"],
                            wrist_horizontal_aperture,
                        )
                    ),
                    "focus_distance": 0.55,
                    "horizontal_aperture": (
                        head_horizontal_aperture
                        if legacy_wrist_cameras
                        else wrist_horizontal_aperture
                    ),
                    "vertical_aperture": _RECORDING_CAMERA_VERTICAL_APERTURE,
                    "clipping_range": (
                        (0.0008, 5.0)
                        if legacy_wrist_cameras
                        else (WRIST_RECORDING_CAMERA_NEAR_M, 5.0)
                    ),
                },
                "wrist_right_camera": {
                    "focal_length": (
                        _focal_length_for_vertical_fov(60.0)
                        if legacy_wrist_cameras
                        else _focal_length_for_horizontal_fov(
                            _WRIST_RECORDING_CAMERA_HFOV_BY_SIDE["right"],
                            wrist_horizontal_aperture,
                        )
                    ),
                    "focus_distance": 0.55,
                    "horizontal_aperture": (
                        head_horizontal_aperture
                        if legacy_wrist_cameras
                        else wrist_horizontal_aperture
                    ),
                    "vertical_aperture": _RECORDING_CAMERA_VERTICAL_APERTURE,
                    "clipping_range": (
                        (0.0008, 5.0)
                        if legacy_wrist_cameras
                        else (WRIST_RECORDING_CAMERA_NEAR_M, 5.0)
                    ),
                },
            }
            recording_camera_names = (
                ("head_camera",)
                if self._live_main_camera_only
                else _RECORDING_CAMERA_NAMES
            )
            self._camera_aliases.clear()
            self._dynamic_cameras = set(recording_camera_names)
            legacy_wrist_source_desc = ""
            configured_camera_paths: list[str] = []

            camera_sources: dict[str, str | None] = {
                name: _RECORDING_CAMERA_PRIM_PATHS[name]
                for name in recording_camera_names
            }
            if legacy_wrist_cameras and not self._live_main_camera_only:
                right_wrist_prim = self._native_camera_prim_path(
                    "right",
                    ("wrist_fisheye_right", "handcam_rgb_right", "handcam_rgb"),
                )
                left_wrist_prim = self._native_camera_prim_path(
                    "left",
                    ("wrist_fisheye_left", "handcam_rgb_left"),
                )
                camera_sources = {
                    "head_camera": _RECORDING_CAMERA_PRIM_PATHS["head_camera"],
                    "wrist_right_camera": right_wrist_prim,
                    "wrist_left_camera": (
                        left_wrist_prim
                        if self._spec.bimanual
                        else right_wrist_prim
                    ),
                }
                self._dynamic_cameras = {"head_camera"}
                if not self._spec.bimanual:
                    self._camera_aliases["wrist_left_camera"] = "wrist_right_camera"
                right_source = "native" if right_wrist_prim is not None else "dynamic"
                if "wrist_left_camera" in self._camera_aliases:
                    left_source = "alias:right"
                else:
                    left_source = "native" if left_wrist_prim is not None else "dynamic"
                legacy_wrist_source_desc = (
                    f", wrist_sources=left:{left_source},right:{right_source}"
                )

            for name in recording_camera_names:
                if name in self._camera_aliases:
                    continue
                camera_width, camera_height = camera_sizes[name]
                prim_path = camera_sources[name]
                spawn = sim_utils.PinholeCameraCfg(**camera_lenses[name])
                if legacy_wrist_cameras and name.startswith("wrist_"):
                    if prim_path is None:
                        prim_path = _RECORDING_CAMERA_PRIM_PATHS[name]
                        self._dynamic_cameras.add(name)
                    else:
                        spawn = None
                camera_cfg_kwargs = {
                    "prim_path": prim_path,
                    "update_period": 0.0,
                    "height": camera_height,
                    "width": camera_width,
                    "data_types": ["rgb"],
                    "update_latest_camera_pose": True,
                    "spawn": spawn,
                }
                if recording_renderer_cfg_type is not None:
                    camera_cfg_kwargs["renderer_cfg"] = (
                        recording_renderer_cfg_type()
                    )
                cfg = CameraCfg(
                    **camera_cfg_kwargs,
                )
                self._cameras[name] = Camera(cfg)
                if prim_path is not None:
                    configured_camera_paths.append(str(prim_path))

            if self._studio_visuals and configured_camera_paths:
                from pxr import UsdGeom

                sim_utils.update_stage()
                exposure_ev = isaac_studio_camera_exposure()
                exposed_cameras = 0
                for prim_path in configured_camera_paths:
                    prim = self._stage.GetPrimAtPath(prim_path)
                    if not prim.IsValid() or not prim.IsA(UsdGeom.Camera):
                        continue
                    UsdGeom.Camera(prim).CreateExposureAttr().Set(exposure_ev)
                    exposed_cameras += 1
                print(
                    "[HandsOn/IsaacLab] B03 studio camera exposure: "
                    f"{exposure_ev:+.2f} EV on {exposed_cameras} cameras",
                    flush=True,
                )

            if self._live_main_camera_only:
                print(
                    "[HandsOn/IsaacLab] B03 Newton main-only live camera: "
                    f"head={self._render_width}x{self._render_height}, "
                    "wrists=deferred placeholders, "
                    f"renderer={'NewtonWarp' if recording_renderer_cfg_type else 'IsaacRTX'}",
                    flush=True,
                )
            elif legacy_wrist_cameras:
                print(
                    "[HandsOn/IsaacLab] Legacy recording cameras enabled: "
                    f"head={self._render_width}x{self._render_height}, "
                    f"wrists={wrist_width}x{wrist_height} 60deg VFOV, "
                    "native MJCF wrist prim binding, "
                    f"wrist_left_alias={self._camera_aliases.get('wrist_left_camera', '')}"
                    f"{legacy_wrist_source_desc}",
                    flush=True,
                )
            else:
                print(
                    "[HandsOn/IsaacLab] Circular-mount recording camera profile enabled: "
                    f"head={self._render_width}x{self._render_height}, "
                    f"wrists={wrist_width}x{wrist_height} "
                    "serial-specific HFOV "
                    f"(left={_WRIST_RECORDING_CAMERA_HFOV_BY_SIDE['left']:g}, "
                    f"right={_WRIST_RECORDING_CAMERA_HFOV_BY_SIDE['right']:g}), "
                    "independent circular-mount tracking, "
                    f"renderer={'NewtonWarp' if recording_renderer_cfg_type else 'IsaacRTX'}",
                    flush=True,
                )
        except Exception as exc:
            message = f"Recording cameras unavailable; render will use fallback frames: {exc}"
            self._isaac_warnings.append(message)
            print(f"[HandsOn/IsaacLab] {message}", flush=True)

    def _native_camera_prim_path(
        self,
        side: str,
        names: tuple[str, ...],
    ) -> str | None:
        if self._stage is None:
            return None
        from pxr import Usd, UsdGeom

        root_path = f"/World/HandsOnRobots/{side.capitalize()}Robot"
        root = self._stage.GetPrimAtPath(root_path)
        if not root.IsValid():
            return None
        cameras = {
            prim.GetName(): str(prim.GetPath())
            for prim in Usd.PrimRange(root)
            if prim.IsA(UsdGeom.Camera)
        }
        for name in names:
            if name in cameras:
                return cameras[name]
        return None

    def reset(self, seed: int | None = None, **kwargs: Any):
        target_label = kwargs.get("target_label") or kwargs.get("target_object")
        if self.task_name == xy3.TASK_NAME and target_label:
            self._xy3_fixed_target = str(target_label) if str(target_label) in xy3.FRUIT_NAMES else None
        if target_label:
            self._target_object_name = self._resolve_target_object(str(target_label))
        self._prepare_live_arm_visuals_for_stable_origin()
        reset_observation, reset_info = super().reset(seed=seed)

        # The parent reset historically returns after one physics frame.  Keep
        # that lifecycle unchanged for legacy ABC tasks.  Priority-zero tasks
        # opt into their longer actual-state settle; hands-only guidance uses
        # a short task-object-only settle in place of the inapplicable V3 robot
        # gate.  Counting the frame already completed by the parent keeps the
        # requested settle length exact.
        ready_state_settle_steps = self._public_reset_settle_physics_steps()
        if ready_state_settle_steps <= 5:
            return reset_observation, reset_info
        completed_steps = max(0, int(getattr(self, "_reset_physics_steps", 0)))
        additional_steps = max(0, ready_state_settle_steps - completed_steps)
        for _ in range(additional_steps):
            self._step_isaaclab()
            self._reset_physics_steps += 1

        self._refresh_object_poses()
        if self.task_name == "t41_sort_nested_cups":
            self._initialize_ycb04_episode_evidence()
        self._sync_b320_tcp_command_poses_to_physical_state()
        self._validate_task_initial_state_before_ready()
        settled_info = dict(reset_info)
        settled_info.update(self._task_info())
        settled_info["isaac_warnings"] = tuple(
            getattr(self, "_isaac_warnings", ())
        )
        if bool(getattr(self, "_guidance_mode", False)):
            settled_info["task_guidance_settle_physics_steps"] = int(
                ready_state_settle_steps
            )
            settled_info["task_guidance_settle_seconds"] = float(
                ready_state_settle_steps * self._physics_dt
            )
        # Reset settling is outside every operator action interval.  Start a
        # clean fixed-rate trace boundary so these 120 setup frames can never
        # be mislabelled as substeps of action[0].
        physx_trace = getattr(self, "_physx_ground_truth_trace", None)
        if physx_trace is not None:
            physx_trace.begin_substep_capture()
        settled_observation = self._attach_physx_ground_truth(
            self._compute_observation()
        )
        return settled_observation, settled_info

    def accept_stable_recording_origin(
        self,
        _report: Mapping[str, Any],
    ) -> Mapping[str, Any] | None:
        """Reveal guarded live arms only after the physical origin is safe."""

        if not self._live_arm_visibility_guard_uses_stable_origin:
            return None
        restored = 0
        if self._live_arm_visuals_pending_stable_origin:
            restored = self._commit_live_arm_visibility(hidden=False)
            if restored <= 0:
                raise RuntimeError(
                    f"{self.task_name} stable origin could not restore its "
                    "live robot visuals."
                )
            print(
                "[HandsOn/IsaacLab] Stable recording origin accepted; "
                f"restored {restored} live robot visual prims "
                f"(viewport_pumped={self._live_arm_visibility_last_ui_pump})",
                flush=True,
            )
        return {
            "accepted": True,
            "live_robot_visuals_restored": int(restored),
            "viewport_pumped": bool(
                self._live_arm_visibility_last_ui_pump
            ),
        }

    def _finalize_ycb05_step(self, result):
        if self.task_name != YCB05_TASK_NAME:
            return result
        observation, reward, terminated, truncated, info = result
        succeeded = bool(info.get("succeed", False))
        failed = bool(info.get("failed", False))
        timed_out = bool(
            not succeeded
            and not failed
            and self.env_step * self._control_dt >= self._time_limit
        )
        if timed_out:
            info = dict(info)
            info["truncated"] = True
            info["terminal_reason"] = "time_limit"
            return observation, reward, False, True, info
        if failed:
            info = dict(info)
            info["terminal_reason"] = str(
                self._ycb05_state.get("failure_reason") or "physical_failure"
            )
            info["terminal_kind"] = (
                "invalid_physics"
                if self._ycb05_state.get("failure_reason") in {
                    "invalid_contact_state", "non_finite_or_broken_joint"
                }
                else "task_failure"
            )
        elif succeeded:
            info = dict(info)
            info["terminal_reason"] = "success_trigger_released_while_held"
        return observation, reward, terminated, truncated, info

    def restore_recorded_initial_state(
        self,
        state_parts: Mapping[str, np.ndarray],
    ) -> dict[str, Any]:
        """Restore recorded table and task-object poses before action replay."""
        if self.task_name == gen5.TASK_NAME and "gen5_hidden_state" in state_parts:
            gen5.restore_hidden_state(self, state_parts["gen5_hidden_state"])
        if self.task_name == "eval_gen06_spray_shoe":
            from . import eval_gen06_spray_shoe_scene as gen7
            gen7.restore_hidden_state(self, state_parts)
        if self.task_name == gen2_geometry.TASK_NAME and "gen2_hidden_state" in state_parts:
            gen2_geometry.restore_hidden_state(self, state_parts["gen2_hidden_state"])
        if self.task_name == gen1.TASK_NAME:
            task_state = np.asarray(state_parts.get("gen1_task_state", [0, 0, 0, 0]), dtype=np.float64)
            if task_state.shape != (4,) or not np.all(np.isfinite(task_state)):
                raise ValueError("GEN1 recorded task state must contain four finite values")
            counter = float(task_state[0])
            if counter < 0 or counter != int(counter):
                raise ValueError("GEN1 recorded success counter must be a nonnegative integer")
            self._success_counter = int(counter)
            self._last_gen1_success_metrics = {}
            if "gen1_reset_pose_wxyz" in state_parts:
                reset_pose = np.asarray(state_parts["gen1_reset_pose_wxyz"], dtype=np.float64)
                if reset_pose.shape != (7,) or not np.all(np.isfinite(reset_pose)):
                    raise ValueError("GEN1 recorded reset pose must contain seven finite values")
                self._gen1_sampled_reset_pose = reset_pose.copy()
        if self.task_name == "t47_trigger_drill_on_block":
            revision = np.asarray(
                state_parts.get("ycb05_semantics_revision", []), dtype=np.float64,
            )
            if revision.shape != (1,) or revision[0] != YCB05_SEMANTICS_REVISION:
                raise ValueError(
                    "YCB05 recording semantics revision mismatch; "
                    "legacy aim episodes require their original code"
                )
        ycb10_recorded_state = None
        if self.task_name == YCB10_TASK_NAME:
            # Validate before touching the scene.  The reference transforms,
            # unfinished transfer and final-hold history affect future success;
            # restoring poses alone would silently restart that history.
            ycb10_recorded_state = YCB10SemanticState.from_hidden_vector(
                state_parts["ycb10_hidden_state"]
            )
            ycb10_forces = np.asarray(
                state_parts["finger_contact_forces"], dtype=np.float64
            ).reshape(5).copy()
            ycb10_validity = np.asarray(
                state_parts["ycb10_contact_validity"], dtype=np.float64
            ).reshape(8).copy()
            if not np.all(np.isfinite(ycb10_forces)) or not np.all(
                np.isin(ycb10_validity, [0.0, 1.0])
            ):
                raise ValueError("Invalid recorded YCB10 contact evidence")
        selector = np.asarray(
            state_parts.get("target_selector", np.zeros(0)),
            dtype=np.float64,
        ).ravel()
        if selector.size and self.task_name != ycb02.TASK_NAME:
            target_index = int(
                np.clip(
                    np.argmax(selector),
                    0,
                    len(self._spec.target_objects) - 1,
                )
            )
            self._target_object_name = self._spec.target_objects[target_index]

        delta = np.asarray(
            state_parts.get("table_delta_height", self.delta_h),
            dtype=np.float64,
        ).ravel()
        if delta.size and self.task_name != ycb02.TASK_NAME:
            self.delta_h[:] = float(delta[0])
            self._restore_recorded_table_height(float(delta[0]))

        recorded_poses: dict[str, np.ndarray] = {}
        # Keep the raw YCB02 object-pose payload until the task-specific
        # validator below can reject an accidental time/batch dimension.  The
        # generic restorers retain their historical flattening behaviour.
        if self.task_name == ycb02.TASK_NAME:
            object_poses = np.zeros((0, 7), dtype=np.float64)
        else:
            object_poses = np.asarray(
                state_parts.get("object_poses", np.zeros((0, 7))),
                dtype=np.float64,
            ).reshape(-1, 7)
        for name, pose in zip(self._spec.target_objects, object_poses):
            recorded_poses[name] = pose

        if self.task_name == ycb02.TASK_NAME:
            # Validate every YCB02 pose before restoring identity or changing
            # the table.  Recording-only arrays are authoritative for the
            # complete randomized layout; accepting a short/NaN array here
            # would silently leave part of a replay at the fresh reset pose.
            if "object_poses" in state_parts:
                object_poses = self._validate_ycb02_recorded_pose_rows(
                    state_parts["object_poses"],
                    key="object_poses",
                    allow_empty=True,
                )
                recorded_poses = {
                    name: pose
                    for name, pose in zip(self._spec.target_objects, object_poses)
                }

            all_ball_key = next(
                (
                    key
                    for key in ("ycb02_all_ball_poses", "all_ycb_ball_poses")
                    if key in state_parts
                ),
                None,
            )
            all_ball_poses = (
                np.zeros((0, 7), dtype=np.float64)
                if all_ball_key is None
                else self._validate_ycb02_recorded_pose_rows(
                    state_parts[all_ball_key],
                    key=all_ball_key,
                    expected_count=len(ycb02.BALL_NAMES),
                )
            )
            candidate_ball_poses = (
                np.zeros((0, 7), dtype=np.float64)
                if "candidate_ball_poses" not in state_parts
                else self._validate_ycb02_recorded_pose_rows(
                    state_parts["candidate_ball_poses"],
                    key="candidate_ball_poses",
                    expected_count=len(ycb02.BALL_NAMES),
                )
            )
            all_cup_key = next(
                (
                    key
                    for key in ("ycb02_all_cup_poses", "all_ycb_cup_poses")
                    if key in state_parts
                ),
                None,
            )
            all_cup_poses = (
                np.zeros((0, 7), dtype=np.float64)
                if all_cup_key is None
                else self._validate_ycb02_recorded_pose_rows(
                    state_parts[all_cup_key],
                    key=all_cup_key,
                    expected_count=len(ycb02.CUP_NAMES),
                )
            )
            active_cup_pose_rows = (
                np.zeros((0, 7), dtype=np.float64)
                if "active_cup_pose" not in state_parts
                else self._validate_ycb02_recorded_pose_rows(
                    state_parts["active_cup_pose"],
                    key="active_cup_pose",
                    expected_count=1,
                )
            )
            if delta.size and (
                delta.size != 1 or not np.all(np.isfinite(delta))
            ):
                raise ValueError(
                    "YCB02 recorded table_delta_height must be one finite value"
                )

            # Restore the hidden identity before resolving the active-cup
            # alias below.  Without this ordering a replay of (for example)
            # the j-cup variant would silently use the constructor's default
            # constructor-default C-cup/golf-ball semantics.
            if delta.size:
                self.delta_h[:] = float(delta[0])
                self._restore_recorded_table_height(float(delta[0]))
            self._restore_ycb02_recorded_episode_state(state_parts)

            # The public flat state stores all four candidate poses, while
            # recording-only telemetry stores all seven bodies. Accept
            # either representation so initial-state and state-guided replay
            # both restore the complete randomized scene.
            for name, pose in zip(ycb02.BALL_NAMES, all_ball_poses):
                recorded_poses[name] = pose
            for name, pose in zip(self._ycb02_candidate_order, candidate_ball_poses):
                recorded_poses[name] = pose
            for name, pose in zip(ycb02.CUP_NAMES, all_cup_poses):
                recorded_poses[name] = pose
            if active_cup_pose_rows.shape[0]:
                recorded_poses[self._ycb02_active_cup_name] = (
                    active_cup_pose_rows[0]
                )

            # A fresh replay reset has its own sampled layout.  Replace that
            # diagnostic with the recorded layout exactly once, but never
            # recompute the lift baseline from later moving state-guided
            # frames.
            if not self._ycb02_recorded_layout_restored:
                recorded_xy = {
                    name: np.asarray(pose[:2], dtype=np.float64).copy()
                    for name, pose in recorded_poses.items()
                    if name in (*ycb02.CUP_NAMES, *ycb02.BALL_NAMES)
                    and np.asarray(pose).size >= 2
                }
                if recorded_xy:
                    self._ycb02_reset_xy = recorded_xy
                self._ycb02_recorded_layout_restored = True

        if (
            not selector.size
            and object_poses.size
            and "target_object_pose" in state_parts
        ):
            target_pose = np.asarray(
                state_parts.get("target_object_pose", np.zeros(0)),
                dtype=np.float64,
            ).ravel()
            if target_pose.size >= 3:
                candidates = list(zip(self._spec.target_objects, object_poses))
                if candidates:
                    distances = np.asarray(
                        [
                            np.linalg.norm(np.asarray(pose[:3], dtype=np.float64) - target_pose[:3])
                            for _name, pose in candidates
                        ],
                        dtype=np.float64,
                    )
                    finite = np.isfinite(distances)
                    if np.any(finite):
                        target_index = int(np.argmin(np.where(finite, distances, np.inf)))
                        self._target_object_name = candidates[target_index][0]

        for state_key, role in self._spec.aliases.items():
            if state_key not in state_parts:
                continue
            if role == "target":
                name = self._target_object_name
            elif role == "receptacle":
                name = (
                    self._ycb02_active_cup_name
                    if self.task_name == ycb02.TASK_NAME
                    else self._spec.receptacle
                )
            else:
                name = role
            if self.task_name == ycb02.TASK_NAME:
                # YCB02 aliases (currently active_cup_pose) are part of the
                # same authoritative pose payload validated above.  Validate
                # again here because this loop would otherwise overwrite the
                # normalized copy with an unchecked raw state slice.
                alias_pose = self._validate_ycb02_recorded_pose_rows(
                    state_parts[state_key],
                    key=state_key,
                    expected_count=1,
                )
                recorded_poses[name] = alias_pose[0]
            else:
                pose = np.asarray(state_parts[state_key], dtype=np.float64).ravel()
                if pose.size >= 7:
                    recorded_poses[name] = pose[:7]

        if self.task_name == YCB01_TASK_NAME:
            gate_frame = np.asarray(
                state_parts.get("gate_frame_pose", self._ycb01_gate_frame_pose),
                dtype=np.float64,
            ).ravel()
            if gate_frame.size >= 7:
                self._ycb01_gate_frame_pose = gate_frame[:7].copy()
            start_direction = np.asarray(
                state_parts.get("ycb01_start_direction", np.zeros(0)),
                dtype=np.float64,
            ).ravel()
            if start_direction.size:
                self._ycb01_travel_direction = (
                    -1.0 if float(start_direction[0]) < 0.0 else 1.0
                )
            flags = np.asarray(
                state_parts.get("ycb01_event_flags", np.zeros(0)),
                dtype=np.float64,
            ).ravel()
            if flags.size >= 7:
                self._ycb01_start_side_seen = bool(flags[0] > 0.5)
                self._ycb01_hand_contact_seen = bool(flags[1] > 0.5)
                self._ycb01_center_crossed = bool(flags[2] > 0.5)
                self._ycb01_full_passed = bool(flags[3] > 0.5)
                self._ycb01_valid_crossing_latched = self._ycb01_full_passed
                self._ycb01_table_supported_recently = bool(flags[4] > 0.5)
            hidden = np.asarray(
                state_parts.get("ycb01_hidden_state", np.zeros(0)),
                dtype=np.float64,
            ).ravel()
            if hidden.size >= 9:
                self._ycb01_previous_ball_position = hidden[:3].copy()
                self._ycb01_lift_violation_seconds = float(hidden[3])
                self._ycb01_gate_violation_seconds = float(hidden[4])
                self._ycb01_last_contact_force = float(hidden[5])
                self._ycb01_reset_ordinal = int(round(float(hidden[7])))
                self._ycb01_failure_reason = {
                    1: "ball_lifted_or_thrown",
                    2: "ball_fell_off_table",
                    3: "gate_displaced_or_toppled",
                    4: "ball_or_hand_touched_gate",
                }.get(int(round(float(hidden[8]))))
            self._ycb01_reset_post_poses = {
                name: pose.copy()
                for name, pose in recorded_poses.items()
                if name in YCB01_GATE_BODY_NAMES
            }

        restored_views: set[int] = set()
        for name, pose in recorded_poses.items():
            view = self._task_body_views.get(name)
            if view is None or id(view) in restored_views:
                continue
            if self._set_task_body_world_pose(view, pose):
                restored_views.add(id(view))

        if self._direct_hand_control:
            # Direct physical replay has no arm/IK state to reconstruct.  Its
            # complete robot initial condition is exactly the recorded palm
            # command plus the 20 Wuji joint positions.
            self._restore_recorded_robot_command_state(state_parts)
            self._reset_robot_control_state()

        if self.task_name == YCB05_TASK_NAME:
            trigger_state = np.asarray(
                state_parts.get("trigger_state", np.zeros(0)),
                dtype=np.float64,
            ).ravel()
            if trigger_state.size >= 2:
                self._set_ycb05_trigger_state(
                    float(trigger_state[0]),
                    float(trigger_state[1]),
                )
            sampled = np.asarray(
                state_parts.get("ycb05_sampled_reset_poses", np.zeros((0, 7))),
                dtype=np.float64,
            ).reshape(-1, 7)
            if sampled.shape[0] >= 2:
                self._ycb05_sampled_reset_poses = {
                    YCB05_DRILL_NAME: sampled[0].copy(),
                    YCB05_WOOD_NAME: sampled[1].copy(),
                }
            references = np.asarray(
                state_parts.get("ycb05_reference_poses", np.zeros((0, 7))),
                dtype=np.float64,
            ).reshape(-1, 7)
            if references.shape[0] >= 2:
                self._ycb05_drill_reset_pose = references[0].copy()
                self._ycb05_wood_reset_pose = references[1].copy()
                self._ycb05_settled_reference_captured = True
            stage_value = np.asarray(
                state_parts.get("ycb05_stage", np.zeros(0)),
                dtype=np.float64,
            ).ravel()
            timers = np.asarray(
                state_parts.get("ycb05_timers", np.zeros(0)),
                dtype=np.float64,
            ).ravel()
            flags = np.asarray(
                state_parts.get("ycb05_event_flags", np.zeros(0)),
                dtype=np.float64,
            ).ravel()
            terminal_reason = np.asarray(
                state_parts.get("ycb05_terminal_reason", np.zeros(0)),
                dtype=np.float64,
            ).ravel()
            restored_state = initial_ycb05_state()
            if stage_value.size:
                restored_state["stage"] = int(np.clip(round(float(stage_value[0])), -1, 5))
            timer_names = (
                "settle_s",
                "grasp_s",
                "aim_s",
                "press_s",
                "release_s",
                "target_contact_s",
                "early_press_s",
                "press_aim_loss_s",
            )
            for name, value in zip(timer_names, timers):
                restored_state[name] = max(0.0, float(value))
            flag_names = (
                "grasp_seen",
                "lift_seen",
                "aim_dwell_seen",
                "trigger_contact_seen",
                "valid_press_seen",
                "trigger_release_seen",
                "wrong_order_press_seen",
                "target_contact_seen",
                "drop_seen",
                "success",
            )
            for name, value in zip(flag_names, flags):
                restored_state[name] = bool(value >= 0.5)
            if terminal_reason.size:
                reason_code = int(round(float(terminal_reason[0])))
                restored_state["failure_reason"] = YCB05_FAILURE_CODE_REASONS.get(
                    reason_code
                )
            invalid_channels = np.asarray(
                state_parts.get("ycb05_invalid_contact_channels", np.zeros(10))
            ).ravel()
            restored_state["invalid_contact_channels"] = [
                key for key, value in zip(YCB05_CONTACT_CHANNELS, invalid_channels)
                if value >= 0.5
            ]
            self._ycb05_state = restored_state
            grace = np.asarray(
                state_parts.get("ycb05_contact_grace", np.zeros(10)), dtype=np.float64
            ).ravel()
            if (grace.shape != (len(YCB05_CONTACT_CHANNELS),)
                    or not np.all(np.isfinite(grace))
                    or np.any(grace != np.round(grace))
                    or np.any(grace < 0)
                    or np.any(grace > np.asarray(_YCB05_CONTACT_GRACE_LIMITS))):
                raise ValueError("Invalid recorded YCB05 contact grace counters")
            self._ycb05_contact_grace = {
                key: int(value) for key, value in zip(YCB05_CONTACT_CHANNELS, grace)
            }

        if ycb10_recorded_state is not None:
            self._ycb10_state = ycb10_recorded_state
            self._ycb10_last_finger_forces = ycb10_forces
            self._ycb10_last_contact_validity = ycb10_validity

        if self._sim is not None:
            self._sim.forward()
        for robot in self._robots.values():
            robot.update(0.0)
        self._refresh_object_poses()
        if self.task_name == "t41_sort_nested_cups":
            restored_ycb04_poses = {
                cup.name: self._poses.get(
                    cup.name,
                    self._fallback_pose(cup.name),
                ).copy()
                for cup in _ycb04.CUPS_LARGE_TO_SMALL
            }
            self._ycb04_observable_previous_poses = restored_ycb04_poses
            recorded_velocities = np.asarray(
                state_parts.get("cup_velocities", np.zeros((0, 6))),
                dtype=np.float64,
            ).reshape(-1, 6)
            self._ycb04_observable_velocities = {
                cup.name: (
                    recorded_velocities[index].copy()
                    if index < recorded_velocities.shape[0]
                    else np.zeros(6, dtype=np.float64)
                )
                for index, cup in enumerate(_ycb04.CUPS_LARGE_TO_SMALL)
            }
        if self.task_name == _YCB07_TASK_NAME:
            # Restore the timer state machine together with its physical pose.
            # Without this, replay starts with the recorded button display but
            # a freshly reset logical state, so the UI and success gate diverge.
            target = np.asarray(
                state_parts.get(
                    "timer_target",
                    (
                        self._ycb07_state.target_minutes,
                        self._ycb07_state.target_seconds,
                    ),
                ),
                dtype=np.float64,
            ).ravel()
            if target.size >= 2:
                restored_target = (int(round(target[0])), int(round(target[1])))
                if restored_target not in _YCB07_TARGETS:
                    raise ValueError(
                        f"recorded YCB07 target {restored_target!r} is not canonical"
                    )
                self._ycb07_state.reset(restored_target)
            self._ycb07_state.restore_logic_vector(
                np.asarray(
                    state_parts.get("timer_logic", np.zeros(0)),
                    dtype=np.float64,
                ).ravel()
            )
            self._ycb07_state.restore_latch_vector(
                np.asarray(
                    state_parts.get("timer_button_latches", np.zeros(0)),
                    dtype=np.float64,
                ).ravel()
            )
            self._last_ycb07_success_metrics = self._ycb07_timer_metrics(
                update_state=False
            )

        if self.task_name == ycb09.TASK_NAME:
            self._restore_ycb09_recorded_progress(state_parts)
        return self._compute_observation()

    def _restore_ycb09_recorded_progress(self, state_parts) -> None:
        """Restore semantic state at the recorded origin, before action 0."""
        for key, attr in (
            ("wine_glass_reset_pose", "_ycb09_glass_reset_pose"),
            ("plate_reset_pose", "_ycb09_plate_reset_pose"),
        ):
            if key in state_parts:
                pose = np.asarray(state_parts[key], dtype=np.float64)
                if pose.shape != (7,) or not np.all(np.isfinite(pose)):
                    raise ValueError(f"Invalid YCB09 recorded {key}")
                setattr(self, attr, pose.copy())
        hidden = np.asarray(state_parts.get("ycb09_hidden_state", []), dtype=np.float64).ravel()
        if not hidden.size:
            return
        if hidden.size not in (13, ycb09.HIDDEN_STATE_SIZE) or not np.all(np.isfinite(hidden)):
            raise ValueError("Invalid YCB09 recorded hidden state")
        # Legacy clean origins remain replayable. A legacy mid-carry state
        # lacks the continuous segment origin and cannot establish that proof.
        if hidden.size == 13 and (hidden[3] >= 0.5 or hidden[4] >= 0.5):
            raise ValueError("Legacy YCB09 carry state has no continuous carry origin")
        self._seed, self._ycb09_reset_ordinal = int(hidden[0]), int(hidden[1])
        for index, attr in (
            (2, "_ycb09_lift_hold_steps"), (5, "_ycb09_hand_clear_steps"),
            (6, "_ycb09_stability_steps"), (7, "_ycb09_glass_off_table_steps"),
            (8, "_ycb09_plate_off_table_steps"),
        ):
            setattr(self, attr, max(0.0, float(hidden[index])))
        self._ycb09_lifted, self._ycb09_transported = hidden[3] >= 0.5, hidden[4] >= 0.5
        self._ycb09_terminal_reason = {0: "", 1: "glass_off_table", 2: "plate_off_table"}.get(int(hidden[9]), "invalid_recorded_terminal_state")
        self._ycb09_invalid_reason = {0: "", 1: "nonfinite_or_missing_rigid_state", 2: "invalid_contact_state"}.get(int(hidden[10]), "invalid_recorded_hidden_state")
        self._ycb09_carry_start_position = (
            hidden[14:17].copy() if hidden.size == ycb09.HIDDEN_STATE_SIZE and hidden[13] >= 0.5 else None
        )
        self._ycb09_capture_reset_pending = False
        self._last_ycb09_metrics = {}

    def restore_recorded_visual_state(
        self,
        state_parts: Mapping[str, np.ndarray],
        *,
        robot_iterations: int = 8,
    ) -> dict[str, Any]:
        """Restore recorded task objects and drive robot visuals toward state.

        Historical ABC zarr episodes only store TCP and hand command state, not
        the complete PhysX articulation qpos.  This method is therefore a
        best-effort visual reconstruction path: it restores task objects exactly
        and repeatedly solves/writes the robot joint targets from the recorded
        TCP + gripper state before rendering.
        """
        self.restore_recorded_initial_state(state_parts)
        self._restore_recorded_robot_command_state(state_parts)
        self._snap_robot_to_command_state(robot_iterations)
        if self._sim is not None:
            self._sim.forward()
        if self._scene is not None:
            try:
                self._scene.update(0.0)
            except Exception:
                pass
        self._refresh_object_poses()
        return self._compute_observation()

    def apply_recorded_visual_arm_qpos(
        self,
        arm_qpos: np.ndarray,
    ) -> dict[str, Any]:
        """Apply one certified offline ROKAE plan frame for post-rendering.

        This is intentionally unavailable in the detached live runtime.  The
        post-render process starts an ordinary full-robot scene, restores the
        recorded task/hand state, then writes these 14 planned arm joints so
        rendering never falls back to frame-local online IK.
        """

        if self._direct_hand_control:
            raise RuntimeError(
                "Offline arm qpos must be rendered in a full-robot scene"
            )
        values = np.asarray(arm_qpos, dtype=np.float64).reshape(-1)
        if values.shape != (14,) or not np.all(np.isfinite(values)):
            raise ValueError("Offline visual arm qpos must be finite shape (14,)")
        for offset, side in ((0, "right"), (7, "left")):
            robot = self._control_robot(side)
            ids = self._arm_joint_ids.get(side, ())
            if len(ids) != 7:
                raise RuntimeError(
                    f"Expected seven {side} ROKAE arm joints, got {len(ids)}"
                )
            joint_pos = _torch_view(robot.data.joint_pos).clone()
            joint_vel = self._torch.zeros_like(joint_pos)
            planned = self._torch.as_tensor(
                values[offset : offset + 7],
                dtype=joint_pos.dtype,
                device=joint_pos.device,
            )
            joint_pos[:, ids] = planned
            robot.write_joint_state_to_sim(joint_pos, joint_vel)
            robot.set_joint_position_target(joint_pos)
            robot.write_data_to_sim()
            self._joint_targets[side] = joint_pos.clone()
        if self._sim is not None:
            self._sim.forward()
        if self._scene is not None:
            try:
                self._scene.update(0.0)
            except Exception:
                pass
        for robot in self._robots.values():
            robot.update(0.0)
        self._refresh_object_poses()
        return self._compute_observation()

    def evaluate_restored_physx_replay_state(self) -> dict[str, Any]:
        """Evaluate a trusted recorded snapshot without advancing PhysX.

        Contact impulses are not part of the ground-truth state contract.  C04
        therefore reconstructs its spray latch from the recorded trigger DOF;
        object aiming and every other success condition are still recomputed
        from the restored simulator poses.
        """

        self._refresh_object_poses()
        if self.task_name == "t50_water_plant":
            reading = self._physics_dof_position("joint_0")
            if reading is not None:
                trigger_position, _initial_position = reading
                emitting = self._c04_spray_should_be_visible(
                    trigger_position,
                    self._c04_water_emitting,
                )
                if trigger_position <= _C04_TRIGGER_RELEASE_RAD:
                    self._c04_trigger_cycle_latched = False
                elif emitting:
                    self._c04_trigger_cycle_latched = True
                self._c04_trigger_pulled = bool(emitting)
                self._c04_water_emitting = bool(emitting)
                self._c04_trigger_phase = (
                    "pressed" if emitting else "pressing"
                )
                self._update_c04_spray_visual()

        if self.task_name == "eval_gen06_spray_shoe":
            # A rendered/restored snapshot is not another control frame.
            success = bool(
                self._gen7_spray_shoe_success_now()
                and self._success_counter >= self._success_steps_required()
            )
        else:
            success = bool(self._compute_success())
        failed = bool(self._compute_failure())
        info: dict[str, Any] = {
            "env_succeed": success,
            "failed": failed,
        }
        info.update(self._task_info())
        from .blender_visual_layer import configured_blender_visual_metadata

        info.update(configured_blender_visual_metadata(self))
        return info

    def _restore_recorded_robot_command_state(
        self,
        state_parts: Mapping[str, np.ndarray],
    ) -> None:
        tcp_pose = np.asarray(
            state_parts.get("tcp_pose", np.zeros(0)),
            dtype=np.float64,
        ).ravel()
        if tcp_pose.size >= 7:
            right_pose = tcp_pose[:7].astype(np.float64, copy=True)
            if np.all(np.isfinite(right_pose)) and not np.allclose(right_pose[:7], 0.0):
                quat_norm = float(np.linalg.norm(right_pose[3:7]))
                if quat_norm > 1e-8:
                    right_pose[3:7] /= quat_norm
                    self._right_tcp_pose = right_pose
                    self._right_pose_commanded = True
                    self._arm_pose_filters["right"] = None
        if tcp_pose.size >= 14:
            left_pose = tcp_pose[7:14].astype(np.float64, copy=True)
            if np.all(np.isfinite(left_pose)) and not np.allclose(left_pose[:7], 0.0):
                quat_norm = float(np.linalg.norm(left_pose[3:7]))
                if quat_norm > 1e-8:
                    left_pose[3:7] /= quat_norm
                    self._left_tcp_pose = left_pose
                    self._left_pose_commanded = True
                    self._arm_pose_filters["left"] = None

        gripper_pose = np.asarray(
            state_parts.get("gripper_pose", np.zeros(0)),
            dtype=np.float64,
        ).ravel()
        if not gripper_pose.size:
            return

        if self._spec.bimanual and gripper_pose.size >= 32:
            right_size = min(16, self._right_hand.size)
            left_size = min(16, self._left_hand.size)
            if right_size:
                self._right_hand[:right_size] = gripper_pose[:right_size]
            if left_size:
                self._left_hand[:left_size] = gripper_pose[16 : 16 + left_size]
            return

        right_size = min(self._right_hand.size, gripper_pose.size)
        if right_size:
            self._right_hand[:right_size] = gripper_pose[:right_size]

    def _snap_robot_to_command_state(self, robot_iterations: int) -> None:
        if not self._robots or self._torch is None:
            return
        iterations = max(1, int(robot_iterations))
        for _ in range(iterations):
            self._apply_joint_targets()
            self._write_joint_targets_as_state()
            if self._sim is not None:
                self._sim.forward()
            if self._scene is not None:
                try:
                    self._scene.update(0.0)
                except Exception:
                    pass
            for robot in self._robots.values():
                try:
                    robot.update(0.0)
                except Exception:
                    pass

    def _write_joint_targets_as_state(self) -> None:
        for side, robot in self._robots.items():
            target = self._joint_targets.get(side)
            if target is None:
                continue
            try:
                joint_pos = target.clone()
                joint_vel = self._torch.zeros_like(joint_pos)
                robot.write_joint_state_to_sim(joint_pos, joint_vel)
                robot.set_joint_position_target(joint_pos)
                robot.write_data_to_sim()
            except Exception as exc:
                message = f"{side} robot visual state restore failed: {exc}"
                if message not in self._isaac_warnings:
                    self._isaac_warnings.append(message)
                    print(f"[HandsOn/IsaacLab] {message}", flush=True)

    def _restore_recorded_table_height(self, delta_height: float) -> bool:
        table_prim = self._find_rigid_body_prim("table")
        if table_prim is None:
            return False
        table_path = str(table_prim.GetPath())
        for path, view, indices, root_pose, root_velocity in self._task_reset_body_states:
            if path != table_path:
                continue
            restored_pose = _randomized_physx_pose(
                root_pose.detach().cpu().numpy(),
                xy_offset=np.zeros(2, dtype=np.float64),
                z_offset=float(delta_height),
                yaw_degrees=0.0,
            )
            pose_tensor = self._torch.as_tensor(
                restored_pose,
                dtype=root_pose.dtype,
                device=root_pose.device,
            )
            self._write_rigid_reset_state(
                path,
                view,
                indices,
                pose_tensor,
                self._torch.zeros_like(root_velocity),
            )
            return True
        return False

    def _forbid_physics_only_task_state_write(
        self,
        writer: str,
        *,
        subject: str | None = None,
    ) -> None:
        """Fail before mutating a certified task body during an action."""

        is_certified_physics_only = bool(
            self.task_name == "c07_pitcher_pour_cup"
            or self.task_name in _C_TOOL_PHYSICS_ONLY_COLLECTION_TASKS
        )
        if not is_certified_physics_only or not getattr(
            self,
            "_trajectory_action_phase_active",
            False,
        ):
            return
        suffix = "" if subject is None else f" for {subject}"
        raise RuntimeError(
            f"{self.task_name} forbids {writer}{suffix} during collection; "
            "robot drives, gravity, contacts, and articulation drives must "
            "advance task bodies"
        )

    def _set_task_body_world_pose(self, view: Any, pose_wxyz: np.ndarray) -> bool:
        self._forbid_physics_only_task_state_write(
            "task-body root pose/velocity writes"
        )
        if self._torch is None:
            return False
        try:
            transforms = view.get_transforms().clone()
            velocities = view.get_velocities().clone()
            original_transforms = transforms.clone()
            original_velocities = velocities.clone()
            pose = np.asarray(pose_wxyz, dtype=np.float64).reshape(7)
            transforms[:, :3] = self._torch.as_tensor(
                pose[:3],
                dtype=transforms.dtype,
                device=transforms.device,
            )
            transforms[:, 3:7] = self._torch.as_tensor(
                [pose[4], pose[5], pose[6], pose[3]],
                dtype=transforms.dtype,
                device=transforms.device,
            )
            indices = self._torch.arange(
                int(view.count),
                dtype=self._torch.long,
                device=self._isaac_device,
            )
            try:
                # A velocity failure must not leave a transform-only teleport.
                zero_velocities = self._torch.zeros_like(velocities)
                view.set_velocities(
                    zero_velocities,
                    indices,
                )
                view.set_transforms(transforms, indices)
            except Exception:
                try:
                    view.set_velocities(original_velocities, indices)
                    view.set_transforms(original_transforms, indices)
                except Exception:
                    pass
                raise
            subject = next(
                (
                    name
                    for name, candidate in self._task_body_views.items()
                    if candidate is view
                ),
                None,
            )
            reset_path = next(
                (
                    str(path)
                    for path, candidate, *_state in self._task_reset_body_states
                    if candidate is view
                ),
                None,
            )
            if reset_path is None:
                reset_path = next(
                    (
                        str(path)
                        for path, candidate, *_state in (
                            self._task_reset_articulation_states
                        )
                        if candidate is view
                    ),
                    None,
                )
            if reset_path is not None:
                # The PhysX tensor frontend can return the preceding frame's
                # cached transform immediately after a setter.  Preserve the
                # exact authored reset payload so deliberate task
                # randomization is not later misclassified as solver drift.
                self._record_authored_task_reset_write(
                    reset_path,
                    transform_xyzw=transforms,
                    velocity=zero_velocities,
                )
            self._record_trajectory_state_write(
                "_set_task_body_world_pose",
                subject=subject,
            )
            return True
        except Exception as exc:
            self._add_task_state_warning(f"Could not restore recorded object pose: {exc}")
            return False

    @staticmethod
    def _ycb02_footprint_radius(name: str) -> float:
        if name in ycb02.BALL_RADIUS_M:
            return float(ycb02.BALL_RADIUS_M[name])
        try:
            return float(ycb02.CUP_FOOTPRINT_RADIUS_M[name])
        except (AttributeError, KeyError) as exc:
            # Keep an unknown body from silently entering the sampler with a
            # zero footprint.  This is a programmer/configuration error, not a
            # recoverable random-sampling miss.
            raise KeyError(f"Unknown YCB02 footprint body: {name!r}") from exc

    @staticmethod
    def _ycb02_object_bound_radius(name: str) -> float:
        """Return a conservative 3-D sphere radius for reset hand checks.

        The reset gate samples XY centres, but the complete ROKAE/Wuji body
        cloud is three-dimensional.  A cup's vertical wall/rim therefore has
        to contribute to the hand envelope even when its XY projection is
        clear.  The circumscribed sphere is intentionally conservative and
        remains valid for every yaw sampled by ``_apply_task_pose_randomization``.
        """

        footprint = HandsOnABCIsaacLabEnv._ycb02_footprint_radius(name)
        if name in ycb02.BALL_RADIUS_M:
            return float(footprint)
        half_height = max(
            abs(float(ycb02.CUP_SUPPORT_LOCAL_MIN_Z_M[name])),
            abs(float(ycb02.CUP_RIM_LOCAL_Z_M[name])),
        )
        return float(math.hypot(footprint, half_height))

    @classmethod
    def _ycb02_reach_margin(
        cls,
        name: str,
        xy: np.ndarray,
        table_top_z: float,
    ) -> float:
        """Return the signed bilateral arm-workspace margin for one centre.

        The bimanual controller's axis-aligned target clamp is implemented as
        a 0.78 m sphere around each ROKAE arm root.  A rectangular reset bound
        can therefore claim a point is valid while the nearest arm still
        cannot reach it (the failure appears later as an unresponsive action).
        Check the nominal grasp point in 3-D against both roots and retain a
        small reserve for IK interpolation and the randomized table height.
        This helper is deliberately geometry-only so offline reset diagnostics
        can exercise the same predicate without constructing Isaac.
        """
        xy = np.asarray(xy, dtype=np.float64).reshape(2)
        bases = np.asarray(ycb02.RESET_ARM_BASES_M, dtype=np.float64)
        if bases.shape != (2, 3) or not np.all(np.isfinite(bases)):
            raise RuntimeError("YCB02 arm workspace bases are malformed")
        workspace_radius = float(ycb02.RESET_ARM_WORKSPACE_RADIUS_M)
        reach_clearance = float(ycb02.RESET_ARM_REACH_CLEARANCE_M)
        if not np.isfinite(workspace_radius) or workspace_radius <= 0.0:
            raise RuntimeError("YCB02 arm workspace radius is malformed")
        if not np.isfinite(reach_clearance) or reach_clearance < 0.0:
            raise RuntimeError("YCB02 arm reach clearance is malformed")
        if name in ycb02.BALL_RADIUS_M:
            root_z = float(table_top_z) + float(ycb02.BALL_RADIUS_M[name])
        else:
            root_z = float(table_top_z) - float(
                ycb02.CUP_SUPPORT_LOCAL_MIN_Z_M[name]
            )
        grasp_height = float(ycb02.RESET_OBJECT_GRASP_HEIGHT_M)
        if not np.isfinite(grasp_height) or grasp_height < 0.0:
            raise RuntimeError("YCB02 grasp height is malformed")
        target = np.asarray(
            [float(xy[0]), float(xy[1]), root_z + grasp_height],
            dtype=np.float64,
        )
        nearest = float(np.min(np.linalg.norm(bases - target, axis=1)))
        return workspace_radius - reach_clearance - nearest

    @classmethod
    def _ycb02_camera_ellipse_margin(
        cls,
        name: str,
        xy: np.ndarray,
    ) -> float:
        """Return signed clearance to the conservative head-camera ellipse.

        The real-v1 head camera's tabletop projection narrows toward the left
        edge.  An ellipse is a stable, simulator-independent approximation of
        that footprint and avoids the corner leaks of an axis-aligned box.  We
        shrink its radii by the body's circumscribed XY footprint and an image
        reserve, then convert the normalized radial slack back to metres so it
        can be compared with the other reset clearances.
        """
        center = np.asarray(
            ycb02.RESET_CAMERA_ELLIPSE_CENTER_M,
            dtype=np.float64,
        ).reshape(2)
        radii = np.asarray(
            ycb02.RESET_CAMERA_ELLIPSE_RADII_M,
            dtype=np.float64,
        ).reshape(2)
        if (
            center.shape != (2,)
            or radii.shape != (2,)
            or not np.all(np.isfinite(center))
            or not np.all(np.isfinite(radii))
            or np.any(radii <= 0.0)
        ):
            raise RuntimeError("YCB02 camera ellipse is malformed")
        image_clearance = float(ycb02.RESET_CAMERA_CLEARANCE_M)
        if not np.isfinite(image_clearance) or image_clearance < 0.0:
            raise RuntimeError("YCB02 camera ellipse clearance is malformed")
        effective_radii = radii - (
            float(cls._ycb02_footprint_radius(name)) + image_clearance
        )
        if np.any(effective_radii <= 0.0):
            raise RuntimeError(
                f"YCB02 camera ellipse cannot contain {name!r} footprint"
            )
        xy = np.asarray(xy, dtype=np.float64).reshape(2)
        normalized_radius = float(
            np.linalg.norm((xy - center) / effective_radii)
        )
        return (1.0 - normalized_radius) * float(np.min(effective_radii))

    @classmethod
    def _ycb02_layout_margin(
        cls,
        xy_by_name: Mapping[str, np.ndarray],
        active_names: set[str] | None = None,
        hand_points: tuple[np.ndarray, ...] = (),
        table_top_z: float = _TABLE_TOP_Z,
        workspace_bounds: np.ndarray | tuple[tuple[float, float], tuple[float, float]] | None = None,
    ) -> float:
        """Return the signed clearance of a partial or complete YCB02 layout.

        ``active_names`` is retained for compatibility with older callers.
        Edge and pair checks always cover every supplied body; an explicit
        subset only narrows the legacy robot-envelope probe. Production YCB02
        reset calls pass all seven names, so all cups/balls are screened
        against both live arm body clouds. A positive return value means every
        tested boundary, pair, and 3-D robot-envelope gate is clear by that
        amount.
        """
        hand_checked_names = (
            set(xy_by_name)
            if active_names is None
            else set(active_names) & set(xy_by_name)
        )
        # Keep the historical helper default on the full physical table for
        # offline geometry callers (some diagnostics intentionally probe a
        # point outside the camera rectangle).  The production reset sampler
        # passes the calibrated recording bounds explicitly below; therefore
        # no sampled pose can leave the visible/reachable envelope.
        bounds = np.asarray(
            ycb02.RESET_XY_BOUNDS_M
            if workspace_bounds is None
            else workspace_bounds,
            dtype=np.float64,
        )
        if workspace_bounds is None:
            bounds = np.asarray(
                [
                    [ycb02.TABLE_X_BOUNDS_M[0], ycb02.TABLE_Y_BOUNDS_M[0]],
                    [ycb02.TABLE_X_BOUNDS_M[1], ycb02.TABLE_Y_BOUNDS_M[1]],
                ],
                dtype=np.float64,
            )
        if bounds.shape != (2, 2) or not np.all(np.isfinite(bounds)):
            raise RuntimeError("YCB02 reset XY bounds are malformed")
        physical_bounds = np.asarray(
            [
                [ycb02.TABLE_X_BOUNDS_M[0], ycb02.TABLE_Y_BOUNDS_M[0]],
                [ycb02.TABLE_X_BOUNDS_M[1], ycb02.TABLE_Y_BOUNDS_M[1]],
            ],
            dtype=np.float64,
        )
        if (
            physical_bounds.shape != (2, 2)
            or not np.all(np.isfinite(physical_bounds))
            or np.any(physical_bounds[0] >= physical_bounds[1])
        ):
            raise RuntimeError("YCB02 physical table bounds are malformed")
        edge_clearance = float(ycb02.RESET_EDGE_CLEARANCE_M)
        pair_clearance = float(ycb02.RESET_PAIR_CLEARANCE_M)
        hand_clearance = float(ycb02.RESET_HAND_CLEARANCE_M)
        margins: list[float] = []
        for name, xy in xy_by_name.items():
            if name not in (*ycb02.CUP_NAMES, *ycb02.BALL_NAMES):
                raise KeyError(f"Unknown YCB02 layout body: {name!r}")
            xy = np.asarray(xy, dtype=np.float64).reshape(2)
            if not np.all(np.isfinite(xy)):
                margins.append(-math.inf)
                continue
            radius = cls._ycb02_footprint_radius(name)
            margins.extend(
                (
                    float(xy[0])
                    - float(bounds[0, 0])
                    - radius
                    - edge_clearance,
                    float(bounds[1, 0])
                    - float(xy[0])
                    - radius
                    - edge_clearance,
                    float(xy[1])
                    - float(bounds[0, 1])
                    - radius
                    - edge_clearance,
                    float(bounds[1, 1])
                    - float(xy[1])
                    - radius
                    - edge_clearance,
                )
            )
            # The explicit workspace envelope is intentionally narrower than
            # the table, but keep an independent physical-table gate here so
            # a future envelope edit cannot let a circumscribed cup/ball cross
            # the support edge and start the episode interpenetrating the
            # table lip.
            if workspace_bounds is not None:
                margins.extend(
                    (
                        float(xy[0])
                        - float(physical_bounds[0, 0])
                        - radius
                        - edge_clearance,
                        float(physical_bounds[1, 0])
                        - float(xy[0])
                        - radius
                        - edge_clearance,
                        float(xy[1])
                        - float(physical_bounds[0, 1])
                        - radius
                        - edge_clearance,
                        float(physical_bounds[1, 1])
                        - float(xy[1])
                        - radius
                        - edge_clearance,
                    )
                )
            if name in ycb02.BALL_RADIUS_M:
                root_z = table_top_z + float(ycb02.BALL_RADIUS_M[name])
            else:
                root_z = table_top_z - float(
                    ycb02.CUP_SUPPORT_LOCAL_MIN_Z_M[name]
                )
            object_center = np.asarray(
                [float(xy[0]), float(xy[1]), float(root_z)],
                dtype=np.float64,
            )
            if name in hand_checked_names:
                object_bound_radius = cls._ycb02_object_bound_radius(name)
                for point in hand_points:
                    point_np = np.asarray(point, dtype=np.float64).reshape(-1)
                    if point_np.size < 3 or not np.all(np.isfinite(point_np[:3])):
                        margins.append(-math.inf)
                        continue
                    margins.append(
                        float(np.linalg.norm(object_center - point_np[:3]))
                        - object_bound_radius
                        - hand_clearance
                    )
            # ``workspace_bounds`` is an explicit production-sampler opt-in.
            # Keep the historical helper default useful for callers that probe
            # arbitrary physical-table points, but require every native reset
            # candidate to be reachable by at least one arm *and* safely in
            # the head-camera footprint.  Both margins are in metres and can
            # therefore share RESET_MIN_MARGIN_M with edge/pair checks.
            if workspace_bounds is not None:
                margins.append(
                    cls._ycb02_reach_margin(name, xy, table_top_z)
                )
                margins.append(cls._ycb02_camera_ellipse_margin(name, xy))
        names = sorted(xy_by_name)
        for index, name_a in enumerate(names):
            for name_b in names[index + 1 :]:
                clearance = (
                    cls._ycb02_footprint_radius(name_a)
                    + cls._ycb02_footprint_radius(name_b)
                    + pair_clearance
                )
                a = np.asarray(xy_by_name[name_a], dtype=np.float64).reshape(2)
                b = np.asarray(xy_by_name[name_b], dtype=np.float64).reshape(2)
                margins.append(float(np.linalg.norm(a - b)) - clearance)
        return min(margins) if margins else math.inf

    def _ycb02_reset_xy_positions(self) -> dict[str, np.ndarray]:
        """Place every cup and ball in hand-clear rows with shuffled identities."""

        all_names = (*ycb02.CUP_NAMES, *ycb02.BALL_NAMES)
        cup_order = tuple(self._ycb02_cup_order)
        ball_order = tuple(self._ycb02_candidate_order)
        if len(cup_order) != len(ycb02.CUP_NAMES) or set(cup_order) != set(
            ycb02.CUP_NAMES
        ):
            raise RuntimeError(f"YCB02 cup order is not a permutation: {cup_order!r}")
        if len(ball_order) != len(ycb02.BALL_NAMES) or set(ball_order) != set(
            ycb02.BALL_NAMES
        ):
            raise RuntimeError(
                f"YCB02 ball order is not a permutation: {ball_order!r}"
            )

        nominal_layout = {
            name: np.asarray([ycb02.CUP_ROW_X_M, slot_y], dtype=np.float64)
            for name, slot_y in zip(cup_order, ycb02.CUP_ROW_Y_M)
        }
        nominal_layout.update(
            {
                name: np.asarray(
                    [ycb02.BALL_ROW_X_M, slot_y], dtype=np.float64
                )
                for name, slot_y in zip(ball_order, ycb02.BALL_ROW_Y_M)
            }
        )

        # Screen against the complete live arm body cloud, not only palm and
        # finger origins.  The PhysX origin gate sees collisions from links
        # such as link5/link7; omitting those links here lets a layout pass the
        # static predicate and then forces a full reset when the scene settles.
        # Interface-only probes fall back to the corresponding live TCP pose,
        # so seeded randomness is preserved when Isaac articulations are not
        # present.
        hand_points = (
            *self._reset_robot_body_points("right"),
            *self._reset_robot_body_points("left"),
        )
        table_top_z = _TABLE_TOP_Z + float(self.delta_h[0])
        bounds = np.asarray(ycb02.RESET_XY_BOUNDS_M, dtype=np.float64)
        minimum_margin = float(ycb02.RESET_MIN_MARGIN_M)

        # The nominal rows are preferred when they are clear. Isaac's live
        # ROKAE FK differs enough from the MuJoCo authoring model that a fixed
        # slot can otherwise land beside a robot link.
        # Translate the complete row group rather than changing robot home or
        # silently dropping an object: the operator retains the clean visual
        # layout while every randomized body is screened against both live arm
        # body clouds before its reset pose is written.
        candidate_translations = [np.zeros(2, dtype=np.float64)]
        x_shift_bounds = np.asarray(
            ycb02.RESET_ROW_TRANSLATION_X_BOUNDS_M,
            dtype=np.float64,
        )
        y_shift_bounds = np.asarray(
            ycb02.RESET_ROW_TRANSLATION_Y_BOUNDS_M,
            dtype=np.float64,
        )
        if self.randomize:
            candidate_translations.extend(
                np.asarray(
                    [
                        self._random.uniform(*x_shift_bounds),
                        self._random.uniform(*y_shift_bounds),
                    ],
                    dtype=np.float64,
                )
                for _ in range(int(ycb02.RESET_ROW_RANDOM_ATTEMPTS))
            )
        grid_x_count, grid_y_count = ycb02.RESET_ROW_FALLBACK_GRID_SIZE
        candidate_translations.extend(
            np.asarray([x_shift, y_shift], dtype=np.float64)
            for x_shift in np.linspace(*x_shift_bounds, int(grid_x_count))
            for y_shift in np.linspace(*y_shift_bounds, int(grid_y_count))
        )

        layout: dict[str, np.ndarray] | None = None
        accepted_translation = np.zeros(2, dtype=np.float64)
        adaptive_rows = False
        staggered_rows = False
        best_margin = -math.inf
        attempts = 0
        for attempts, translation in enumerate(candidate_translations, start=1):
            candidate = {
                name: xy + translation for name, xy in nominal_layout.items()
            }
            margin = self._ycb02_layout_margin(
                candidate,
                set(all_names),
                hand_points,
                table_top_z,
                workspace_bounds=bounds,
            )
            if np.isfinite(margin):
                best_margin = max(best_margin, float(margin))
            if np.isfinite(margin) and margin >= minimum_margin:
                layout = candidate
                accepted_translation = translation.copy()
                break

        # A lateral hand home can occupy one slot in every legal translation
        # of the compact fixed rows.  In that case retain the two-row visual
        # grouping, but sample the row depths and sorted lateral slots
        # independently.  The same complete layout predicate still proves
        # support, visibility, reach, pair spacing, and clearance from every
        # live palm/finger body before any reset tensor is written.
        if layout is None and self.randomize:
            adaptive_attempt_offset = attempts
            cup_x_bounds = np.asarray(
                ycb02.RESET_ADAPTIVE_CUP_ROW_X_BOUNDS_M,
                dtype=np.float64,
            )
            ball_x_bounds = np.asarray(
                ycb02.RESET_ADAPTIVE_BALL_ROW_X_BOUNDS_M,
                dtype=np.float64,
            )
            row_y_bounds = np.asarray(
                ycb02.RESET_ADAPTIVE_ROW_Y_BOUNDS_M,
                dtype=np.float64,
            )
            for adaptive_attempt in range(
                1,
                int(ycb02.RESET_ADAPTIVE_ROW_ATTEMPTS) + 1,
            ):
                cup_x = float(self._random.uniform(*cup_x_bounds))
                ball_x = float(self._random.uniform(*ball_x_bounds))
                cup_slots_y = np.sort(
                    self._random.uniform(
                        *row_y_bounds,
                        size=len(ycb02.CUP_NAMES),
                    )
                )
                ball_slots_y = np.sort(
                    self._random.uniform(
                        *row_y_bounds,
                        size=len(ycb02.BALL_NAMES),
                    )
                )
                candidate = {
                    name: np.asarray([cup_x, slot_y], dtype=np.float64)
                    for name, slot_y in zip(cup_order, cup_slots_y)
                }
                candidate.update(
                    {
                        name: np.asarray([ball_x, slot_y], dtype=np.float64)
                        for name, slot_y in zip(ball_order, ball_slots_y)
                    }
                )
                margin = self._ycb02_layout_margin(
                    candidate,
                    set(all_names),
                    hand_points,
                    table_top_z,
                    workspace_bounds=bounds,
                )
                attempts = adaptive_attempt_offset + adaptive_attempt
                if np.isfinite(margin):
                    best_margin = max(best_margin, float(margin))
                if np.isfinite(margin) and margin >= minimum_margin:
                    layout = candidate
                    adaptive_rows = True
                    break

        # A live home may block every shared cup-row or ball-row depth. Give
        # each body an independent depth inside its visual row band while the
        # lateral slots stay ordered. This strictly expands the feasible set;
        # the full hand, support, camera, reach, and pair-clearance predicate
        # is still evaluated before any reset pose is accepted.
        if layout is None and self.randomize:
            staggered_attempt_offset = attempts
            cup_x_bounds = np.asarray(
                ycb02.RESET_ADAPTIVE_CUP_ROW_X_BOUNDS_M,
                dtype=np.float64,
            )
            ball_x_bounds = np.asarray(
                ycb02.RESET_ADAPTIVE_BALL_ROW_X_BOUNDS_M,
                dtype=np.float64,
            )
            row_y_bounds = np.asarray(
                ycb02.RESET_ADAPTIVE_ROW_Y_BOUNDS_M,
                dtype=np.float64,
            )
            for staggered_attempt in range(
                1,
                int(ycb02.RESET_STAGGERED_ROW_ATTEMPTS) + 1,
            ):
                cup_x = self._random.uniform(
                    *cup_x_bounds,
                    size=len(ycb02.CUP_NAMES),
                )
                ball_x = self._random.uniform(
                    *ball_x_bounds,
                    size=len(ycb02.BALL_NAMES),
                )
                cup_slots_y = np.sort(
                    self._random.uniform(
                        *row_y_bounds,
                        size=len(ycb02.CUP_NAMES),
                    )
                )
                ball_slots_y = np.sort(
                    self._random.uniform(
                        *row_y_bounds,
                        size=len(ycb02.BALL_NAMES),
                    )
                )
                candidate = {
                    name: np.asarray([slot_x, slot_y], dtype=np.float64)
                    for name, slot_x, slot_y in zip(
                        cup_order,
                        cup_x,
                        cup_slots_y,
                    )
                }
                candidate.update(
                    {
                        name: np.asarray([slot_x, slot_y], dtype=np.float64)
                        for name, slot_x, slot_y in zip(
                            ball_order,
                            ball_x,
                            ball_slots_y,
                        )
                    }
                )
                margin = self._ycb02_layout_margin(
                    candidate,
                    set(all_names),
                    hand_points,
                    table_top_z,
                    workspace_bounds=bounds,
                )
                attempts = staggered_attempt_offset + staggered_attempt
                if np.isfinite(margin):
                    best_margin = max(best_margin, float(margin))
                if np.isfinite(margin) and margin >= minimum_margin:
                    layout = candidate
                    staggered_rows = True
                    break

        if layout is None:
            raise RuntimeError(
                "YCB02 could not place the randomized objects away from both "
                "live robot arm body clouds while preserving the supported, visible, "
                f"reachable row layout (best_margin={best_margin:.6f}, "
                f"attempts={attempts}, cups={cup_order!r}, balls={ball_order!r})"
            )

        margin = self._ycb02_layout_margin(
            layout,
            set(all_names),
            hand_points,
            table_top_z,
            workspace_bounds=bounds,
        )

        self._ycb02_reset_xy = {
            name: layout[name].copy() for name in all_names
        }
        self._ycb02_reset_layout_diagnostics = {
            "margin_m": float(margin),
            "attempts": int(attempts),
            "object_count": len(all_names),
            "randomized": bool(self.randomize),
            "layout_kind": (
                "robot_clear_staggered_rows"
                if staggered_rows
                else (
                    "robot_clear_adaptive_rows"
                    if adaptive_rows
                    else "robot_clear_two_ordered_rows"
                )
            ),
            "translation_xy_m": (
                None
                if adaptive_rows or staggered_rows
                else accepted_translation.copy()
            ),
            "cup_order": cup_order,
            "ball_order": ball_order,
            "bounds_m": bounds.copy(),
        }
        layout_label = (
            "staggered"
            if staggered_rows
            else "adaptive" if adaptive_rows else "translated"
        )
        print(
            "[HandsOn/IsaacLab] YCB02 reset rows: "
            f"cups={','.join(cup_order)}, balls={','.join(ball_order)}, "
            f"layout={layout_label}, "
            f"shift={None if adaptive_rows or staggered_rows else accepted_translation.round(4).tolist()}, "
            f"margin={margin:.4f}m, attempts={attempts}",
            flush=True,
        )
        return {
            name: self._ycb02_reset_xy[name].copy() for name in all_names
        }

    def _ycb02_contact_force(self, subject: str, role: str) -> tuple[float, bool]:
        view = self._ycb02_contact_views.get((subject, role))
        available = bool(self._ycb02_contact_pairs_available and view is not None)
        return self._c04_contact_force(view), available

    def _ycb02_ball_local(self, ball_name: str) -> np.ndarray:
        cup_pose = self._poses.get(self._ycb02_active_cup_name, self._fallback_pose(self._ycb02_active_cup_name))
        ball_pose = self._poses.get(ball_name, self._fallback_pose(ball_name))
        return (_invert_pose_matrix(_pose_vector_to_matrix(cup_pose)) @ np.asarray([*ball_pose[:3], 1.0]))[:3]

    def _ycb02_hand_clearance(
        self,
        object_name: str,
        object_pose: np.ndarray,
    ) -> tuple[float, float, bool]:
        """Measure both complete hand envelopes against a placed object.

        YCB02 is exposed as a dual-arm task, so release must be evaluated from
        both wrists/finger clouds rather than the historical right-hand-only
        fallback used by A02.  This geometric check complements the physical
        ball/hand contact views: contact views cover the ball, while this
        envelope check also prevents a hand from still holding the cup when a
        placement is reported successful.
        """

        points = (
            *self._a06_hand_points("right"),
            *self._a06_hand_points("left"),
        )
        if object_name in ycb02.BALL_RADIUS_M:
            required = float(ycb02.BALL_RADIUS_M[object_name]) + 0.020
        else:
            # A cup is taller than its XY footprint.  Use the circumscribed
            # radius of its measured collision envelope plus a small margin,
            # matching the reset sampler's conservative no-penetration gate.
            footprint = self._ycb02_footprint_radius(object_name)
            half_height = max(
                abs(float(ycb02.CUP_SUPPORT_LOCAL_MIN_Z_M[object_name])),
                abs(float(ycb02.CUP_RIM_LOCAL_Z_M[object_name])),
            )
            required = math.hypot(footprint, half_height) + 0.020
        position = np.asarray(object_pose[:3], dtype=np.float64).reshape(3)
        distances = [
            float(np.linalg.norm(np.asarray(point, dtype=np.float64).reshape(3) - position))
            for point in points
            if np.all(np.isfinite(np.asarray(point, dtype=np.float64)))
        ]
        minimum = min(distances, default=math.inf)
        return minimum, float(required), bool(minimum >= required)

    def _ycb02_cup_tilt_deg(self) -> float:
        cup_pose = self._poses.get(self._ycb02_active_cup_name, self._fallback_pose(self._ycb02_active_cup_name))
        return float(np.rad2deg(np.arccos(np.clip(self._z_axis_alignment(cup_pose), -1.0, 1.0))))

    def _ycb02_ball_inside_metrics(self, ball_name: str) -> dict[str, Any]:
        cup_name = self._ycb02_active_cup_name
        local = self._ycb02_ball_local(ball_name)
        radial = float(np.linalg.norm(local[:2]))
        radial_limit = float(ycb02.settled_ball_radial_limit(cup_name, ball_name, float(local[2])))
        rim_z = float(ycb02.CUP_RIM_LOCAL_Z_M[cup_name])
        bottom_z = float(ycb02.CUP_SUPPORT_LOCAL_MIN_Z_M[cup_name] + ycb02.BALL_RADIUS_M[ball_name])
        geometric_inside = bool(radial_limit >= 0.0 and radial <= radial_limit and bottom_z - 0.005 <= float(local[2]) <= rim_z - ycb02.RIM_INTERIOR_DEPTH_M)
        cup_force, cup_available = self._ycb02_contact_force(ball_name, cup_name)
        table_force, table_available = self._ycb02_contact_force(ball_name, "table")
        contact_available = bool(cup_available and table_available)
        cup_contact_witness = bool(
            cup_force > ycb02.CONTACT_FORCE_EPSILON_N
        )
        table_support_excluded = bool(
            table_force <= ycb02.CONTACT_FORCE_EPSILON_N
        )
        # PhysX may stop publishing a non-zero force after a stable rigid body
        # goes to sleep.  Requiring a positive cup force on every one of the
        # final hold frames made a genuinely settled ball flicker out of the
        # cup classification.  A dynamic sphere geometrically contained below
        # the rim, with the direct table pair explicitly clear, can only remain
        # stable through cup support; the later velocity hold verifies that it
        # is not merely passing through the volume.
        support_confirmed = bool(
            contact_available
            and table_support_excluded
            and (cup_contact_witness or geometric_inside)
        )
        return {
            "local": local,
            "radial": radial,
            "radial_limit": radial_limit,
            "rim_z": rim_z,
            "geometric_inside": geometric_inside,
            "physically_supported": support_confirmed,
            "inside": bool(geometric_inside and support_confirmed),
            "cup_contact_force": float(cup_force),
            "table_contact_force": float(table_force),
            "cup_contact_witness": cup_contact_witness,
            "table_support_excluded": table_support_excluded,
            "contact_available": contact_available,
        }

    def _update_ycb02_event_state(self) -> None:
        if self.task_name != ycb02.TASK_NAME:
            return
        forces = {name: self._ycb02_contact_force(name, "hand")[0] for name in self._ycb02_candidate_order}
        touched = [name for name, force in forces.items() if force > ycb02.CONTACT_FORCE_EPSILON_N]
        if touched and self._ycb02_selected_ball_name is None:
            self._ycb02_selected_ball_name = max(touched, key=forces.__getitem__)
        if forces.get(self._ycb02_correct_ball_name, 0.0) > ycb02.CONTACT_FORCE_EPSILON_N:
            self._ycb02_correct_touched = True
        correct_pose = self._poses.get(self._ycb02_correct_ball_name)
        if correct_pose is None:
            return
        reset_z = self._ycb02_reset_ball_z.get(self._ycb02_correct_ball_name, float(correct_pose[2]))
        if self._ycb02_correct_touched and float(correct_pose[2]) >= reset_z + ycb02.MIN_LIFT_M:
            self._ycb02_correct_lifted = True
            self._ycb02_selected_ball_name = self._ycb02_correct_ball_name
        local = self._ycb02_ball_local(self._ycb02_correct_ball_name)
        rim_z = ycb02.CUP_RIM_LOCAL_Z_M[self._ycb02_active_cup_name]
        radial_limit = ycb02.ball_inside_radial_limit(self._ycb02_active_cup_name, self._ycb02_correct_ball_name)
        sampled_rim_crossing = bool(
            self._ycb02_previous_correct_local_z is not None
            and self._ycb02_previous_correct_local_z > rim_z
            and float(local[2]) <= rim_z
            and float(np.linalg.norm(local[:2])) <= radial_limit + 0.0005
        )
        correct_inside = bool(
            self._ycb02_ball_inside_metrics(
                self._ycb02_correct_ball_name
            )["inside"]
        )
        # At one control sample the tight-fitting ball can still be above the
        # rim and at the next already be supported against an inner wall.  Its
        # current off-centre settled position is then outside the rim-plane
        # radial test even though continuous CCD physics necessarily carried
        # it through the opening.  Treat supported interior occupancy after a
        # verified touch/lift as a second, physically stronger crossing proof.
        if self._ycb02_correct_lifted and (
            sampled_rim_crossing or correct_inside
        ):
            self._ycb02_rim_crossed = True
        self._ycb02_previous_correct_local_z = float(local[2])
        if self._ycb02_rim_crossed and correct_inside:
            self._ycb02_inside_latched = True

    def _ycb02_required_steps(self, seconds: float) -> int:
        return max(1, int(math.ceil(float(seconds) / max(float(self._control_dt), 1e-6))))

    def _ycb02_task_stage(self) -> int:
        if self._ycb02_stable_steps >= self._ycb02_required_steps(ycb02.SUCCESS_STABLE_SECONDS): return 5
        if self._ycb02_hand_clear_steps >= self._ycb02_required_steps(ycb02.HAND_CLEAR_SECONDS): return 4
        if self._ycb02_inside_latched: return 3
        if self._ycb02_rim_crossed: return 2
        if self._ycb02_correct_lifted: return 1
        return 0

    def _ycb02_metrics(self, *, update_timers: bool) -> dict[str, Any]:
        self._update_ycb02_event_state()
        cup_name = self._ycb02_active_cup_name
        cup_pose = self._poses.get(cup_name, self._fallback_pose(cup_name))
        cup_tilt = self._ycb02_cup_tilt_deg()
        cup_force, cup_table_available = self._ycb02_contact_force(cup_name, "table")
        cup_support_height_error = abs(
            float(cup_pose[2])
            - (
                self._current_table_top_z()
                - ycb02.CUP_SUPPORT_LOCAL_MIN_Z_M[cup_name]
            )
        )
        # As with an inserted ball, a sleeping cup can have a zero reported
        # pair force.  The measured support height plus the existing upright
        # and velocity gates is the persistent table-support witness.
        cup_supported = bool(
            cup_table_available
            and cup_support_height_error
            <= ycb02.CUP_TABLE_HEIGHT_TOLERANCE_M
        )
        cup_velocity = self._physics_body_velocity(cup_name)
        def _velocity_components(value: Any) -> np.ndarray | None:
            """Return a finite six-component velocity or ``None``.

            PhysX normally publishes ``(vx, vy, vz, wx, wy, wz)``.  Treat a
            missing, short, or non-finite fixture exactly like unavailable
            telemetry instead of accidentally classifying a three-vector as
            stable (``np.linalg.norm(arr[3:])`` is zero in that case).
            """

            if value is None:
                return None
            try:
                components = np.asarray(value, dtype=np.float64).reshape(-1)
            except (TypeError, ValueError):
                return None
            if components.size < 6 or not np.all(np.isfinite(components[:6])):
                return None
            return components[:6]

        cup_velocity_components = _velocity_components(cup_velocity)
        cup_stable = bool(
            cup_velocity_components is not None
            and float(np.linalg.norm(cup_velocity_components[:3]))
            <= ycb02.BALL_STABLE_LINEAR_SPEED_MPS
            and float(np.linalg.norm(cup_velocity_components[3:6]))
            <= ycb02.BALL_STABLE_ANGULAR_SPEED_RADPS
        )
        # All four physical balls are candidates in every episode.  Their
        # shuffled row order changes, but no visible ball is semantically
        # inactive or omitted from the capacity decision.
        all_ball_metrics = {
            name: self._ycb02_ball_inside_metrics(name)
            for name in ycb02.BALL_NAMES
        }
        ball_metrics = {
            name: all_ball_metrics[name] for name in self._ycb02_candidate_order
        }
        hand_forces = {
            name: self._ycb02_contact_force(name, "hand")[0]
            for name in ycb02.BALL_NAMES
        }
        ball_hand_clear = all(force <= ycb02.CONTACT_FORCE_EPSILON_N for force in hand_forces.values())
        cup_hand_min_distance, cup_hand_clearance_required, cup_hand_clear = self._ycb02_hand_clearance(cup_name, cup_pose)
        all_hand_clear = bool(ball_hand_clear and cup_hand_clear)
        correct = self._ycb02_correct_ball_name
        correct_inside = bool(ball_metrics[correct]["inside"])
        others_outside = all(not bool(ball_metrics[name]["inside"]) for name in self._ycb02_candidate_order if name != correct)
        velocities = {name: self._physics_body_velocity(name) for name in self._ycb02_candidate_order}
        stable_by_name = {
            name: (
                (components := _velocity_components(velocity)) is not None
                and float(np.linalg.norm(components[:3]))
                <= ycb02.BALL_STABLE_LINEAR_SPEED_MPS
                and float(np.linalg.norm(components[3:6]))
                <= ycb02.BALL_STABLE_ANGULAR_SPEED_RADPS
            )
            for name, velocity in velocities.items()
        }
        hand_clear_required = self._ycb02_required_steps(ycb02.HAND_CLEAR_SECONDS)
        stable_required = self._ycb02_required_steps(ycb02.SUCCESS_STABLE_SECONDS)
        smaller_inside_stable_names = tuple(
            name
            for name in self._ycb02_variant.smaller_fitting_balls
            if ball_metrics[name]["inside"]
            and stable_by_name[name]
            and all_hand_clear
        )
        smaller_inside_stable = bool(smaller_inside_stable_names)
        oversized_wedged_names = tuple(
            name
            for name in self._ycb02_variant.oversized_balls
            if (
                not ball_metrics[name]["inside"]
                and ball_metrics[name]["contact_available"]
                and ball_metrics[name]["cup_contact_force"]
                > ycb02.CONTACT_FORCE_EPSILON_N
                and all_hand_clear
                and stable_by_name[name]
                and float(np.linalg.norm(ball_metrics[name]["local"][:2]))
                <= ycb02.CUP_INNER_CENTER_RADIUS_M[cup_name]
                + ycb02.BALL_RADIUS_M[name]
                and ycb02.CUP_RIM_LOCAL_Z_M[cup_name]
                - ycb02.RIM_INTERIOR_DEPTH_M
                <= float(ball_metrics[name]["local"][2])
                <= ycb02.CUP_RIM_LOCAL_Z_M[cup_name]
                + ycb02.BALL_RADIUS_M[name]
                + 0.015
            )
        )
        oversized_wedged = bool(oversized_wedged_names)
        all_inside_names = tuple(
            name for name in ycb02.BALL_NAMES if all_ball_metrics[name]["inside"]
        )
        # A body can leave the support surface through the table's X/Y edge
        # while its Z coordinate remains high (for example, a cup carried
        # horizontally over the lip).  Treat that as the same recoverable
        # off-table condition monitored by the existing 0.20 s timer.  Check
        # every dynamic YCB body and fail
        # closed on malformed/non-finite physical poses without converting it
        # into an operator-caused failure.
        table_top_z = float(self._current_table_top_z())
        table_bounds = np.asarray(
            [
                ycb02.TABLE_X_BOUNDS_M,
                ycb02.TABLE_Y_BOUNDS_M,
            ],
            dtype=np.float64,
        )
        invalid_pose_now = (
            table_bounds.shape != (2, 2)
            or not np.all(np.isfinite(table_bounds))
            or np.any(table_bounds[:, 0] >= table_bounds[:, 1])
            or not np.isfinite(table_top_z)
        )
        off_table_now = False
        if not invalid_pose_now:
            for name in (*ycb02.CUP_NAMES, *ycb02.BALL_NAMES):
                pose = np.asarray(
                    self._poses.get(name, self._fallback_pose(name)),
                    dtype=np.float64,
                ).reshape(-1)
                if pose.size < 7 or not np.all(np.isfinite(pose[:7])):
                    invalid_pose_now = True
                    continue
                quaternion_norm = float(np.linalg.norm(pose[3:7]))
                if not np.isfinite(quaternion_norm) or quaternion_norm < 1.0e-6:
                    invalid_pose_now = True
                    continue
                radius = float(self._ycb02_footprint_radius(name))
                if not np.isfinite(radius) or radius <= 0.0:
                    invalid_pose_now = True
                    continue
                x, y, z = (float(value) for value in pose[:3])
                if (
                    x < table_bounds[0, 0] + radius
                    or x > table_bounds[0, 1] - radius
                    or y < table_bounds[1, 0] + radius
                    or y > table_bounds[1, 1] - radius
                    or z < table_top_z - ycb02.OFF_TABLE_Z_MARGIN_M
                ):
                    off_table_now = True
        if invalid_pose_now and not self._ycb02_invalid_reason:
            self._ycb02_invalid_reason = "invalid_physics"
        toppled_now = cup_tilt > ycb02.CUP_TOPPLED_TILT_DEG
        if update_timers:
            base_ready = bool(not self._ycb02_invalid_reason and self._ycb02_correct_lifted and self._ycb02_rim_crossed and self._ycb02_inside_latched and correct_inside and others_outside and cup_tilt <= ycb02.CUP_SUCCESS_TILT_DEG and cup_supported)
            self._ycb02_hand_clear_steps = self._ycb02_hand_clear_steps + 1 if base_ready and all_hand_clear else 0
            stable_now = bool(self._ycb02_hand_clear_steps >= hand_clear_required and correct_inside and stable_by_name[correct] and cup_stable and cup_hand_clear and cup_tilt <= ycb02.CUP_SUCCESS_TILT_DEG and cup_supported and others_outside)
            self._ycb02_stable_steps = self._ycb02_stable_steps + 1 if stable_now else 0
            self._ycb02_wrong_stable_steps = self._ycb02_wrong_stable_steps + 1 if smaller_inside_stable else 0
            self._ycb02_oversized_wedged_steps = self._ycb02_oversized_wedged_steps + 1 if oversized_wedged else 0
            self._ycb02_off_table_steps = self._ycb02_off_table_steps + 1 if off_table_now else 0
            self._ycb02_toppled_steps = self._ycb02_toppled_steps + 1 if toppled_now else 0
        metrics = {
            "ycb02_success_now": bool(self._ycb02_stable_steps >= stable_required and not self._ycb02_invalid_reason),
            "ycb02_correct_lifted": bool(self._ycb02_correct_lifted),
            "ycb02_rim_crossed": bool(self._ycb02_rim_crossed),
            "ycb02_inside_supported": correct_inside,
            "ycb02_other_balls_outside": others_outside,
            "ycb02_hand_clear": bool(self._ycb02_hand_clear_steps >= hand_clear_required),
            "ycb02_ball_hand_clear": bool(ball_hand_clear),
            "ycb02_cup_hand_clear": bool(cup_hand_clear),
            "ycb02_cup_hand_min_distance": float(cup_hand_min_distance),
            "ycb02_cup_hand_clearance_required": float(cup_hand_clearance_required),
            "ycb02_ball_stable": bool(self._ycb02_stable_steps >= stable_required),
            "ycb02_cup_stable": bool(cup_stable),
            "ycb02_cup_linear_speed_mps": float(
                np.linalg.norm(cup_velocity_components[:3])
                if cup_velocity_components is not None
                else math.inf
            ),
            "ycb02_cup_angular_speed_radps": float(
                np.linalg.norm(cup_velocity_components[3:6])
                if cup_velocity_components is not None
                else math.inf
            ),
            "ycb02_cup_upright_supported": bool(cup_tilt <= ycb02.CUP_SUCCESS_TILT_DEG and cup_supported),
            "ycb02_inside_names": tuple(
                name
                for name in self._ycb02_candidate_order
                if ball_metrics[name]["inside"]
            ),
            "ycb02_all_inside_names": all_inside_names,
            "ycb02_hand_contact_forces": hand_forces,
            "ycb02_contact_pairs_available": bool(self._ycb02_contact_pairs_available),
            "ycb02_cup_table_contact_force": float(cup_force),
            "ycb02_cup_table_contact_witness": bool(
                cup_force > ycb02.CONTACT_FORCE_EPSILON_N
            ),
            "ycb02_cup_support_height_error_m": float(
                cup_support_height_error
            ),
            "ycb02_cup_tilt_deg": float(cup_tilt),
            "ycb02_ball_metrics": ball_metrics,
            "ycb02_ball_stable_by_name": stable_by_name,
            "ycb02_hand_clear_steps": int(self._ycb02_hand_clear_steps),
            "ycb02_hand_clear_steps_required": int(hand_clear_required),
            "ycb02_stable_steps": int(self._ycb02_stable_steps),
            "ycb02_stable_steps_required": int(stable_required),
            "ycb02_wrong_stable_steps": int(self._ycb02_wrong_stable_steps),
            "ycb02_oversized_wedged_steps": int(self._ycb02_oversized_wedged_steps),
            "ycb02_off_table_steps": int(self._ycb02_off_table_steps),
            "ycb02_toppled_steps": int(self._ycb02_toppled_steps),
            "ycb02_multiple_balls_inside": len(all_inside_names) >= 2,
            "ycb02_no_multiple_inside": len(all_inside_names) < 2,
            "ycb02_smaller_inside_stable": smaller_inside_stable,
            "ycb02_smaller_inside_stable_names": smaller_inside_stable_names,
            "ycb02_oversized_wedged": oversized_wedged,
            "ycb02_oversized_wedged_names": oversized_wedged_names,
            "ycb02_off_table_now": off_table_now,
            "ycb02_cup_toppled_now": toppled_now,
            "ycb02_invalid_reason": self._ycb02_invalid_reason,
            "ycb02_task_stage": self._ycb02_task_stage(),
        }
        self._last_ycb02_metrics = metrics
        return metrics

    def _ycb02_success_now(self) -> bool:
        success_now = bool(self._ycb02_metrics(update_timers=True)["ycb02_success_now"])
        self._ycb02_success_metrics_pending_for_failure = True
        if success_now and not self._ycb02_terminal_reason:
            self._ycb02_terminal_reason = "success"
        return success_now

    def _reset_ycb02_episode_state(self) -> None:
        if self.task_name != ycb02.TASK_NAME:
            return
        variant_index = (
            int(self._random.choice(len(ycb02.VARIANTS)))
            if self.randomize
            else 0
        )
        variant = ycb02.VARIANTS[variant_index]
        cup_order = tuple(
            str(name)
            for name in (
                self._random.permutation(ycb02.CUP_NAMES)
                if self.randomize
                else ycb02.CUP_NAMES
            )
        )
        candidate_order = tuple(
            str(name)
            for name in (
                self._random.permutation(ycb02.BALL_NAMES)
                if self.randomize
                else ycb02.BALL_NAMES
            )
        )
        self._ycb02_variant_index = variant_index
        self._ycb02_variant = variant
        self._ycb02_active_cup_name = variant.cup
        self._ycb02_cup_order = cup_order
        self._ycb02_candidate_order = candidate_order
        self._ycb02_correct_ball_name = variant.correct_ball
        self._ycb02_fit_mask = ycb02.permuted_fit_mask(
            variant,
            candidate_order,
        )
        self._target_object_name = candidate_order[0]
        self._ycb02_reset_ordinal += 1
        self._ycb02_reset_xy = {}
        self._ycb02_reset_layout_diagnostics = {}
        self._ycb02_recorded_layout_restored = False
        table_top = _TABLE_TOP_Z + float(self.delta_h[0])
        self._ycb02_reset_ball_z = {
            name: table_top + ycb02.BALL_RADIUS_M[name]
            for name in ycb02.BALL_NAMES
        }
        self._ycb02_selected_ball_name = None
        self._ycb02_correct_touched = False
        self._ycb02_correct_lifted = False
        self._ycb02_rim_crossed = False
        self._ycb02_inside_latched = False
        self._ycb02_previous_correct_local_z = None
        self._ycb02_hand_clear_steps = 0
        self._ycb02_stable_steps = 0
        self._ycb02_wrong_stable_steps = 0
        self._ycb02_oversized_wedged_steps = 0
        self._ycb02_off_table_steps = 0
        self._ycb02_toppled_steps = 0
        self._ycb02_terminal_reason = ""
        self._ycb02_invalid_reason = ""
        self._last_ycb02_metrics = {}
        self._ycb02_success_metrics_pending_for_failure = False

    @staticmethod
    def _validate_ycb02_recorded_pose_rows(
        value: Any,
        *,
        key: str,
        expected_count: int | None = None,
        allow_empty: bool = False,
    ) -> np.ndarray:
        """Validate and normalize one YCB02 recording pose array.

        Public state slices are flattened by ``HandsOnObsAdapter`` while the
        recording-only fields retain their ``(N, 7)`` frame shape.  Accept both
        representations here, but reject malformed/non-finite rows before any
        PhysX write.  Normalizing the quaternion keeps old recordings with
        small norm drift replay-compatible while still rejecting zero/NaN
        orientations.
        """

        try:
            array = np.asarray(value, dtype=np.float64)
        except (TypeError, ValueError, OverflowError) as exc:
            raise ValueError(
                f"YCB02 recorded {key!r} cannot be converted to float64"
            ) from exc
        if array.size == 0:
            if allow_empty:
                return np.zeros((0, 7), dtype=np.float64)
            raise ValueError(f"YCB02 recorded {key!r} must not be empty")
        if array.ndim == 1:
            if array.size % 7:
                raise ValueError(
                    f"YCB02 recorded {key!r} must contain rows of seven values; "
                    f"got shape {array.shape}"
                )
            array = array.reshape(-1, 7).copy()
        elif array.ndim == 2 and array.shape[1] == 7:
            array = array.copy()
        else:
            raise ValueError(
                f"YCB02 recorded {key!r} must have shape (N, 7) or a flattened "
                f"multiple of seven; got {array.shape}"
            )
        if expected_count is not None and array.shape[0] != expected_count:
            raise ValueError(
                f"YCB02 recorded {key!r} must contain exactly {expected_count} "
                f"poses, got {array.shape[0]}"
            )
        if not np.all(np.isfinite(array)):
            raise ValueError(f"YCB02 recorded {key!r} must be finite")
        quaternion_norms = np.linalg.norm(array[:, 3:7], axis=1)
        if np.any(
            ~np.isfinite(quaternion_norms) | (quaternion_norms <= 1.0e-8)
        ):
            invalid = np.flatnonzero(
                ~np.isfinite(quaternion_norms) | (quaternion_norms <= 1.0e-8)
            ).tolist()
            raise ValueError(
                f"YCB02 recorded {key!r} contains zero/non-finite quaternions "
                f"at indices {invalid}"
            )
        array[:, 3:7] /= quaternion_norms[:, None]
        return np.ascontiguousarray(array)

    def _restore_ycb02_recorded_episode_state(
        self,
        state_parts: Mapping[str, np.ndarray],
    ) -> bool:
        """Restore YCB02 identity and event state from a recorded frame.

        The public policy state intentionally contains no oracle target.  The
        recorder nevertheless stores the variant/candidate permutation in the
        recording-only ``ycb02_hidden_state`` field so a fresh replay process
        can evaluate the same physical episode.  Older recordings may not
        contain that field; in that case the public cup/candidate IDs are a
        sufficient, non-oracular fallback for reconstructing the variant.

        Return ``True`` when an identity was restored and ``False`` when the
        input is an older frame with neither identity representation.  A
        malformed identity is rejected rather than silently evaluating a
        replay against a different cup or ball.
        """

        # Invalid physics is an episode-level diagnostic.  Keep it sticky
        # while a replay feeds subsequent frames (the source recorder may
        # encode code 8 on only the first invalid frame); a fresh environment
        # reset clears it in ``_reset_ycb02_episode_state``.
        prior_invalid_reason = str(
            getattr(self, "_ycb02_invalid_reason", "") or ""
        )

        def exact_int(
            value: Any,
            label: str,
            lower: int,
            upper: int,
        ) -> int:
            try:
                numeric = float(value)
            except (TypeError, ValueError) as exc:
                raise ValueError(
                    f"YCB02 recorded {label} must be an integer"
                ) from exc
            if not np.isfinite(numeric) or abs(numeric - round(numeric)) > 1e-6:
                raise ValueError(
                    f"YCB02 recorded {label} must be a finite integer, "
                    f"got {value!r}"
                )
            result = int(round(numeric))
            if result < lower or result > upper:
                raise ValueError(
                    f"YCB02 recorded {label}={result} is outside "
                    f"[{lower}, {upper}]"
                )
            return result

        def exact_binary(value: Any, label: str) -> bool:
            """Decode a recorded event latch without truthiness coercion.

            Hidden state is a numeric recording format, so values such as
            ``0.25`` or ``nan`` must not silently become ``True``.  A tiny
            tolerance keeps JSON/Zarr float round-trips compatible while
            still rejecting non-binary event data.
            """

            try:
                numeric = float(value)
            except (TypeError, ValueError) as exc:
                raise ValueError(
                    f"YCB02 recorded {label} must be binary"
                ) from exc
            if not np.isfinite(numeric):
                raise ValueError(
                    f"YCB02 recorded {label} must be finite, got {value!r}"
                )
            rounded = round(numeric)
            if rounded not in (0, 1) or abs(numeric - rounded) > 1e-6:
                raise ValueError(
                    f"YCB02 recorded {label} must be 0 or 1, got {value!r}"
                )
            return bool(rounded)

        def exact_nonnegative_int(value: Any, label: str) -> int:
            """Decode a finite integral timer/counter with no clamping."""

            try:
                numeric = float(value)
            except (TypeError, ValueError) as exc:
                raise ValueError(
                    f"YCB02 recorded {label} must be a non-negative integer"
                ) from exc
            if (
                not np.isfinite(numeric)
                or numeric < 0.0
                or abs(numeric - round(numeric)) > 1e-6
            ):
                raise ValueError(
                    f"YCB02 recorded {label} must be a finite non-negative "
                    f"integer, got {value!r}"
                )
            return int(round(numeric))

        hidden = np.asarray(
            state_parts.get("ycb02_hidden_state", np.zeros(0)),
            dtype=np.float64,
        ).ravel()
        hidden_present = "ycb02_hidden_state" in state_parts
        candidate_count = len(ycb02.BALL_NAMES)
        identity_size = 2 + 2 * candidate_count
        complete_size = identity_size + 12
        # Current recordings use a capacity-derived identity prefix or the
        # full identity+event vector. Treat an intermediate suffix as
        # corruption instead of silently dropping half of the event state.
        if (
            hidden_present
            and hidden.size not in (0, identity_size)
            and hidden.size < complete_size
        ):
            raise ValueError(
                "YCB02 recorded hidden state must contain "
                f"{identity_size} or at least {complete_size} "
                f"values, got {hidden.size}"
            )
        variant: ycb02.YCB02Variant | None = None
        variant_index: int | None = None
        candidate_order: tuple[str, ...] | None = None
        candidate_ids: tuple[int, ...] | None = None

        # Public IDs are not oracle information, and they provide an
        # independent integrity check for the recording-only hidden identity.
        # Older shortened flat states may contain only one of these fields;
        # retain the legacy fallback in that case, but never use a partial pair
        # as if it were authoritative.
        public_identity: tuple[int, tuple[int, ...]] | None = None
        public_identity_fields_present = (
            "active_cup_id" in state_parts
            or "candidate_ball_ids" in state_parts
        )
        public_cup_ids = np.asarray(
            state_parts.get("active_cup_id", np.zeros(0)),
            dtype=np.float64,
        ).ravel()
        public_candidate_ids = np.asarray(
            state_parts.get("candidate_ball_ids", np.zeros(0)),
            dtype=np.float64,
        ).ravel()
        if (
            public_cup_ids.size >= 1
            and public_candidate_ids.size >= candidate_count
        ):
            if (
                public_cup_ids.size != 1
                or public_candidate_ids.size != candidate_count
            ):
                raise ValueError(
                    "YCB02 recorded public identity fields have unexpected "
                    f"shapes: active_cup_id={public_cup_ids.size}, "
                    f"candidate_ball_ids={public_candidate_ids.size}"
                )
            public_cup_id = exact_int(
                public_cup_ids[0],
                "active cup ID",
                0,
                len(ycb02.CUP_NAMES) - 1,
            )
            public_candidate_tuple = tuple(
                exact_int(
                    value,
                    f"public candidate ID {index}",
                    0,
                    len(ycb02.BALL_NAMES) - 1,
                )
                for index, value in enumerate(public_candidate_ids)
            )
            public_identity = (public_cup_id, public_candidate_tuple)
        elif public_identity_fields_present and hidden.size >= identity_size:
            self._add_task_state_warning(
                "YCB02 recorded public identity is incomplete; validating "
                "against hidden identity only"
            )

        # The identity block stores the variant index, correct-ball ID, one
        # fit flag per candidate, and the complete shuffled candidate order.
        # Validate all of it before changing any live task
        # state so a corrupt frame cannot leave a partially restored episode.
        if hidden.size >= identity_size:
            if not np.all(np.isfinite(hidden[:identity_size])):
                raise ValueError("YCB02 recorded identity block is non-finite")
            variant_index = exact_int(
                hidden[0],
                "variant index",
                0,
                len(ycb02.VARIANTS) - 1,
            )
            variant = ycb02.VARIANTS[variant_index]
            correct_id = exact_int(
                hidden[1],
                "correct ball ID",
                0,
                len(ycb02.BALL_NAMES) - 1,
            )
            expected_correct_id = ycb02.BALL_IDS[variant.correct_ball]
            if correct_id != expected_correct_id:
                raise ValueError(
                    "YCB02 recorded correct-ball ID disagrees with its "
                    f"variant ({correct_id} != {expected_correct_id})"
                )
            candidate_ids = tuple(
                exact_int(
                    value,
                    f"candidate ID {index}",
                    0,
                    len(ycb02.BALL_NAMES) - 1,
                )
                for index, value in enumerate(
                    hidden[2 + candidate_count : identity_size]
                )
            )
            expected_ids = {ycb02.BALL_IDS[name] for name in ycb02.BALL_NAMES}
            if (
                len(set(candidate_ids)) != candidate_count
                or set(candidate_ids) != expected_ids
            ):
                raise ValueError(
                    "YCB02 recorded candidate IDs do not match the selected "
                    f"variant: ids={candidate_ids!r}, expected={sorted(expected_ids)!r}"
                )
            recorded_fit = tuple(
                exact_binary(value, f"fit mask {index}")
                for index, value in enumerate(hidden[2 : 2 + candidate_count])
            )
            candidate_order = tuple(
                ycb02.BALL_NAMES[ball_id] for ball_id in candidate_ids
            )
            expected_fit = ycb02.permuted_fit_mask(variant, candidate_order)
            if recorded_fit != expected_fit:
                raise ValueError(
                    "YCB02 recorded fit mask disagrees with candidate order: "
                    f"mask={recorded_fit!r}, expected={expected_fit!r}"
                )
            if public_identity is not None:
                public_cup_id, public_candidate_tuple = public_identity
                expected_cup_id = ycb02.CUP_IDS[variant.cup]
                if public_cup_id != expected_cup_id:
                    raise ValueError(
                        "YCB02 recorded active cup ID disagrees with hidden "
                        f"variant ({public_cup_id} != {expected_cup_id})"
                    )
                if public_candidate_tuple != candidate_ids:
                    raise ValueError(
                        "YCB02 recorded candidate IDs disagree between public "
                        f"and hidden state ({public_candidate_tuple!r} != "
                        f"{candidate_ids!r})"
                    )
        else:
            # Compatibility path for pre-hidden-state recordings.  These IDs
            # are already public observation fields and identify only the
            # authored variant/candidate set, never the oracle answer.
            if public_identity is not None:
                cup_id, candidate_ids = public_identity
                variant_index = next(
                    (
                        index
                        for index, authored_variant in enumerate(ycb02.VARIANTS)
                        if ycb02.CUP_IDS[authored_variant.cup] == cup_id
                    ),
                    None,
                )
                if variant_index is None:
                    raise ValueError(
                        f"YCB02 recorded active cup ID {cup_id} has no variant"
                    )
                variant = ycb02.VARIANTS[variant_index]
                expected_ids = {
                    ycb02.BALL_IDS[name] for name in ycb02.BALL_NAMES
                }
                if (
                    len(set(candidate_ids)) != candidate_count
                    or set(candidate_ids) != expected_ids
                ):
                    raise ValueError(
                        "YCB02 public candidate IDs do not match active cup "
                        f"{cup_id}: ids={candidate_ids!r}"
                    )
                candidate_order = tuple(
                    ycb02.BALL_NAMES[ball_id] for ball_id in candidate_ids
                )
            else:
                self._add_task_state_warning(
                    "YCB02 recorded frame has no identity block; retaining the "
                    "fresh reset variant for legacy compatibility"
                )
                return False

        assert variant is not None
        assert variant_index is not None
        assert candidate_order is not None

        # Validate the complete event suffix before mutating any live state.
        # This keeps a malformed replay frame transactional: identity fields
        # cannot be left half-restored when a timer or terminal code is bad.
        event_state: dict[str, Any] | None = None
        if hidden.size >= complete_size:
            event_offset = identity_size
            event_state = {
                "correct_touched": exact_binary(
                    hidden[event_offset], "correct_touched"
                ),
                "correct_lifted": exact_binary(
                    hidden[event_offset + 1], "correct_lifted"
                ),
                "rim_crossed": exact_binary(
                    hidden[event_offset + 2], "rim_crossed"
                ),
                "inside_latched": exact_binary(
                    hidden[event_offset + 3], "inside_latched"
                ),
                "hand_clear_steps": exact_nonnegative_int(
                    hidden[event_offset + 4], "hand_clear_steps"
                ),
                "stable_steps": exact_nonnegative_int(
                    hidden[event_offset + 5], "stable_steps"
                ),
                "wrong_stable_steps": exact_nonnegative_int(
                    hidden[event_offset + 6], "wrong_stable_steps"
                ),
                "oversized_wedged_steps": exact_nonnegative_int(
                    hidden[event_offset + 7], "oversized_wedged_steps"
                ),
                "off_table_steps": exact_nonnegative_int(
                    hidden[event_offset + 8], "off_table_steps"
                ),
                "toppled_steps": exact_nonnegative_int(
                    hidden[event_offset + 9], "toppled_steps"
                ),
            }
            selected_id = exact_int(
                hidden[event_offset + 10],
                "selected ball ID",
                -1,
                len(ycb02.BALL_NAMES) - 1,
            )
            if selected_id >= 0 and selected_id not in candidate_ids:
                raise ValueError(
                    "YCB02 recorded selected ball ID is not one of the "
                    f"candidate IDs ({selected_id} not in {candidate_ids!r})"
                )
            terminal_code = exact_int(
                hidden[event_offset + 11],
                "terminal reason code",
                0,
                8,
            )
            terminal_reason = {
                0: "",
                1: "success",
                2: "wrong_ball_placed",
                3: "oversized_ball_wedged",
                4: "multiple_balls_inside",
                5: "object_off_table",
                6: "cup_toppled",
                7: "timeout",
            }.get(terminal_code, "")
            event_state.update(
                {
                    "selected_id": selected_id,
                    "terminal_reason": terminal_reason,
                    # Code 8 is emitted when the source has no recognised
                    # terminal reason (typically NaN/severe penetration).  It
                    # marks the episode invalid, not an operator failure.
                    "invalid_reason": (
                        "invalid_physics" if terminal_code == 8 else ""
                    ),
                }
            )
            if event_state["correct_lifted"] and not event_state["correct_touched"]:
                raise ValueError(
                    "YCB02 recorded event state has correct_lifted without "
                    "correct_touched"
                )
            if event_state["rim_crossed"] and not event_state["correct_lifted"]:
                raise ValueError(
                    "YCB02 recorded event state has rim_crossed without "
                    "correct_lifted"
                )
            if event_state["inside_latched"] and not event_state["rim_crossed"]:
                raise ValueError(
                    "YCB02 recorded event state has inside_latched without "
                    "rim_crossed"
                )

        self._ycb02_variant_index = int(variant_index)
        self._ycb02_variant = variant
        self._ycb02_active_cup_name = variant.cup
        self._ycb02_candidate_order = candidate_order
        self._ycb02_correct_ball_name = variant.correct_ball
        self._ycb02_fit_mask = ycb02.permuted_fit_mask(
            variant,
            candidate_order,
        )
        # The legacy role aliases use ``_target_object_name``.  Keep it tied
        # to the recorded candidate order, never to the hidden correct ball.
        self._target_object_name = candidate_order[0]

        # The reset baseline is needed by the lift gate during a replay that
        # starts before the first lift.  Recompute it after restoring the
        # recorded table height (the caller applies delta_h first).
        table_top = self._current_table_top_z()
        self._ycb02_reset_ball_z = {
            name: table_top + ycb02.BALL_RADIUS_M[name]
            for name in ycb02.BALL_NAMES
        }

        # Restore the event/timer suffix when the complete current-format
        # hidden vector is present.  Identity restoration above intentionally
        # works with the shorter compatibility block as well.
        if event_state is not None:
            self._ycb02_correct_touched = bool(
                event_state["correct_touched"]
            )
            self._ycb02_correct_lifted = bool(
                event_state["correct_lifted"]
            )
            self._ycb02_rim_crossed = bool(event_state["rim_crossed"])
            self._ycb02_inside_latched = bool(event_state["inside_latched"])
            self._ycb02_hand_clear_steps = int(event_state["hand_clear_steps"])
            self._ycb02_stable_steps = int(event_state["stable_steps"])
            self._ycb02_wrong_stable_steps = int(
                event_state["wrong_stable_steps"]
            )
            self._ycb02_oversized_wedged_steps = int(
                event_state["oversized_wedged_steps"]
            )
            self._ycb02_off_table_steps = int(event_state["off_table_steps"])
            self._ycb02_toppled_steps = int(event_state["toppled_steps"])
            selected_id = int(event_state["selected_id"])
            self._ycb02_selected_ball_name = (
                None if selected_id < 0 else ycb02.BALL_NAMES[selected_id]
            )
            self._ycb02_terminal_reason = str(event_state["terminal_reason"])
            self._ycb02_invalid_reason = (
                prior_invalid_reason
                or str(event_state["invalid_reason"])
            )
        return True


    def _reset_ycb09_episode_state(self) -> None:
        if self.task_name != ycb09.TASK_NAME:
            return
        self._ycb09_reset_ordinal += 1
        self._ycb09_capture_reset_pending = False
        self._ycb09_glass_reset_pose = None
        self._ycb09_plate_reset_pose = None
        self._ycb09_carry_start_position = None
        self._ycb09_lift_hold_steps = 0
        self._ycb09_lifted = False
        self._ycb09_transported = False
        self._ycb09_hand_clear_steps = 0
        self._ycb09_stability_steps = 0
        self._ycb09_glass_off_table_steps = 0
        self._ycb09_plate_off_table_steps = 0
        self._ycb09_terminal_reason = ""
        self._ycb09_invalid_reason = ""
        self._last_ycb09_metrics = {}

    def _sample_reset_state(self, *, clear_manual_request: bool) -> None:
        if self.task_name == xy3.TASK_NAME:
            self._target_object_name = self._xy3_fixed_target or str(self._random.choice(xy3.FRUIT_NAMES))
        table_height_bounds = _TASK_TABLE_HEIGHT_BOUNDS.get(
            self.task_name,
            (0.0, 0.05),
        )
        self.delta_h = np.asarray(
            [self._random.uniform(*table_height_bounds) if self.randomize else 0.0],
            dtype=np.float64,
        )

        if self.task_name == YCB05_TASK_NAME:
            self._ycb05_sampled_reset_poses = sample_ycb05_layout(
                self._random,
                randomize=self.randomize,
                table_top_z=_TABLE_TOP_Z + float(self.delta_h[0]),
            )
        self._right_tcp_pose = _RIGHT_HOME.copy()
        self._left_tcp_pose = _LEFT_HOME.copy()
        if self.task_name == "eval_gen02_open_trash_bin":
            self._right_tcp_pose = _BC021_TABLETOP_RIGHT_START_TCP.copy()
            self._left_tcp_pose = _RAISED_LEFT_START_TCP.copy()
        elif self.task_name == xy5.TASK_NAME:
            self._right_tcp_pose = _YCB01_CLEAR_RIGHT_START_TCP.copy()
            self._left_tcp_pose = _RAISED_LEFT_START_TCP.copy()
        elif self.task_name == "t18_open_micropipette_box":
            self._right_tcp_pose = _C_TOOL_SPREAD_RIGHT_START_TCP.copy()
            self._left_tcp_pose = _C_TOOL_SPREAD_LEFT_START_TCP.copy()
        elif self.task_name in _SHARED_MIRRORED_HOME_TASKS:
            pass
        elif self.task_name == ycb09.TASK_NAME:
            self._right_tcp_pose = _YCB09_RIGHT_START_TCP.copy()
            self._left_tcp_pose = _YCB09_LEFT_START_TCP.copy()
        elif self.task_name == gen1.TASK_NAME:
            self._right_tcp_pose = _GEN1_CLEAR_RIGHT_START_TCP.copy()
            self._left_tcp_pose = _GEN1_CLEAR_LEFT_START_TCP.copy()
