    def _append_success_hold_row(
        self,
        rows: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        required_steps = self._success_steps_required()
        if required_steps > 1:
            hold_label = f"All conditions held for {required_steps} frames"
            hold_key = "success_hold"
            if self.task_name == "c07_pitcher_pour_cup":
                hold_label = "放稳并脱手连续保持 0.5 秒"
                hold_key = "c07_release_hold"
            elif self.task_name == "t09_insert_peg":
                hold_label = "插入且插销/插座稳定连续保持 0.5 秒"
                hold_key = "b03_stable_hold"
            elif self.task_name == "t24_place_ball_in_bowl":
                hold_label = "球和碗放稳且脱手连续保持 0.5 秒"
                hold_key = "a03_release_stable_hold"
            elif self.task_name == "t03_cover_box":
                hold_label = "盒盖/透明盒放稳且脱手连续保持 0.5 秒"
                hold_key = "b05_release_stable_hold"
            elif self.task_name == gen5.TASK_NAME:
                hold_label = "Package stack remains stable for 0.5 seconds"
                hold_key = "gen5_release_stable_hold"
            rows.append(
                self._condition_row(
                    hold_key,
                    hold_label,
                    self._success_counter >= required_steps,
                )
            )
        return rows

