    def _core_box_success_condition_rows(self) -> list[dict[str, Any]]:
        lid = self._pose_for_role("target")
        base = self._pose_for_role("receptacle")
        local, _target, _receptacle = self._target_local_to_receptacle()
        z_error = float(local[2] - _LID_GOAL_LOCAL_Z[self.task_name])
        top_aligned = self._z_axis_alignment(lid, base) >= float(np.cos(np.deg2rad(20.0)))
        yaw_aligned = self._x_axis_abs_alignment(lid, base) >= float(np.cos(np.deg2rad(25.0)))
        moved = bool(self._lid_was_moved)
        if self._lid_start_pose is not None:
            moved = moved or float(np.linalg.norm(lid[:3] - self._lid_start_pose[:3])) >= _LID_MIN_MOVE_DISTANCE
        velocity = self._physics_body_velocity(self._target_object_name)
        stable = velocity is None or (
            float(np.linalg.norm(velocity[:3])) <= _LID_STABLE_LINEAR_SPEED
            and float(np.linalg.norm(velocity[3:])) <= _LID_STABLE_ANGULAR_SPEED
        )
        return [
            self._condition_row("b05_centered", "盒盖中心对准盒口", float(np.linalg.norm(local[:2])) <= 0.055),
            self._condition_row("b05_height", "盒盖高度接近盖好位置", -0.020 <= z_error <= 0.025),
            self._condition_row("b05_top_aligned", "盒盖基本放平", top_aligned),
            self._condition_row("b05_yaw_aligned", "盒盖方向和盒子对齐", yaw_aligned),
            self._condition_row("b05_moved", "盒盖已被移动到盒子上", moved),
            self._condition_row("b05_stable", "盒盖已经稳定不滑动", stable),
        ]

    @staticmethod
    def _b05_full_coverage_metrics(
        lid_pose: np.ndarray,
        base_pose: np.ndarray,
    ) -> dict[str, Any]:
        """Measure oriented lid/box overlap and require more than 90%."""

        lid = _pose_vector_to_matrix(
            np.asarray(lid_pose, dtype=np.float64).reshape(7)
        )
        base = _pose_vector_to_matrix(
            np.asarray(base_pose, dtype=np.float64).reshape(7)
        )
        base_half = _B05_FOOTPRINT_HALF_EXTENTS["Clear_Box"]
        lid_half = _B05_FOOTPRINT_HALF_EXTENTS["Box_lid"]
        corners_local = np.asarray(
            [
                [-base_half[0], -base_half[1], 0.0, 1.0],
                [base_half[0], -base_half[1], 0.0, 1.0],
                [base_half[0], base_half[1], 0.0, 1.0],
                [-base_half[0], base_half[1], 0.0, 1.0],
            ],
            dtype=np.float64,
        )
        corners_in_lid = (
            _invert_pose_matrix(lid) @ (base @ corners_local.T)
        ).T[:, :2]
        edge_clearances = lid_half[None, :] - np.abs(corners_in_lid)
        minimum_edge_clearance = float(np.min(edge_clearances))

        def clip_axis(
            polygon: np.ndarray,
            axis: int,
            boundary: float,
            keep_greater: bool,
        ) -> np.ndarray:
            if polygon.size == 0:
                return polygon.reshape(0, 2)
            output: list[np.ndarray] = []
            previous = polygon[-1]
            previous_inside = (
                previous[axis] >= boundary
                if keep_greater
                else previous[axis] <= boundary
            )
            for current in polygon:
                current_inside = (
                    current[axis] >= boundary
                    if keep_greater
                    else current[axis] <= boundary
                )
                if current_inside != previous_inside:
                    denominator = current[axis] - previous[axis]
                    if abs(float(denominator)) > 1e-15:
                        fraction = (boundary - previous[axis]) / denominator
                        output.append(previous + fraction * (current - previous))
                if current_inside:
                    output.append(current)
                previous = current
                previous_inside = current_inside
            return np.asarray(output, dtype=np.float64).reshape(-1, 2)

        overlap = corners_in_lid
        overlap = clip_axis(overlap, 0, -float(lid_half[0]), True)
        overlap = clip_axis(overlap, 0, float(lid_half[0]), False)
        overlap = clip_axis(overlap, 1, -float(lid_half[1]), True)
        overlap = clip_axis(overlap, 1, float(lid_half[1]), False)
        if len(overlap) >= 3:
            overlap_area = 0.5 * abs(
                float(
                    np.dot(overlap[:, 0], np.roll(overlap[:, 1], -1))
                    - np.dot(overlap[:, 1], np.roll(overlap[:, 0], -1))
                )
            )
        else:
            overlap_area = 0.0
        base_area = float(4.0 * base_half[0] * base_half[1])
        coverage_ratio = float(np.clip(overlap_area / base_area, 0.0, 1.0))
        return {
            "full_coverage": bool(
                coverage_ratio > _B05_MIN_COVERAGE_RATIO
            ),
            "coverage_ratio": coverage_ratio,
            "coverage_threshold": _B05_MIN_COVERAGE_RATIO,
            "overlap_area_m2": overlap_area,
            "base_area_m2": base_area,
            "minimum_edge_clearance_m": minimum_edge_clearance,
            "corner_xy_in_lid": corners_in_lid,
            "overlap_polygon_xy_in_lid": overlap,
        }

    def _c01_success_condition_rows(self) -> list[dict[str, Any]]:
        depth = self._c01_nail_depth()
        effective_depth = max(depth, self._c01_max_valid_hit_depth)
        wood = self._pose_for_role("wood")
        table_z = self._current_table_top_z()
        wood_clearance = float(wood[2] - _C01_WOOD_HALF_HEIGHT - table_z)
        return [
            self._condition_row("c01_valid_hit", "锤子确实敲中过钉子", self._c01_had_valid_hit),
            self._condition_row("c01_depth", "钉子已经被敲入足够深", effective_depth >= _C01_SUCCESS_DEPTH),
            self._condition_row("c01_wood_lift", "木板被钉子带起离开桌面", wood_clearance >= _C01_WOOD_LIFT_CLEARANCE),
            self._condition_row(
                "c01_collection_eligible",
                "本轨迹未使用抓取或对准辅助",
                not bool(getattr(self, "_c01_assist_ever_applied", False)),
            ),
        ]

    def _c02_success_condition_rows(self) -> list[dict[str, Any]]:
        marble = self._pose_for_role("target")
        bowl = self._pose_for_role("receptacle")
        marble_inside_bowl = self._c02_marble_inside_bowl(marble, bowl)
        return [
            self._condition_row("c02_spoon_used", "勺子已经被拿起使用", self._c02_spoon_used),
            self._condition_row("c02_spoon_loaded", "勺子里曾经装到弹珠", self._c02_spoon_loaded_seen),
            self._condition_row("c02_over_bowl", "装着弹珠的勺子到过碗上方", self._c02_spoon_over_bowl_seen),
            self._condition_row("c02_marble_in_bowl", "弹珠已经落在碗里", marble_inside_bowl),
            self._condition_row(
                "c02_right_hand_clear",
                "右手没有直接碰到弹珠",
                not bool(self._c02_failed_direct_marble_touch),
            ),
            self._condition_row(
                "c02_left_hand_not_lifting",
                "左手没有把弹珠抓起",
                not bool(self._c02_failed_left_hand_lift),
            ),
        ]

